from functools import lru_cache as _lru_cache


@_lru_cache(maxsize=50000)
def _parse_task_time_str(s):
    for fmt in ("%I:%M:%S %p", "%I:%M %p"):
        try:
            return datetime.strptime(s, fmt)
        except Exception:
            pass
    return None


def parse_task_time(s):
    """Read a task start/end time saved as '07:39:12 PM' (new) or '07:39 PM' (old) — remembered, times repeat a lot"""
    return _parse_task_time_str(str(s).strip())

def task_secs(row):
    """Duration of a task in seconds (exact for new records, whole minutes for old ones)"""
    s = parse_task_time(row.get("start_time",""))
    e = parse_task_time(row.get("end_time",""))
    if s and e:
        diff = (e - s).total_seconds()
        if diff < 0:
            diff += 24*3600   # crossed midnight
        return int(diff)
    try:
        return int(float(row.get("duration_mins",0) or 0) * 60)
    except Exception:
        return 0

def time_sort_key(s):
    """'01:15 PM' must come after '09:30 AM' — sort by the real time, not the text"""
    t = parse_task_time(s)
    return (0, t.time()) if t else (1, datetime.min.time())

def fmt_secs(secs):
    """45 -> '45 secs', 125 -> '2 min 5 secs', 3720 -> '1 hr 2 min'"""
    secs = int(round(secs or 0))
    if secs < 60:
        return f"{secs} secs"
    if secs < 3600:
        m, s = divmod(secs, 60)
        return f"{m} min {s} secs" if s else f"{m} min"
    h, rem = divmod(secs, 3600)
    return f"{h} hr {rem//60} min"

