                # Delete the In Progress duplicate if exists
                task_id = st.session_state.get("purchase_order_task_id")
                if task_id:
                    supabase.table("daily_tasks").delete().eq("id", task_id).execute()
                    st.session_state["purchase_order_task_id"] = None
