def _form_import_file():
    st.caption("Upload the order-schedule file from backend — one area at a time. "
               "Re-uploading the same or a newer file is safe: only new items are added.")
    area = st.selectbox("Which area / store is this file for? *", [SELECT_AREA] + load_areas(), key="imp_area")
    up = st.file_uploader("Backend file (.xlsx or .csv)", type=["xlsx", "xls", "csv"],
                          key=f"imp_file_{st.session_state.get('imp_ver', 0)}")
    if not up:
        show_order_time_guide(expanded=True)
        show_customer_order_format(expanded=False)
        return
    try:
        lines, err = parse_backend_file(up)
    except Exception as e:
        st.error(f"Could not read file: {e}")
        show_customer_order_format(expanded=True)
        return
    if err:
        st.error(err)
        show_customer_order_format(expanded=True)
        return
    if not lines:
        st.warning("No item lines found in this file.")
        return
    n_orders = len(set(l["order_no"] for l in lines))
    n_time = len({l["order_no"] for l in lines if l.get("order_time")})
    st.info(f"📄 File has **{len(lines)} item lines** in **{n_orders} orders** · 🕐 order time found for "
            f"**{n_time} of {n_orders}** orders")
    if n_time < n_orders:
        st.warning("🕐 " + ("This file has no **Order Date / Order Time** columns." if not n_time else
                           f"{n_orders - n_time} order(s) have no order time.")
                   + " Add them with VLOOKUP from the chat sheet (see below), or fill them later in ⏰ Missing order time.")
        show_order_time_guide(expanded=not n_time)
    pf = pd.DataFrame(lines)
    pf["ot"] = [(to_ist(l.get("order_time")).strftime("%d %b %I:%M %p") if l.get("order_time") else "—") for l in lines]
    prev = pf[["scheduled_date", "order_no", "ot", "customer_name", "item_name", "pack_size", "qty"]]
    prev.columns = ["Date", "Order #", "Ordered at", "Customer", "Item", "Pack", "Qty"]
    st.dataframe(prev, hide_index=True, width='stretch', height=250)

    if st.button("📥 Import", type="primary", key="imp_go", width='stretch'):
        if area == SELECT_AREA:
            st.error("Select the area / store for this file first!")
            return
        try:
            res = import_order_lines(lines, area)
        except Exception as e:
            st.error(f"Import failed: {e}")
            return
        st.success(f"✅ **{area}**: {res['new']} new items added · {res['existing']} already imported"
                   + (f" · {res['qty_changed']} qty updated" if res['qty_changed'] else "")
                   + (f" · {res['restored']} restored" if res['restored'] else "")
                   + (f" · 🕐 order time for {res['times']} orders" if res.get("times") else "")
                   + (f" ({res['time_filled']} added to items imported earlier)" if res.get("time_filled") else ""))
        if res.get("no_time_col"):
            st.error("🕐 Order times were NOT saved — one-time setup needed: run this line in Supabase → SQL Editor, "
                     "then import the file again.")
            st.code(ORDER_TIME_SQL, language="sql")
        if res["removed"]:
            st.warning(f"🗑️ {res['removed']} pending item(s) are no longer in the backend file — marked **Removed** (cancelled/changed orders).")
        if res["wrong_area"]:
            st.error("⚠️ These orders were already imported under a DIFFERENT area and were skipped — "
                     "check you selected the right area: " + ", ".join(sorted(set(res["wrong_area"]))[:15]))
        log_simple_task("Order Import", {"area": area, "lines": str(res["new"]),
                                          "file_lines": str(len(lines)), "orders": str(n_orders)})
        st.session_state["imp_ver"] = st.session_state.get("imp_ver", 0) + 1

# ── PURCHASE: PENDING ITEMS ───────────────────────────────────────────────────
DELIVERY_TIMES = [""] + [datetime(2000, 1, 1, h, m).strftime("%I:%M %p") for h in range(7, 24) for m in (0, 30)]

def due_info(line, now=None):
    """(flag, minutes_left, label) from scheduled date + promised delivery time; None if no time"""
    t = (line.get("delivery_time") or "").strip()
    d = (line.get("scheduled_date") or "").strip()
    if not t or not d:
        return None
    try:
        due = IST.localize(datetime.strptime(f"{d} {t}", "%Y-%m-%d %I:%M %p"))
    except Exception:
        return None
    left = int(((due - (now or now_ist())).total_seconds()) // 60)
    flag = "🔴" if left <= 60 else ("🟡" if left <= 180 else "🟢")
    label = f"overdue {fmt_age(-left)}" if left < 0 else f"in {fmt_age(left)}"
    return flag, left, label

def _sched_label(d):
    try:
        return datetime.strptime(d, "%Y-%m-%d").strftime("%d %b")
    except Exception:
        return d or ""

SCHED_PRESETS = ["Overdue + Today", "Last 3 days + Today", "Today", "Tomorrow", "Today + Tomorrow", "Overdue only",
                 "Last 7 days", "All dates", "📅 Choose dates"]

def sched_date_filter(key, lines, container=None, default="Overdue + Today"):
    """Quick scheduled-date filter (like a date-range picker). Returns (filtered lines, short label)."""
    from datetime import timedelta
    box = container or st
    today = today_ist()
    preset = box.selectbox("Scheduled date", SCHED_PRESETS, index=SCHED_PRESETS.index(default), key=f"{key}_preset")
    lo = hi = None                                   # inclusive YYYY-MM-DD bounds (None = open)
    if preset == "Overdue + Today":
        hi = today
    elif preset == "Last 3 days + Today":
        lo, hi = today - timedelta(days=3), today
    elif preset == "Today":
        lo = hi = today
    elif preset == "Tomorrow":
        lo = hi = today + timedelta(days=1)
    elif preset == "Today + Tomorrow":
        lo, hi = today, today + timedelta(days=1)
    elif preset == "Overdue only":
        hi = today - timedelta(days=1)
    elif preset == "Last 7 days":
        lo, hi = today - timedelta(days=6), today
    elif preset == "📅 Choose dates":
        rng = box.date_input("From – to", value=(today, today + timedelta(days=1)), key=f"{key}_range",
                             format="DD/MM/YYYY")
        if isinstance(rng, (list, tuple)) and len(rng) == 2:
            lo, hi = rng
        elif isinstance(rng, (list, tuple)) and len(rng) == 1:
            lo = hi = rng[0]
        else:
            lo = hi = rng
    los = lo.strftime("%Y-%m-%d") if lo else None
    his = hi.strftime("%Y-%m-%d") if hi else None
    out = [l for l in lines
           if (not los or (l.get("scheduled_date") or "") >= los)
           and (not his or ((l.get("scheduled_date") or "9999") <= his))]
    label = preset if preset != "📅 Choose dates" else f"{los}…{his}"
    return out, label

def form_pending_items():
    st.subheader("🧾 Pending Customer Items")
    st.caption("For each item: 🏪 **In Store** (available, nothing to buy) or ❌ **Not Available** (can't be sourced). "
               "Items to buy from a distributor → tick them in **📦 Arrangement Order**. "
               "Set **Deliver by** (time promised to the customer) — it applies to the whole order.")
    try:
        all_lines = get_open_lines(None)
    except Exception as e:
        st.error(f"Could not load items — has the setup SQL been run in Supabase? ({e})")
        return
    c1, c2 = st.columns(2)
    with c1:
        area = st.selectbox("Area", ["All Areas"] + load_areas(), key="pi_area")
    lines = [l for l in all_lines if area == "All Areas" or l.get("area") == area]
    lines, sched = sched_date_filter("pi_sched", lines, c2)
    if not lines:
        st.success("🎉 No pending customer items for this filter!")
        return

    now = now_ist()
    def sort_key(l):
        di = due_info(l, now)
        return (l.get("scheduled_date") or "9999", di[1] if di else 10**9, str(l.get("imported_at") or ""), str(l.get("order_no")))
    lines = sorted(lines, key=sort_key)
    rows = []
    for l in lines:
        a = age_mins(l.get("imported_at"), now)
        di = due_info(l, now)
        rows.append({
            "id": l["id"],
            "⏰": di[0] if di else age_flag(a),
            "Sched": _sched_label(l.get("scheduled_date")),
            "Deliver by": l.get("delivery_time") or "",
            "Due": di[2] if di else "",
            "Age": fmt_age(a),
            "Order #": l.get("order_no", ""),
            "Customer": l.get("customer_name", ""),
            "Area": l.get("area", ""),
            "Item": l.get("item_name", ""),
            "Pack": l.get("pack_size", ""),
            "Qty": _qty_txt(remaining_qty(l)),
            "Status": l.get("status", ""),
            "Action": "—",
        })
    df = pd.DataFrame(rows)
    c1, c2, c3, c4 = st.columns(4)
    with c1: st.metric("Pending Items", len(rows))
    with c2: st.metric("Orders", df["Order #"].nunique())
    with c3: st.metric("🔴 Due within 1 hr / overdue", sum(1 for l in lines if (due_info(l, now) or (None, 10**9))[1] <= 60))
    with c4: st.metric("⏱️ No delivery time set", df[df["Deliver by"] == ""]["Order #"].nunique())

    ver = st.session_state.get("pi_ver", 0)
    edited = st.data_editor(
        df, key=f"pi_editor_{ver}", hide_index=True, width='stretch',
        disabled=[c for c in df.columns if c not in ("Action", "Deliver by")],
        column_config={
            "id": None,
            "Deliver by": st.column_config.SelectboxColumn("Deliver by", options=DELIVERY_TIMES,
                                                           help="Time promised to the customer (whole order)"),
            "Action": st.column_config.SelectboxColumn(
                "Action", options=["—", "🏪 In Store", "❌ Not Available"], required=True),
        })
    st.caption("⏰ with a delivery time: 🔴 due within 1 hr or overdue · 🟡 within 3 hrs · 🟢 later. "
               "Without a time: age since upload.")
    chosen = edited[edited["Action"] != "—"]
    old_time = {r["id"]: r["Deliver by"] for r in rows}
    time_changes = {}
    for _, r in edited.iterrows():
        if (r["Deliver by"] or "") != (old_time.get(r["id"]) or ""):
            time_changes[str(r["Order #"])] = r["Deliver by"] or None
    n_changes = len(chosen) + len(time_changes)
    if st.button(f"💾 Save ({len(chosen)} decision(s), {len(time_changes)} delivery time(s))", type="primary",
                 key="pi_save", disabled=n_changes == 0, width='stretch'):
        by_id = {l["id"]: l for l in lines}
        n_store = n_na = 0
        now_s = now_iso()
        try:
            for order_no, t in time_changes.items():
                supabase.table("customer_order_lines").update({"delivery_time": t})\
                    .eq("order_no", order_no).eq("removed", False).execute()
            for _, r in chosen.iterrows():
                line = by_id.get(int(r["id"]))
                if not line:
                    continue
                decision = "In Store" if "In Store" in r["Action"] else "Not Available"
                if line.get("status") == "Partly Arranged":
                    supabase.table("customer_order_lines").update({
                        "remainder_note": decision, "decided_by": st.session_state.name,
                        "decided_at": now_s}).eq("id", line["id"]).execute()
                    refresh_line_status(line["id"])
                else:
                    supabase.table("customer_order_lines").update({
                        "status": decision, "decided_by": st.session_state.name,
                        "decided_at": now_s, "completed_at": now_s}).eq("id", line["id"]).execute()
                if decision == "In Store":
                    n_store += 1
                else:
                    n_na += 1
            if n_store + n_na:
                log_simple_task("Customer Items Check", {"area": area, "lines": str(n_store + n_na),
                                                         "in_store": str(n_store), "not_available": str(n_na)})
            st.session_state["pi_ver"] = ver + 1
            st.success(f"✅ Saved: {n_store} In Store · {n_na} Not Available · {len(time_changes)} delivery time(s)")
            st.rerun()
        except Exception as e:
            st.error(f"Error: {e} — has delivery_time_setup.sql been run in Supabase?")

# ── ARRANGEMENT FORM: pick customer lines ────────────────────────────────────
LINE_DECISIONS = ["", "🏪 In Store", "❌ Not Available"]

def save_line_decisions(decisions, time_changes, by_id, area):
    """In Store / Not Available decisions + promised delivery times (whole order). -> (n_store, n_na)"""
    now_s = now_iso()
    n_store = n_na = 0
    for order_no, t in time_changes.items():
        supabase.table("customer_order_lines").update({"delivery_time": t}).eq("order_no", order_no).eq("removed", False).execute()
    for line_id, dec in decisions:
        line = by_id.get(line_id)
        if not line:
            continue
        decision = "In Store" if "In Store" in dec else "Not Available"
        if line.get("status") == "Partly Arranged":
            supabase.table("customer_order_lines").update({
                "remainder_note": decision, "decided_by": st.session_state.name, "decided_at": now_s}).eq("id", line_id).execute()
            refresh_line_status(line_id)
        else:
            supabase.table("customer_order_lines").update({
                "status": decision, "decided_by": st.session_state.name,
                "decided_at": now_s, "completed_at": now_s}).eq("id", line_id).execute()
        if decision == "In Store":
            n_store += 1
        else:
            n_na += 1
    if n_store + n_na:
        log_simple_task("Customer Items Check", {"area": area, "lines": str(n_store + n_na),
                                                 "in_store": str(n_store), "not_available": str(n_na)})
    return n_store, n_na

def arrangement_line_picker():
    """Customer items of an area: decide each one here — tick to order from this distributor, or mark In Store /
    Not Available, and set the delivery time. Returns (area, [rows ticked to order])"""
    ver = st.session_state.get("arr_link_ver", 0)
    with st.expander("🧾 Customer order items — decide each medicine here", expanded=True):
        msg = st.session_state.pop("arr_dec_msg", None)
        if msg:
            st.success(msg)
        fc1, fc2 = st.columns(2)
        with fc1:
            a_opts = [SELECT_AREA] + load_areas()
            last = st.session_state.get("arr_last_area")
            link_area = st.selectbox("Area of customer orders", a_opts, key=f"arr_link_area_{ver}",
                                     index=a_opts.index(last) if last in a_opts else 0)
            st.session_state["arr_last_area"] = link_area
        if link_area == SELECT_AREA:
            st.caption("Select an area to see its pending customer items. (Or skip this and just enter the number of medicines below.)")
            return None, []
        try:
            open_lines = get_open_lines(link_area)
        except Exception as e:
            st.warning(f"Could not load customer items ({e})")
            return None, []
        if not open_lines:
            st.success("🎉 No pending customer items for this area.")
            return link_area, []
        open_lines, pick_date = sched_date_filter(f"arr_link_date_{ver}", open_lines, fc2)
        if not open_lines:
            st.info("No pending customer items for this date.")
            return link_area, []
        now = now_ist()
        bounced = {}
        try:
            for b in supabase.table("bounce_items").select("line_id,distributor,qty_missing").eq("status", "Re-order")\
                    .in_("line_id", [l["id"] for l in open_lines]).execute().data or []:
                bounced.setdefault(b["line_id"], []).append(b)
        except Exception:
            pass
        m = st.columns(4)
        with m[0]: st.metric("Pending items", len(open_lines))
        with m[1]: st.metric("Orders", len({l.get("order_no") for l in open_lines}))
        with m[2]: st.metric("🔴 Due ≤ 1 hr / overdue", sum(1 for l in open_lines if (due_info(l, now) or (None, 10**9))[1] <= 60))
        with m[3]: st.metric("⏱️ No delivery time", len({l.get("order_no") for l in open_lines if not l.get("delivery_time")}))
        if bounced:
            n_store = sum(1 for bs in bounced.values() if all(b["distributor"] == "In Store (not found)" for b in bs))
            parts = ([f"{len(bounced) - n_store} bounced by a distributor"] if len(bounced) > n_store else []) + \
                    ([f"{n_store} not found in store"] if n_store else [])
            st.warning(f"🔁 {' · '.join(parts)} — shown at the top. Order them from a distributor.")
        open_lines = sorted(open_lines, key=lambda l: (l["id"] not in bounced, l.get("scheduled_date") or "9999",
                                                       (due_info(l, now) or (None, 10**9))[1],
                                                       str(l.get("imported_at") or ""), str(l.get("order_no"))))
        rows = []
        _k = st.session_state.get("arr_keep_ticks") or {}       # ticks survive a 💾 Save of times / In Store
        keep = _k.get("ticks", {}) if _k.get("ver") == ver else {}
        for l in open_lines:
            di = due_info(l, now)
            rows.append({
                "id": l["id"],
                "Order?": l["id"] in keep,
                "Not ordering?": "",
                "⏰": di[0] if di else age_flag(age_mins(l.get("imported_at"), now)),
                "Date": _sched_label(l.get("scheduled_date")),
                "Deliver by": l.get("delivery_time") or "",
                "Due": di[2] if di else "",
                "🔁": (("🔴 not found in store" if all(b["distributor"] == "In Store (not found)" for b in bounced[l["id"]])
                    else "bounced by " + ", ".join(sorted({b["distributor"] for b in bounced[l["id"]]}))) if l["id"] in bounced else ""),
                "Order #": l.get("order_no", ""),
                "Customer": l.get("customer_name", ""),
                "Item": l.get("item_name", ""),
                "Pack": l.get("pack_size", ""),
                "Needed": remaining_qty(l),
                "Order Qty": keep.get(l["id"], remaining_qty(l)),
            })
        ldf = pd.DataFrame(rows)
        if not ldf["🔁"].astype(bool).any():
            ldf = ldf.drop(columns=["🔁"])
        ed = st.data_editor(
            ldf, key=f"arr_link_editor_{ver}_{link_area}_{pick_date}", hide_index=True, width='stretch',
            disabled=[c for c in ldf.columns if c not in ("Order?", "Not ordering?", "Deliver by", "Order Qty")],
            column_config={
                "id": None,
                "Order?": st.column_config.CheckboxColumn("Order?", help="Tick items you are ordering from this distributor"),
                "Not ordering?": st.column_config.SelectboxColumn(
                    "Not ordering?", options=LINE_DECISIONS,
                    help="🏪 In Store = available, nothing to buy · ❌ Not Available = can't be sourced"),
                "Deliver by": st.column_config.SelectboxColumn("Deliver by", options=DELIVERY_TIMES,
                                                               help="Time promised to the customer (whole order)"),
                "Order Qty": st.column_config.NumberColumn("Order Qty", min_value=0, step=1,
                                                           help="Change only if this item is split between 2 distributors"),
            })
        st.caption("⏰ with a delivery time: 🔴 due within 1 hr or overdue · 🟡 within 3 hrs · 🟢 later. Without a time: age since upload.")
        recs = ed.to_dict("records")
        picked = [r for r in recs if r["Order?"]]
        decisions = [(int(r["id"]), r["Not ordering?"]) for r in recs if r["Not ordering?"]]
        old_time = {r["id"]: r["Deliver by"] for r in rows}
        time_changes = {}
        for r in recs:
            if (r["Deliver by"] or "") != (old_time.get(r["id"]) or ""):
                time_changes[str(r["Order #"])] = r["Deliver by"] or None
        both = [r["Item"] for r in recs if r["Order?"] and r["Not ordering?"]]
        if both:
            st.error("Ticked to order AND marked not ordering — pick one: " + ", ".join(both[:10]))
            picked = []
        if decisions or time_changes:
            n_s = sum(1 for _, d in decisions if "In Store" in d)
            if st.button(f"💾 Save {n_s} In Store · {len(decisions) - n_s} Not Available · {len(time_changes)} delivery time(s)",
                         key=f"arr_dec_save_{ver}", disabled=bool(both)):
                try:
                    ns, nn = save_line_decisions(decisions, time_changes, {l["id"]: l for l in open_lines}, link_area)
                except Exception as e:
                    st.error(f"Error: {e}")
                else:
                    st.session_state["arr_link_ver"] = ver + 1
                    st.session_state["arr_keep_ticks"] = {"ver": ver + 1, "ticks": {int(r["id"]): r["Order Qty"] for r in picked}}
                    st.session_state["arr_dec_msg"] = f"✅ Saved: {ns} In Store · {nn} Not Available · {len(time_changes)} delivery time(s)"
                    st.rerun()
        if picked:
            st.success(f"✅ {len(picked)} item(s) ticked to order — fill the arrangement form below")
        undo_line_decisions(f"arr_u{ver}", link_area)
        return link_area, picked

def save_arrangement_links(arr_id, arr_no, distributor, area, picked):
    now_s = now_iso()
    for p in picked:
        qty = min(_to_float(p.get("Order Qty"), 0), _to_float(p.get("Needed"), 0))
        if qty <= 0:
            continue
        supabase.table("arrangement_lines").insert({
            "arrangement_id": arr_id, "arrangement_no": arr_no, "distributor": distributor,
            "area": area, "line_id": int(p["id"]), "order_no": str(p.get("Order #", "")),
            "item_name": p.get("Item", ""), "qty_ordered": qty, "status": "Ordered",
            "ordered_by": st.session_state.name, "ordered_at": now_s
        }).execute()
        refresh_line_status(int(p["id"]))
        try:
            supabase.table("bounce_items").update({"status": "Re-ordered", "reordered_at": now_s,
                                                   "reordered_arrangement_no": arr_no})\
                .eq("line_id", int(p["id"])).eq("status", "Re-order").execute()
        except Exception:
            pass
    st.session_state["arr_link_ver"] = st.session_state.get("arr_link_ver", 0) + 1

# ── STOCK: CONFIRM CUSTOMER ITEMS (inside Bill Cross Check) ───────────────────
def customer_items_editor(arr):
    """Show customer items linked to this ARR; returns the edited table (or None)"""
    try:
        als = supabase.table("arrangement_lines").select("*")\
            .eq("arrangement_no", str(arr.get("arrangement_no",""))).eq("status", "Ordered").execute().data or []
    except Exception:
        return None
    als = [a for a in als if max(0.0, _to_float(a.get("qty_ordered"), 0) - _to_float(a.get("qty_bounced"), 0)) > 0]
    if not als:
        return None
    st.markdown(f"🧾 **Customer order items in this arrangement ({len(als)})** — change *Received* only if less arrived")
    st.caption("Short, wrong, damaged or near-expiry: enter only the GOOD qty in *Received* and pick the Issue — "
               "it goes to the purchase team to verify and re-order.")
    df = pd.DataFrame([{
        "id": a["id"], "line_id": a.get("line_id"),
        "Order #": a.get("order_no", ""), "Item": a.get("item_name", ""),
        "Ordered": max(0.0, _to_float(a.get("qty_ordered"), 0) - _to_float(a.get("qty_bounced"), 0)),
        "Received": max(0.0, _to_float(a.get("qty_ordered"), 0) - _to_float(a.get("qty_bounced"), 0)),
        "Issue": "",
    } for a in als])
    return st.data_editor(df, key=f"bc_cust_{arr.get('id','')}", hide_index=True, width='stretch',
                          disabled=["Order #", "Item", "Ordered"],
                          column_config={"id": None, "line_id": None,
                                         "Received": st.column_config.NumberColumn("Received", min_value=0, step=1),
                                         "Issue": st.column_config.SelectboxColumn("Issue (if short)",
                                                                                   options=[""] + BOUNCE_ISSUES)})

def save_customer_receipts(ed):
    """Save received qty for each customer item: full = Received, less = Short"""
    now_s = now_iso()
    n_ok = n_short = 0
    for _, r in ed.iterrows():
        rec = _to_float(r["Received"], 0)
        status = "Received" if rec >= _to_float(r["Ordered"], 0) else "Short"
        if status == "Short":
            try:
                al = supabase.table("arrangement_lines").select("*").eq("id", int(r["id"])).execute().data or [{}]
                al = al[0]
                _bounce_insert([{
                    "arrangement_id": al.get("arrangement_id"), "arrangement_no": al.get("arrangement_no"),
                    "distributor": al.get("distributor"), "area": al.get("area"), "stage": "Warehouse",
                    "arr_line_id": int(r["id"]), "line_id": al.get("line_id"), "medicine_name": r["Item"],
                    "order_no": r["Order #"], "qty_ordered": _to_float(r["Ordered"], 0),
                    "qty_missing": _to_float(r["Ordered"], 0) - rec, "issue": r.get("Issue") or "Short / not given",
                    "status": "To verify", "reported_by": st.session_state.name, "reported_at": now_s}])
            except Exception:
                pass                                   # bounce table not created yet -> behaves as before
        supabase.table("arrangement_lines").update({
            "qty_received": rec, "status": status,
            "received_by": st.session_state.name, "received_at": now_s
        }).eq("id", int(r["id"])).execute()
        if r.get("line_id") is not None and str(r.get("line_id")) != "nan":
            refresh_line_status(int(r["line_id"]))
        if status == "Received":
            n_ok += 1
        else:
            n_short += 1
    return n_ok, n_short

# ── BOUNCED / SHORT MEDICINES → PURCHASE VERIFIES → RE-ORDER ──────────────────
# Stages: "Invoice" (purchase, direct) · "Pickup" (delivery pilot got less → purchase checks photo, direct)
#         "Warehouse" (stock reports at Bill Cross Check → purchase verifies)
# Confirmed bounce on a customer item -> arrangement_lines.qty_bounced += qty -> the customer item re-opens
# with only the missing qty and shows up again (🔁) in the Arrangement Order item list.
BOUNCE_ISSUES = ["Short / not given", "Out of stock", "Not in invoice", "Wrong medicine", "Damaged",
                 "Near expiry", "Rate issue", "Other"]
BOUNCE_DISMISS = ["Received later", "Found in store", "Customer cancelled", "Found in store", "Not needed", "Stock team mistake", "Other"]
BOUNCE_SQL = "run **bounce_setup.sql** in Supabase"

def _eff_ordered(a):
    """qty still expected from this arrangement line (ordered minus confirmed bounces)"""
    return max(0.0, _to_float(a.get("qty_ordered"), 0) - _to_float(a.get("qty_bounced"), 0))

def _bounce_insert(rows):
    if rows:
        return supabase.table("bounce_items").insert(rows).execute().data or []
    return []

def apply_bounce(b):
    """Purchase confirmed: take the missing qty off the arrangement line and re-open the customer item"""
    if b.get("stage") == "Store" and b.get("line_id"):
        reopen_store_line(int(b["line_id"]))
        return
    if not b.get("arr_line_id"):
        return
    al = supabase.table("arrangement_lines").select("*").eq("id", b["arr_line_id"]).execute().data
    if not al:
        return
    al = al[0]
    newb = min(_to_float(al.get("qty_ordered"), 0), _to_float(al.get("qty_bounced"), 0) + _to_float(b.get("qty_missing"), 0))
    supabase.table("arrangement_lines").update({"qty_bounced": newb}).eq("id", al["id"]).execute()
    if al.get("line_id"):
        refresh_line_status(int(al["line_id"]))

def _arr_lines(arr_no):
    return supabase.table("arrangement_lines").select("*").eq("arrangement_no", str(arr_no)).execute().data or []

def bounce_editor(arr, stage, kp, direct=True):
    """Medicines of one arrangement with a 'Missing qty' column. direct=True (purchase) -> goes for re-order now.
    Returns number of items saved (0 if nothing saved)."""
    try:
        als = [a for a in _arr_lines(arr.get("arrangement_no")) if _eff_ordered(a) > 0]
    except Exception as e:
        st.error(f"Could not load medicines ({e})")
        return 0
    ver = st.session_state.get(f"{kp}_ver", 0)
    ed = None
    if als:
        df = pd.DataFrame([{"id": a["id"], "Medicine": a.get("item_name", ""), "Customer order": a.get("order_no", ""),
                            "Ordered": _eff_ordered(a), "Missing qty": 0.0, "Issue": ""} for a in als])
        ed = st.data_editor(df, key=f"{kp}_ed_{ver}", hide_index=True, width='stretch',
                            disabled=["Medicine", "Customer order", "Ordered"],
                            column_config={"id": None,
                                           "Missing qty": st.column_config.NumberColumn("Missing qty ✏️", min_value=0, step=1),
                                           "Issue": st.column_config.SelectboxColumn("Issue", options=[""] + BOUNCE_ISSUES)})
    else:
        st.caption("No customer items are linked to this arrangement — type the missing medicines below.")
    other = st.text_area("Other missing medicines (not in the list) — one per line: name - qty", key=f"{kp}_other_{ver}",
                         placeholder="Dolo 650 Tablet - 2", height=70)
    note = st.text_input("Note (optional)", key=f"{kp}_note_{ver}")
    picked = [] if ed is None else [r for r in ed.to_dict("records") if _to_float(r["Missing qty"], 0) > 0]
    extra = []
    for ln in other.splitlines():
        if ln.strip():
            name, _, q = ln.rpartition(" - ") if " - " in ln else (ln, "", "1")
            extra.append((name.strip(), _to_float(q, 1) or 1))
    n = len(picked) + len(extra)
    label = "🔁 Send for re-order" if direct else "📤 Report to purchase team"
    if not st.button(f"{label} ({n})", type="primary", key=f"{kp}_go_{ver}", disabled=n == 0, width='stretch'):
        return 0
    by_id = {a["id"]: a for a in als}
    bad = [r["Medicine"] for r in picked if _to_float(r["Missing qty"], 0) > r["Ordered"]]
    if bad:
        st.error("Missing qty is more than ordered: " + ", ".join(bad))
        return 0
    now_s = now_iso()
    base = {"arrangement_id": arr.get("id"), "arrangement_no": str(arr.get("arrangement_no", "")),
            "distributor": arr.get("distributor", ""), "area": arr.get("area", ""), "stage": stage,
            "reported_by": st.session_state.name, "reported_at": now_s, "note": note or None,
            "status": "Re-order" if direct else "To verify"}
    if direct:
        base.update({"verified_by": st.session_state.name, "verified_at": now_s})
    rows = []
    for r in picked:
        a = by_id[r["id"]]
        rows.append({**base, "arr_line_id": a["id"], "line_id": a.get("line_id"), "medicine_name": a.get("item_name", ""),
                     "order_no": a.get("order_no", ""), "qty_ordered": r["Ordered"],
                     "qty_missing": _to_float(r["Missing qty"], 0), "issue": r["Issue"] or "Short / not given"})
    for name, q in extra:
        rows.append({**base, "arr_line_id": None, "line_id": None, "medicine_name": name, "order_no": "",
                     "qty_ordered": None, "qty_missing": q, "issue": "Short / not given"})
    try:
        saved = _bounce_insert(rows)
        if direct:
            for b in saved:
                apply_bounce(b)
        log_simple_task("Bounce Reported", {"arrangement_no": base["arrangement_no"], "stage": stage,
                                            "items": str(len(rows)), "direct": "Yes" if direct else "No"})
    except Exception as e:
        st.error(f"Could not save — {BOUNCE_SQL}. ({e})")
        return 0
    st.session_state[f"{kp}_ver"] = ver + 1
    return len(rows)

def _short_pickups(days=3):
    """Completed pickups where the delivery pilot received fewer SKUs than ordered and purchase hasn't checked yet"""
    since = (today_ist() - timedelta(days=days)).strftime("%Y-%m-%d")
    rows = supabase.table("daily_tasks").select("*").eq("task_type", "Pickup").gte("date", since)\
        .order("id", desc=True).execute().data or []
    rows = [p for p in rows if p.get("status") != "In Progress" and not (p.get("details") or {}).get("bounce_checked")
            and (p.get("details") or {}).get("arrangement_no")]
    # pickups saved before 'no_sku_ordered' existed -> use the arrangement's medicine count
    need = list({p["details"]["arrangement_no"] for p in rows if not str(p["details"].get("no_sku_ordered") or "").strip()})
    arr_cnt = {}
    if need:
        arr_cnt = {a.get("arrangement_no"): a.get("no_medicines") for a in
                   (supabase.table("arrangements").select("arrangement_no,no_medicines").in_("arrangement_no", need).execute().data or [])}
    out = []
    for p in rows:
        d = p.get("details") or {}
        got, want = d.get("no_sku_received"), d.get("no_sku_ordered") or arr_cnt.get(d.get("arrangement_no"))
        if want and not d.get("no_sku_ordered"):
            p["details"] = {**d, "no_sku_ordered": str(want)}
        if str(got).strip() and str(want).strip() and _to_float(got) < _to_float(want):
            out.append(p)
    return out

def bounce_counts():
    """(to verify, short pickups to check, waiting re-order) — for badges"""
    try:
        b = supabase.table("bounce_items").select("id,status,line_id").in_("status", ["To verify", "Re-order"]).execute().data or []
    except Exception:
        return 0, 0, 0
    try:
        sp = len(_short_pickups())
    except Exception:
        sp = 0
    return sum(1 for x in b if x["status"] == "To verify"), sp, sum(1 for x in b if x["status"] == "Re-order")

def _mark_pickup_checked(p, n):
    d = dict(p.get("details") or {})
    d.update({"bounce_checked": True, "bounce_checked_by": st.session_state.name, "bounce_items": str(n)})
    supabase.table("daily_tasks").update({"details": d}).eq("id", p["id"]).execute()

def form_bounce_center():
    st.subheader("🔁 Bounced / Short Medicines")
    st.caption("Everything that did not come from the distributor. Confirm it here and the missing qty goes back to "
               "**📦 Arrangement Order** (marked 🔁) to order from another distributor.")
    try:
        supabase.table("bounce_items").select("id").limit(1).execute()
    except Exception as e:
        st.error(f"Bounce table not found — {BOUNCE_SQL}. ({e})")
        return
    msg = st.session_state.pop("bc_msg", None)
    if msg:
        st.success(msg)
    n_ver, n_sp, n_re = bounce_counts()
    tabs = st.tabs([f"🏭 Stock team reports ({n_ver})", f"🚚 Short pickups ({n_sp})", "🧾 Invoice shortage",
                    f"🔁 Waiting re-order ({n_re})", "📊 Report"])

    # 1) stock team reports -> verify
    with tabs[0]:
        rows = supabase.table("bounce_items").select("*").eq("status", "To verify").order("id").execute().data or []
        if not rows:
            st.success("Nothing to verify.")
        else:
            st.caption("Reported by the stock team — at Bill Cross Check (short from distributor) or while picking "
                       "In Store items (not found on the shelf). Check, then confirm (→ goes back for ordering) or dismiss.")
            df = pd.DataFrame([{"id": b["id"], "Action": "—", "Dismiss reason": "", "Stage": "🏪 Not found in store" if b.get("stage") == "Store" else "🏭 Bill check",
                                "Arrangement": b.get("arrangement_no") or "",
                                "Distributor": b.get("distributor"), "Medicine": b.get("medicine_name"),
                                "Customer order": b.get("order_no") or "", "Ordered": _qty_txt(b.get("qty_ordered")),
                                "Missing": _qty_txt(b.get("qty_missing")), "Issue": b.get("issue"),
                                "Reported by": b.get("reported_by"), "Note": b.get("note") or "",
                                "When": (to_ist(b.get("reported_at")) or now_ist()).strftime("%d %b %I:%M %p")} for b in rows])
            ver = st.session_state.get("bv_ver", 0)
            ed = st.data_editor(df, key=f"bv_ed_{ver}", hide_index=True, width='stretch',
                                disabled=[c for c in df.columns if c not in ("Action", "Dismiss reason")],
                                column_config={"id": None,
                                               "Action": st.column_config.SelectboxColumn(
                                                   "Action", options=["—", "✅ Confirm → re-order", "❌ Dismiss"], required=True),
                                               "Dismiss reason": st.column_config.SelectboxColumn("Dismiss reason", options=[""] + BOUNCE_DISMISS)})
            chosen = [r for r in ed.to_dict("records") if r["Action"] != "—"]
            if st.button(f"💾 Save ({len(chosen)})", type="primary", key="bv_save", disabled=not chosen, width='stretch'):
                bad = [r["Medicine"] for r in chosen if r["Action"].startswith("❌") and not r["Dismiss reason"]]
                if bad:
                    st.error("Pick a dismiss reason for: " + ", ".join(bad))
                else:
                    by_id = {b["id"]: b for b in rows}
                    now_s = now_iso()
                    nc = nd = 0
                    for r in chosen:
                        b = by_id[r["id"]]
                        if r["Action"].startswith("✅"):
                            supabase.table("bounce_items").update({"status": "Re-order", "verified_by": st.session_state.name,
                                                                   "verified_at": now_s}).eq("id", b["id"]).execute()
                            apply_bounce(b)
                            nc += 1
                        else:
                            supabase.table("bounce_items").update({"status": "Dismissed", "verified_by": st.session_state.name,
                                                                   "verified_at": now_s, "dismiss_reason": r["Dismiss reason"]})\
                                .eq("id", b["id"]).execute()
                            if b.get("stage") == "Store" and b.get("line_id"):      # stays In Store -> stock picks again
                                supabase.table("customer_order_lines").update({"store_check": None}).eq("id", b["line_id"]).execute()
                            nd += 1
                    st.session_state["bv_ver"] = ver + 1
                    st.session_state["bc_msg"] = f"✅ {nc} sent for re-order · {nd} dismissed"
                    st.rerun()

    # 2) short pickups -> check photo, tick missing
    with tabs[1]:
        try:
            sps = _short_pickups()
        except Exception as e:
            st.error(f"Error: {e}")
            sps = []
        if not sps:
            st.success("No short pickups to check.")
        arr_by_no = {}
        if sps:
            nos = list({(p.get("details") or {}).get("arrangement_no") for p in sps})
            arr_by_no = {a.get("arrangement_no"): a for a in
                         (supabase.table("arrangements").select("*").in_("arrangement_no", nos).execute().data or [])}
        for p in sps:
            d = p.get("details") or {}
            arr = arr_by_no.get(d.get("arrangement_no")) or {"arrangement_no": d.get("arrangement_no"),
                                                           "distributor": d.get("distributor")}
            with st.expander(f"⚠️ #{d.get('arrangement_no')} | {d.get('distributor','')} | {p.get('person','')} | "
                             f"received {d.get('no_sku_received')} of {d.get('no_sku_ordered')} medicines", expanded=True):
                if d.get("remarks"):
                    st.info(f"💬 Delivery pilot's remark: {d['remarks']}")
                c1, c2 = st.columns(2)
                with c1:
                    st.markdown("**📋 Ordered**")
                    if not show_image(arr.get("order_image", ""), key=f"bsp_o_{p['id']}"):
                        st.caption("No order image")
                with c2:
                    st.markdown(f"**🚚 Picked up by {p.get('person','')}**")
                    if not show_image(d.get("medicine_image", ""), key=f"bsp_p_{p['id']}"):
                        st.caption("No pickup image")
                st.markdown("**Enter the missing qty for medicines not received:**")
                n = bounce_editor(arr, "Pickup", f"bsp_{p['id']}", direct=True)
                if n:
                    _mark_pickup_checked(p, n)
                    st.session_state["bc_msg"] = f"✅ #{d.get('arrangement_no')}: {n} medicine(s) sent for re-order"
                    st.rerun()
                if st.button("👍 Checked — nothing to re-order", key=f"bsp_ok_{p['id']}"):
                    _mark_pickup_checked(p, 0)
                    st.rerun()

    # 3) invoice shortage (purchase)
    with tabs[2]:
        invoice_shortage_picker("bis")

    # 4) waiting re-order
    with tabs[3]:
        rows = supabase.table("bounce_items").select("*").eq("status", "Re-order").order("id").execute().data or []
        if not rows:
            st.success("Nothing waiting — all bounced medicines are re-ordered.")
        else:
            now = now_ist()
            st.caption("Customer items are already back in **📦 Arrangement Order** (🔁 at the top) — they clear from here "
                       "automatically when you tick them in a new arrangement. Medicines without a customer order: "
                       "place the order, then mark them re-ordered here.")
            st.dataframe(pd.DataFrame([{
                "Medicine": b.get("medicine_name"), "Missing": _qty_txt(b.get("qty_missing")),
                "Bounced by": b.get("distributor"), "Arrangement": b.get("arrangement_no"), "Stage": b.get("stage"),
                "Issue": b.get("issue"), "Waiting": fmt_age(age_mins(b.get("verified_at") or b.get("reported_at"), now)),
                "Customer order": b.get("order_no") or "— stock item —"} for b in rows]), hide_index=True, width='stretch')
            manual = [b for b in rows if not b.get("line_id")]
            if manual:
                opts = {f"{b.get('medicine_name')} — {_qty_txt(b.get('qty_missing'))} (bounced by {b.get('distributor')})": b
                        for b in manual}
                sel = st.multiselect("Stock items you have re-ordered", list(opts), key="bre_sel")
                new_arr = st.text_input("New arrangement no (optional)", key="bre_arr")
                if st.button("✅ Mark re-ordered", key="bre_go", disabled=not sel):
                    for k in sel:
                        supabase.table("bounce_items").update({"status": "Re-ordered", "reordered_at": now_iso(),
                                                               "reordered_arrangement_no": new_arr or None})\
                            .eq("id", opts[k]["id"]).execute()
                    st.rerun()

    # 5) report
    with tabs[4]:
        days = st.selectbox("Period", [7, 30, 90], format_func=lambda d: f"Last {d} days", key="brep_days")
        since = (now_ist() - timedelta(days=days)).isoformat()
        rows = supabase.table("bounce_items").select("*").gte("reported_at", since).execute().data or []
        rows = [b for b in rows if b.get("status") != "Dismissed"]
        if not rows:
            st.info("No bounces in this period.")
        else:
            df = pd.DataFrame(rows)
            c1, c2 = st.columns(2)
            with c1:
                st.markdown("**By distributor**")
                g = df.groupby("distributor").agg(Bounces=("id", "count"), Qty=("qty_missing", "sum")).sort_values("Bounces", ascending=False)
                st.dataframe(g, width='stretch')
            with c2:
                st.markdown("**By stage**")
                st.dataframe(df.groupby("stage").agg(Bounces=("id", "count")).sort_values("Bounces", ascending=False), width='stretch')
            st.markdown("**Most bounced medicines**")
            st.dataframe(df.groupby("medicine_name").agg(Bounces=("id", "count"),
                                                         Distributors=("distributor", lambda x: ", ".join(sorted(set(x)))))
                         .sort_values("Bounces", ascending=False).head(20), width='stretch')

def invoice_shortage_picker(kp):
    """Purchase: the invoice came with fewer medicines -> pick the arrangement, enter what's missing"""
    st.caption("Invoice from the distributor has fewer medicines than you ordered? Pick the arrangement and enter the "
               "missing qty — it goes straight back for re-order.")
    since = (today_ist() - timedelta(days=5)).strftime("%Y-%m-%d")
    try:
        arrs = supabase.table("arrangements").select("*").gte("order_placed_date", since).order("id", desc=True).execute().data or []
    except Exception as e:
        st.error(f"Error: {e}")
        return
    if not arrs:
        st.info("No arrangements in the last 5 days.")
        return
    opts = {f"#{a.get('arrangement_no')} — {a.get('distributor')} — {a.get('area','')} — {arr_ref_text(a)}": a for a in arrs}
    sel = st.selectbox("Arrangement", ["—"] + list(opts), key=f"{kp}_arr")
    if sel == "—":
        return
    n = bounce_editor(opts[sel], "Invoice", f"{kp}_{opts[sel]['id']}", direct=True)
    if n:
        st.session_state["bc_msg"] = f"✅ {n} medicine(s) sent for re-order"
        st.rerun()

# ── IN-STORE CHECK: stock team picks / reports, purchase team decides ─────────
STORE_SQL = "run **store_check_setup.sql** in Supabase"

def _store_qty(l):
    """qty the customer needs from our own store"""
    if l.get("status") == "In Store":
        return _to_float(l.get("qty"), 0)
    return max(0.0, _to_float(l.get("qty"), 0) - _to_float(l.get("qty_arranged"), 0))   # remainder marked In Store

def in_store_to_check(area=None):
    """In Store customer items not yet checked by the stock team"""
    q = supabase.table("customer_order_lines").select("*").eq("removed", False).is_("store_check", "null")
    if area and area not in ("All Areas", SELECT_AREA):
        q = q.eq("area", area)
    rows = q.execute().data or []
    return [l for l in rows if l.get("status") == "In Store" or
            (l.get("status") == "Partly Arranged" and l.get("remainder_note") == "In Store")]

def count_store_to_check(area=None):
    try:
        return len(in_store_to_check(area))
    except Exception:
        return 0

def form_store_check():
    st.subheader("🏪 In-Store items to pick")
    st.caption("Customer medicines the purchase team marked **In Store**. Pick each one from the shelf: "
               "✅ **Picked** if you have it, ❌ **Not found** if it is not there — the purchase team will then order it.")
    area = st.selectbox("Area", ["All Areas"] + load_areas(), key="sc_area",
                        index=(["All Areas"] + load_areas()).index(st.session_state.get("work_area"))
                        if st.session_state.get("work_area") in load_areas() else 0)
    try:
        lines = in_store_to_check(area)
    except Exception as e:
        st.error(f"Could not load — {STORE_SQL}. ({e})")
        return
    msg = st.session_state.pop("sc_msg", None)
    if msg:
        st.success(msg)
    if not lines:
        st.success("🎉 Nothing to pick — every In Store item is checked.")
        return
    now = now_ist()
    lines.sort(key=lambda l: (l.get("scheduled_date") or "9999", (due_info(l, now) or (None, 10**9))[1], str(l.get("order_no"))))
    rows = [{"id": l["id"], "Result": "—", "⏰": (due_info(l, now) or (age_flag(age_mins(l.get("imported_at"), now)),))[0],
             "Date": _sched_label(l.get("scheduled_date")), "Deliver by": l.get("delivery_time") or "",
             "Order #": l.get("order_no", ""), "Customer": l.get("customer_name", ""), "Area": l.get("area", ""),
             "Medicine": l.get("item_name", ""), "Pack": l.get("pack_size", ""), "Qty": _qty_txt(_store_qty(l)),
             "Marked by": l.get("decided_by") or "", "Note": ""} for l in lines]
    st.metric("To pick", len(rows))
    ver = st.session_state.get("sc_ver", 0)
    ed = st.data_editor(pd.DataFrame(rows), key=f"sc_ed_{ver}", hide_index=True, width='stretch',
                        disabled=[c for c in rows[0] if c not in ("Result", "Note")],
                        column_config={"id": None,
                                       "Result": st.column_config.SelectboxColumn(
                                           "Result", options=["—", "✅ Picked", "❌ Not found"], required=True),
                                       "Note": st.column_config.TextColumn("Note", help="e.g. only 1 strip found, expired, damaged")})
    chosen = [r for r in ed.to_dict("records") if r["Result"] != "—"]
    n_nf = sum(1 for r in chosen if r["Result"].startswith("❌"))
    if not st.button(f"💾 Save ({len(chosen) - n_nf} picked · {n_nf} not found)", type="primary", key="sc_save",
                     disabled=not chosen, width='stretch'):
        return
    by_id = {l["id"]: l for l in lines}
    now_s = now_iso()
    try:
        for r in chosen:
            l = by_id[r["id"]]
            found = r["Result"].startswith("✅")
            supabase.table("customer_order_lines").update({
                "store_check": "Picked" if found else "Not found", "store_checked_by": st.session_state.name,
                "store_checked_at": now_s, "store_note": r["Note"] or None}).eq("id", l["id"]).execute()
            if not found:
                _bounce_insert([{
                    "arrangement_no": "", "distributor": "In Store (not found)", "area": l.get("area"), "stage": "Store",
                    "line_id": l["id"], "arr_line_id": None, "order_no": l.get("order_no"), "medicine_name": l.get("item_name"),
                    "qty_ordered": _store_qty(l), "qty_missing": _store_qty(l), "issue": "Not found in store",
                    "note": r["Note"] or None, "status": "To verify", "reported_by": st.session_state.name, "reported_at": now_s}])
        log_simple_task("In-Store Pick Check", {"area": area, "picked": str(len(chosen) - n_nf), "not_found": str(n_nf)})
    except Exception as e:
        st.error(f"Could not save — {STORE_SQL} and **bounce_setup.sql**. ({e})")
        return
    st.session_state["sc_ver"] = ver + 1
    st.session_state["sc_msg"] = (f"✅ Saved — {len(chosen) - n_nf} picked"
                                  + (f" · {n_nf} not found, sent to the purchase team" if n_nf else ""))
    st.rerun()

def reopen_store_line(line_id):
    """Purchase confirmed 'not found in store' -> the item goes back to pending to order from a distributor"""
    l = supabase.table("customer_order_lines").select("*").eq("id", line_id).execute().data
    if not l:
        return
    l = l[0]
    if l.get("status") == "In Store":
        supabase.table("customer_order_lines").update({"status": "Pending", "completed_at": None}).eq("id", line_id).execute()
    elif l.get("remainder_note") == "In Store":
        supabase.table("customer_order_lines").update({"remainder_note": None}).eq("id", line_id).execute()
        refresh_line_status(line_id)

def undo_line_decisions(kp, area):
    """Purchase: move wrong In Store / Not Available decisions back to pending"""
    since = (now_ist() - timedelta(days=2)).isoformat()
    try:
        rows = supabase.table("customer_order_lines").select("*").eq("removed", False).gte("decided_at", since)\
            .execute().data or []
    except Exception:
        return
    rows = [l for l in rows if (area in (None, "All Areas", SELECT_AREA) or l.get("area") == area) and
            (l.get("status") in ("In Store", "Not Available") or l.get("remainder_note") in ("In Store", "Not Available"))]
    if not rows:
        return
    with st.expander(f"↩️ Undo / Not found in store — {len(rows)} item(s) marked In Store / Not Available in the last 2 days"):
        lab = lambda l: (f"{l.get('item_name')} — {l.get('order_no')} {l.get('customer_name','')} — "
                         f"{'🏪 In Store' if 'In Store' in (l.get('status'), l.get('remainder_note')) else '❌ Not Available'}"
                         f" by {l.get('decided_by','')}" + (f" · stock: {l.get('store_check')}" if l.get("store_check") else ""))
        opts = {lab(l): l for l in rows}
        back = st.multiselect("Items to move back to pending (to order from a distributor)", list(opts), key=f"{kp}_undo")
        why = st.radio("Why?", ["↩️ Wrong click", "🔴 Not found in store (stock team told us)"], horizontal=True,
                       key=f"{kp}_undo_why")
        told = st.text_input("Told by (stock team person)", key=f"{kp}_undo_by") if why.startswith("🔴") else ""
        if st.button("↩️ Move back", key=f"{kp}_undo_go", disabled=not back):
            not_found = why.startswith("🔴")
            bad = [k for k in back if not_found and "In Store" not in (opts[k].get("status"), opts[k].get("remainder_note"))]
            if bad:
                st.error("'Not found in store' is only for items marked In Store: " + "; ".join(b.split(" — ")[0] for b in bad))
                return
            now_s = now_iso()
            for k in back:
                l = opts[k]
                if not_found:                         # recorded for the report + 🔴 flag until re-ordered
                    try:
                        _bounce_insert([{
                            "arrangement_no": "", "distributor": "In Store (not found)", "area": l.get("area"),
                            "stage": "Store", "line_id": l["id"], "arr_line_id": None, "order_no": l.get("order_no"),
                            "medicine_name": l.get("item_name"), "qty_ordered": _store_qty(l), "qty_missing": _store_qty(l),
                            "issue": "Not found in store", "note": (f"told by {told}" if told else None),
                            "status": "Re-order", "reported_by": st.session_state.name, "reported_at": now_s,
                            "verified_by": st.session_state.name, "verified_at": now_s}])
                    except Exception:
                        pass                          # bounce table not created yet -> still moved back
                if l.get("status") in ("In Store", "Not Available"):
                    upd = {"status": "Pending", "decided_by": None, "decided_at": None, "completed_at": None}
                else:
                    upd = {"remainder_note": None, "decided_by": None, "decided_at": None}
                try:
                    supabase.table("customer_order_lines").update({**upd, "store_check": None}).eq("id", l["id"]).execute()
                except Exception:
                    supabase.table("customer_order_lines").update(upd).eq("id", l["id"]).execute()
                if l.get("status") not in ("In Store", "Not Available"):
                    refresh_line_status(l["id"])
            log_simple_task("Not Found In Store" if not_found else "Undo In Store / Not Available",
                            {"lines": str(len(back)), "told_by": told})
            st.session_state["arr_link_ver"] = st.session_state.get("arr_link_ver", 0) + 1
            st.session_state["arr_dec_msg"] = (f"🔴 {len(back)} item(s) not found in store — back at the top to order"
                                               if not_found else f"↩️ {len(back)} item(s) moved back to pending")
            st.rerun()

# ── ORDER TRACKER ─────────────────────────────────────────────────────────────
LINE_ICON = {"Closed": "🧹 Closed (old)", "Pending": "⏳ Pending", "Partly Arranged": "📦 Part-arranged", "Arranged": "📦 Arranged",
             "In Store": "🏪 In Store", "Received": "✅ Received", "Short": "⚠️ Short",
             "Not Available": "❌ Not Available"}

def line_ready(l):
    """a customer medicine is ready for the call: received / not available / short — or In Store AND picked from the shelf"""
    stt = l.get("status")
    if stt == "In Store":
        return l.get("store_check") == "Picked"
    return stt in ("Received", "Not Available", "Short", "Closed")


def line_ready_at(l):
    return to_ist(l.get("store_checked_at") if l.get("status") == "In Store" else l.get("completed_at"))


def line_stage(l):
    """status for the order tracker: In Store not yet picked from the shelf counts as still open"""
    if l.get("status") == "In Store" and l.get("store_check") != "Picked":
        return "To Pick"
    return l.get("status", "Pending")


def order_status(statuses):
    s = list(statuses)
    if all(x == "Pending" for x in s):
        return "⚪ Not Started"
    if any(x in ("Pending", "Partly Arranged", "Arranged", "To Pick") for x in s):
        return "🔄 In Progress"
    if any(x in ("Not Available", "Short") for x in s):
        return "⚠️ Done – Partial"
    return "✅ Ready"

def show_customer_order_tracker(kp="trk", show_phone=False):
    st.subheader("📦 Customer Order Tracker")
    c0, c1, c2, c3 = st.columns(4)
    with c0:
        date_by = st.selectbox("Date type", ["Scheduled date", "Imported on"], key=f"{kp}_dateby")
    with c1:
        day = st.date_input(date_by, value=today_ist(), key=f"{kp}_day")
    with c2:
        area = st.selectbox("Area", ["All Areas"] + load_areas(), key=f"{kp}_area")
    with c3:
        deliv_f = st.selectbox("Delivery", ["All", "✅ Delivered", "❌ Not delivered", "🟡 Partly", "📞 Awaiting call"],
                               key=f"{kp}_deliv")
    start = IST.localize(datetime(day.year, day.month, day.day))
    from datetime import timedelta
    end = start + timedelta(days=1)
    try:
        q = supabase.table("customer_order_lines").select("*").eq("removed", False)
        if date_by == "Scheduled date":
            q = q.eq("scheduled_date", day.strftime("%Y-%m-%d"))
        else:
            q = q.gte("imported_at", start.isoformat()).lt("imported_at", end.isoformat())
        if area != "All Areas":
            q = q.eq("area", area)
        lines = q.execute().data or []
    except Exception as e:
        st.error(f"Could not load — has the setup SQL been run in Supabase? ({e})")
        return

    def _order_delivery(ls):
        if all(l.get("delivery_status") == "Delivered" for l in ls):
            return "✅ Delivered"
        if all(l.get("delivery_status") == "Not Delivered" for l in ls):
            return "❌ Not delivered"
        if any(l.get("delivery_status") for l in ls):
            return "🟡 Partly"
        return "📞 Awaiting call"
    if deliv_f != "All" and lines:
        by_o = {}
        for l in lines:
            by_o.setdefault(l.get("order_no"), []).append(l)
        keep = {o for o, ls in by_o.items() if _order_delivery(ls) == deliv_f}
        lines = [l for l in lines if l.get("order_no") in keep]
    if not lines:
        st.info(f"No customer orders for this {date_by.lower()} / area / delivery filter.")
        return

    customer_order_summary(lines)
    st.divider()

    # arrangement links for distributor names
    links = {}
    for part in _chunks([l["id"] for l in lines], 100):
        for a in supabase.table("arrangement_lines").select("line_id,arrangement_no,distributor,ordered_by,ordered_at")\
                .in_("line_id", part).execute().data or []:
            links.setdefault(a["line_id"], []).append(a)

    now = now_ist()
    orders = {}
    for l in lines:
        orders.setdefault(l["order_no"], []).append(l)

    order_rows = []
    for ono, ls in orders.items():
        statuses = [line_stage(l) for l in ls]
        stt = order_status(statuses)
        t0 = min([to_ist(l.get("imported_at")) for l in ls if to_ist(l.get("imported_at"))] or [now])
        done = stt in ("✅ Ready", "⚠️ Done – Partial")
        t_end = max([line_ready_at(l) for l in ls if line_ready_at(l)] or [now]) if done else now
        mins = max(0, int((t_end - t0).total_seconds() // 60))
        row = {
            "⏰": "🔴" if mins >= 180 else ("🟢" if done else age_flag(mins)),
            "Order #": ono,
            "Customer": ls[0].get("customer_name", ""),
        }
        if show_phone:
            row["Phone"] = ls[0].get("customer_phone", "")
        di = due_info(ls[0], now)
        row.update({
            "Area": ls[0].get("area", ""),
            "Sched": _sched_label(ls[0].get("scheduled_date")),
            "Deliver by": (f"{di[0]} {ls[0].get('delivery_time')} ({di[2]})" if di and not done
                           else (ls[0].get("delivery_time") or "")),
            "Items": len(ls),
            "🏪 Store": statuses.count("In Store") + statuses.count("To Pick"),
            "📦 Arranged": sum(1 for s in statuses if s in ("Arranged", "Partly Arranged")),
            "✅ Received": statuses.count("Received"),
            "⏳ Pending": statuses.count("Pending"),
            "❌ N/A": statuses.count("Not Available") + statuses.count("Short"),
            "Status": stt,
            "🚚 Delivery": _order_delivery(ls),
            "Imported": t0.strftime("%I:%M %p"),
            "Time": fmt_age(mins) + ("" if done else " (running)"),
            "_mins": mins, "_done": done,
        })
        order_rows.append(row)

    odf = pd.DataFrame(order_rows).sort_values(["_done", "_mins"], ascending=[True, False])
    done_df = odf[odf["_done"]]
    m1, m2, m3, m4, m5 = st.columns(5)
    with m1: st.metric("Orders", len(odf))
    with m2: st.metric("✅ Ready", int((odf["Status"] == "✅ Ready").sum()))
    with m3: st.metric("🔄 Open", int((~odf["_done"]).sum()))
    with m4: st.metric("🔴 Over 3 hrs", int((odf["_mins"] >= 180).sum()))
    with m5: st.metric("Avg Time to Ready", fmt_age(done_df["_mins"].mean()) if not done_df.empty else "—")

    f1, f2 = st.columns([3, 2])
    with f1:
        search = st.text_input("🔍 Search — mobile no, order #, customer name or medicine", key=f"{kp}_search",
                               placeholder="e.g. 98716  ·  158213  ·  Shivam  ·  Glizina").strip().lower()
    with f2:
        status_filter = st.multiselect("Show status", sorted(odf["Status"].unique()), default=[], key=f"{kp}_st",
                                       placeholder="All statuses")
    match_orders = None
    if search:
        s_digits = "".join(ch for ch in search if ch.isdigit())
        match_orders = set()
        for l in lines:
            phone = "".join(ch for ch in str(l.get("customer_phone", "")) if ch.isdigit())
            if (search in str(l.get("order_no", "")).lower()
                    or search in str(l.get("customer_name", "")).lower()
                    or search in str(l.get("item_name", "")).lower()
                    or (s_digits and len(s_digits) >= 4 and s_digits in phone)):
                match_orders.add(str(l.get("order_no", "")))
    view = odf if not status_filter else odf[odf["Status"].isin(status_filter)]
    if match_orders is not None:
        view = view[view["Order #"].astype(str).isin(match_orders)]
        st.caption(f"🔍 {len(view)} order(s) match “{search}”")
    st.dataframe(view.drop(columns=["_mins", "_done"]), hide_index=True, width='stretch')

    # line level + export
    line_rows = []
    for l in sorted(lines, key=lambda x: (x.get("order_no", ""), x.get("item_name", ""))):
        ls = links.get(l["id"], [])
        line_rows.append({
            "Scheduled Date": l.get("scheduled_date", ""),
            "Order #": l.get("order_no", ""),
            "Customer Name": l.get("customer_name", ""),
            "Customer Phone": l.get("customer_phone", "") if show_phone else "",
            "Item Name": l.get("item_name", ""),
            "Pack Size": l.get("pack_size", ""),
            "Qty": _qty_txt(l.get("qty")),
            "Deliver by": l.get("delivery_time") or "",
            "Distributor Name": ", ".join(sorted(set(a.get("distributor", "") for a in ls))),
            "ARR No": ", ".join(sorted(set(a.get("arrangement_no", "") for a in ls))),
            "Arranged By": ", ".join(sorted(set(a.get("ordered_by", "") or "" for a in ls))),
            "Arranged At": ", ".join(sorted(set(to_ist(a.get("ordered_at")).strftime("%d %b %I:%M %p")
                                                for a in ls if to_ist(a.get("ordered_at"))))),
            "Area": l.get("area", ""),
            "Status": LINE_ICON.get(l.get("status", ""), l.get("status", "")),
            "Checked By": l.get("decided_by", "") or "",
            "Delivery": l.get("delivery_status") or "",
            "Not Delivered Reason": l.get("delivery_reason") or "",
        })
    ldf = pd.DataFrame(line_rows)
    if not show_phone:
        ldf = ldf.drop(columns=["Customer Phone"])
    if match_orders is not None:
        # show the matching orders' lines; if the search is a medicine name, only those medicines
        med_hit = ldf["Item Name"].str.lower().str.contains(search, regex=False)
        ldf = ldf[ldf["Order #"].astype(str).isin(match_orders) & (med_hit if med_hit.any() else True)]
    with st.expander(f"🔍 Item-level detail ({len(ldf)} medicines)", expanded=bool(search)):
        st.dataframe(ldf, hide_index=True, width='stretch')
    st.download_button("⬇️ Download (with Distributor Name filled)", ldf.to_csv(index=False).encode("utf-8"),
                       file_name=f"customer-orders-{'sched' if date_by == 'Scheduled date' else 'imported'}-{day}-{area.replace(' ', '_')}.csv", mime="text/csv",
                       key=f"{kp}_dl")



# ── 📍 ORDER JOURNEY: one customer order from "came in" to "call done" ────────
JOURNEY_TASKS = ["Pickup", "Register Entry", "Bill Cross Check", "Bill Upload (Software)", "Stock Placement",
                 "Porter Receipt", "Distributor Delivery Receipt"]

def _j_at(date_s, time_s):
    """task date + a text time ('11:05 AM' / '11:05:20 AM') -> naive datetime"""
    try:
        t = parse_task_time(time_s)
        d = datetime.strptime(str(date_s)[:10], "%Y-%m-%d")
        return d.replace(hour=t.hour, minute=t.minute, second=t.second) if t else None
    except Exception:
        return None

def _j_ts(ts):
    return _naive(to_ist(ts)) if ts else None

def _arr_nos_of(d):
    out = set()
    for a in re.split(r"[,\s]+", str(d.get("arrangement_nos") or d.get("arrangement_no") or "")):
        a = a.strip().lstrip("#")
        if a:
            out.add(a)
    return out

def find_journey_orders(text):
    """order numbers matching an order #, a phone number (4+ digits) or a customer name — last 45 days"""
    from datetime import timedelta
    text = (text or "").strip()
    if not text:
        return []
    since = IST.localize(datetime.combine(today_ist() - timedelta(days=45), datetime.min.time())).isoformat()
    base = lambda: supabase.table("customer_order_lines").select("order_no,customer_name,area,scheduled_date,imported_at")\
        .eq("removed", False).gte("imported_at", since)
    rows = []
    digits = "".join(ch for ch in text if ch.isdigit())
    try:
        if digits and len(digits) >= 4:
            rows += base().like("order_no", f"%{digits}%").limit(300).execute().data or []
            rows += base().like("customer_phone", f"%{digits[-10:]}%").limit(300).execute().data or []
        else:
            rows += base().ilike("customer_name", f"%{text}%").limit(300).execute().data or []
            rows += base().ilike("order_no", f"%{text}%").limit(300).execute().data or []
    except Exception:
        return []
    seen = {}
    for r in rows:
        o = str(r.get("order_no", ""))
        if o and o not in seen:
            seen[o] = r
    return sorted(seen.values(), key=lambda r: str(r.get("imported_at") or ""), reverse=True)

JOURNEY_CALL_TASKS = ["Customer Not Reachable", "Customer Delivery Update"]


def _j_at_any(date_s, time_s):
    """like _j_at, also reads '14:05' / '14:05:00' (porter handover time)"""
    w = _j_at(date_s, time_s)
    if w or not time_s:
        return w
    try:
        t = _any_time(time_s)
        return datetime.combine(datetime.strptime(str(date_s)[:10], "%Y-%m-%d").date(), t) if t else None
    except Exception:
        return None


def _ano(x):
    return str(x or "").strip().lstrip("#")


def _load_journey_ctx(lines, als=None, extra_arrs=()):
    """everything the journeys of these customer-order lines need, loaded in a few batch queries"""
    ids = [l["id"] for l in lines]
    if als is None:
        als = []
        for part in _chunks(ids, 100):
            als += supabase.table("arrangement_lines").select("*").in_("line_id", part).execute().data or []
    arr_nos = sorted(({_ano(a.get("arrangement_no")) for a in als} | {_ano(x) for x in extra_arrs}) - {""})
    arrs = {}
    for part in _chunks(arr_nos, 100):
        for a in supabase.table("arrangements").select("*").in_("arrangement_no", part).execute().data or []:
            arrs[_ano(a.get("arrangement_no"))] = a
    now_n = now_ist().replace(tzinfo=None)
    starts = [_j_ts(l.get("imported_at")) for l in lines if l.get("imported_at")] + \
             [_j_ts(a.get("ordered_at")) for a in als if a.get("ordered_at")] + \
             [_j_ts(a.get("created_at")) for a in arrs.values() if a.get("created_at")]
    starts = [s for s in starts if s]
    base, top = (min(starts), max(starts)) if starts else (now_n, now_n)
    d_lo = (base - timedelta(days=1)).strftime("%Y-%m-%d")
    d_hi = min(top + timedelta(days=10), now_n + timedelta(days=1)).strftime("%Y-%m-%d")
    aset = set(arr_nos)
    tasks_by_arr, calls_by_order = {}, {}
    try:
        tasks = fetch_all("daily_tasks", lambda q: q.in_("task_type", JOURNEY_TASKS + ["Porter Bill Missing"] + JOURNEY_CALL_TASKS)
                          .gte("date", d_lo).lte("date", d_hi))
    except Exception:
        tasks = []
    for t in tasks:
        d = t.get("details") or {}
        if t.get("task_type") in JOURNEY_CALL_TASKS:
            for o in re.split(r",\s*", str(d.get("order") or "")):
                if o:
                    calls_by_order.setdefault(o.strip(), []).append(t)
        else:
            for a in _arr_nos_of(d) & aset:
                tasks_by_arr.setdefault(a, []).append(t)
    hos_by_arr, porter_by_arr, ba = {}, {}, {}
    if arr_nos:
        try:
            for part in _chunks(arr_nos, 100):
                for h in supabase.table("pilot_handovers").select("*").in_("arrangement_no", part).execute().data or []:
                    hos_by_arr.setdefault(_ano(h.get("arrangement_no")), []).append(h)
        except Exception:
            pass                                       # table not created yet
        try:
            for b in sorted(fetch_all("porter_bookings", lambda q: q.gte("date", d_lo).lte("date", d_hi)),
                            key=lambda b: b.get("id") or 0):
                for a in _arr_nos_of({"arrangement_nos": b.get("arrangement_nos")}) & aset:
                    porter_by_arr.setdefault(a, []).append(b)
        except Exception:
            pass
        arr_ids = sorted({(t.get("details") or {}).get("arrival_id") for ts in tasks_by_arr.values() for t in ts
                          if t.get("task_type") == "Register Entry"} - {None, ""})
        try:
            for part in _chunks(arr_ids, 100):
                for b in supabase.table("bill_arrivals").select("*").in_("id", part).execute().data or []:
                    ba[b["id"]] = b
        except Exception:
            pass
    return {"als": als, "arrs": arrs, "tasks_by_arr": tasks_by_arr, "calls_by_order": calls_by_order,
            "hos_by_arr": hos_by_arr, "porter_by_arr": porter_by_arr, "ba": ba}


@st.cache_data(ttl=60, show_spinner=False)
def order_journey(order_no):
    """Every step of one customer order, as a time-ordered list of events.
    branch = None for order-level steps, else the ARR no (one branch per distributor bill)"""
    lines = supabase.table("customer_order_lines").select("*").eq("order_no", str(order_no))\
        .eq("removed", False).execute().data or []
    if not lines:
        return None
    return build_journey(lines, _load_journey_ctx(lines))


def _arr_branch(a_no, arrs, als, ctx, add):
    """journey steps of one distributor bill (ARR) -> (a_no, distributor)"""
    arr = arrs.get(a_no, {})
    mine = [a for a in als if _ano(a.get("arrangement_no")) == a_no]
    dist = arr.get("distributor") or (mine[0].get("distributor") if mine else "")
    o_at = min([_j_ts(a.get("ordered_at")) for a in mine if a.get("ordered_at")] or [None]) \
        or _j_at(arr.get("order_placed_date"), arr.get("order_placed_time")) or _j_ts(arr.get("created_at"))
    add(o_at, f"📦 Ordered from {dist}", ", ".join(sorted({a.get("ordered_by") or "" for a in mine} - {""}))
        or arr.get("order_by", ""), a_no,
        info=f"{len(mine)} medicine(s) of this order" + (f" · {arr.get('urgency')}" if arr.get("urgency") not in (None, "", "Normal") else ""),
        photo=arr.get("order_image"), k="ordered")
    my_t = ctx["tasks_by_arr"].get(a_no, [])
    porter_picked = False
    for b in ctx["porter_by_arr"].get(a_no, [])[:1]:
        w = _j_at_any(b.get("date"), b.get("time"))
        if w:
            add(w, f"🚛 Porter booked ({b.get('porter_no') or '—'})", b.get("booked_by", ""), a_no,
                info=f"{b.get('pickup_point') or ''} → {b.get('delivery_point') or ''}", k="porter_book")
        h_at = _j_at_any(b.get("date"), b.get("handover_time")) if b.get("status") not in (None, "", "Booked") else None
        if h_at:
            porter_picked = True
            add(h_at, "📞 Porter picked up", b.get("handover_by", ""), a_no,
                info=" · ".join(x for x in [f"{b.get('no_bills')} bill(s)" if b.get("no_bills") else "",
                                            f"{b.get('no_polythene')} polythene" if b.get("no_polythene") else ""] if x),
                photo=b.get("handover_image") or None, k="picked")
    for t in [t for t in my_t if t.get("task_type") == "Porter Bill Missing"]:
        d = t.get("details") or {}
        add(_j_at(t.get("date"), t.get("time")), "❌ Not received from porter", t.get("person", ""), a_no,
            info=f"{d.get('reason', '')} · porter {d.get('porter_no', '')}", k="missing")
    pk = [t for t in my_t if t.get("task_type") == "Pickup" and t.get("status") != "In Progress"]
    if pk:
        t = pk[0]
        d = t.get("details") or {}
        reached = _j_at(t.get("date"), d.get("time_reached")) or _task_dt(t, "start_time")
        add(reached, "🛵 Picked up at distributor", t.get("person", ""), a_no,
            info=" · ".join(x for x in [f"{d.get('no_sku_received')} SKU" if d.get("no_sku_received") else "",
                                        f"delivery: {d.get('delivery_by')}" if d.get("delivery_by") else "",
                                        f"porter {d.get('porter_no')}" if d.get("porter_no") else ""] if x),
            photo=d.get("medicine_image"), k="picked")
    elif (arr.get("picked_up_at") or arr.get("pickup_by")) and not porter_picked:
        add(_j_ts(arr.get("picked_up_at")), "🛵 Picked up at distributor", arr.get("pickup_by", ""), a_no,
            info=arr.get("pickup_type") or "", k="picked")
    for h in sorted(ctx["hos_by_arr"].get(a_no, []), key=lambda x: str(x.get("at") or "")):
        if h.get("kind") == "overnight":
            add(_j_ts(h.get("at")), f"🌙 Kept overnight by {h.get('to_person','')}", h.get("to_person", ""), a_no,
                info=h.get("note") or "", photo=h.get("photo"), k="handover")
            continue
        add(_j_ts(h.get("at")), f"🤝 Handed {h.get('from_person','')} → {h.get('to_person','')}",
            h.get("from_person", ""), a_no, info=f"for {h.get('area') or '—'}", photo=h.get("photo"), k="handover")
    for t in [t for t in my_t if t.get("task_type") in ("Porter Receipt", "Distributor Delivery Receipt")][:1]:
        add(_task_dt(t, "time"), "📦 Reached warehouse (receipt)", t.get("person", ""), a_no,
            info=(t.get("details") or {}).get("area", ""), k="arrived")
    regs = sorted([t for t in my_t if t.get("task_type") == "Register Entry"], key=lambda x: _task_dt(x, "time") or datetime.max)
    for r in regs[:1]:
        d = r.get("details") or {}
        if d.get("arrival_id") or d.get("arrived_at"):
            b_ = ctx["ba"].get(d.get("arrival_id"), {})
            add(_j_ts(d.get("arrived_at") or b_.get("arrived_at")), f"📥 Arrived at {d.get('area') or b_.get('area') or 'warehouse'}",
                b_.get("logged_by", ""), a_no,
                info=f"brought by {b_.get('brought_by_name') or b_.get('brought_by') or '—'}" if b_ else "",
                photo=b_.get("photo"), k="arrived")
        add(_task_dt(r, "time"), "📝 Register entry", r.get("person", ""), a_no,
            info=f"Bill {d.get('bill_no') or '—'} · {int(_to_float(d.get('no_items'), 0))} items",
            photo=d.get("invoice_image"), k="register")
    cc = sorted([t for t in my_t if t.get("task_type") == "Bill Cross Check" and t.get("status") != "In Progress"],
                key=lambda x: _task_dt(x) or datetime.max)
    rec = [a for a in mine if a.get("status") in ("Received", "Short")]
    short = [a for a in mine if a.get("status") == "Short"]
    if cc:
        t = cc[0]
        add(_task_dt(t), "✔️ Cross checked — medicines received", t.get("person", ""), a_no,
            info=f"{len(rec) - len(short)} received" + (f" · ⚠️ {len(short)} short" if short else ""),
            photo=(t.get("details") or {}).get("bill_check_image"), k="checked")
    elif rec:
        add(max([_j_ts(a.get("received_at")) for a in rec if a.get("received_at")] or [None]),
            "✔️ Medicines received", ", ".join(sorted({a.get("received_by") or "" for a in rec} - {""})), a_no,
            info=f"{len(rec) - len(short)} received" + (f" · ⚠️ {len(short)} short" if short else ""), k="checked")
    up = sorted([t for t in my_t if t.get("task_type") == "Bill Upload (Software)" and t.get("status") != "In Progress"],
                key=lambda x: _task_dt(x) or datetime.max)
    for t in up[:1]:
        add(_task_dt(t), "📤 Bill uploaded in software", t.get("person", ""), a_no, k="uploaded")
    pl = sorted([t for t in my_t if t.get("task_type") == "Stock Placement" and t.get("status") != "In Progress"],
                key=lambda x: _task_dt(x) or datetime.max)
    for t in pl[:1]:
        d = t.get("details") or {}
        wh = d.get("placed_by_type") == "Warehouse team"
        add(_task_dt(t), "📍 Placed on racks" + (" (warehouse team)" if wh else ""),
            (d.get("warehouse_person") or "Warehouse team") if wh else t.get("person", ""), a_no,
            info=f"logged by {t.get('person', '')}" if wh else "", photo=d.get("printout_image"), k="placed")
    if not (cc or rec):
        missing = [t for t in my_t if t.get("task_type") == "Porter Bill Missing"]
        nxt = ("❌ not received from porter — Purchase team to sort it" if missing and not regs else
               "waiting for pickup" if not (pk or arr.get("pickup_by") or porter_picked) else
               "on the way to warehouse" if not regs else "waiting for cross check")
        add(None, f"⏳ Now: {nxt}", "", a_no, info=arr.get("status", ""), k="now")
    return a_no, dist


def _order_events(ev):
    """sort by time (undated 'now' rows go last), then gap from the previous step on the same path"""
    timed = sorted([e for e in ev if e["when"]], key=lambda e: e["when"])
    last_any, last_shared, last_br = None, None, {}
    for e in timed:
        if e["branch"] is None:
            prev = last_any                            # order-level step waits for every bill before it
            last_shared = e["when"]
        else:
            cand = [x for x in (last_br.get(e["branch"]), last_shared) if x]
            prev = max(cand) if cand else None
            last_br[e["branch"]] = e["when"]
        e["gap"] = max(0.0, (e["when"] - prev).total_seconds() / 60) if prev else None
        last_any = e["when"]
    return timed + [e for e in ev if not e["when"]]


def build_journey(lines, ctx):
    idset = {l["id"] for l in lines}
    order_no = str(lines[0].get("order_no"))
    als = [a for a in ctx["als"] if a.get("line_id") in idset]
    arr_nos = sorted({_ano(a.get("arrangement_no")) for a in als} - {""})
    arrs = ctx["arrs"]

    ev, photos = [], []
    def add(when, step, who="", branch=None, info="", photo=None, k=""):
        ev.append({"when": when, "step": step, "who": who or "", "branch": branch, "info": info, "k": k})
        for p in (photo if isinstance(photo, list) else [photo] if photo else []):
            photos.append((f"{step}" + (f" · #{branch}" if branch else ""), p))

    # 1) customer ordered (chat sheet time) / order came in (import)
    ots = [_j_ts(l.get("order_time")) for l in lines if l.get("order_time")]
    ots = [t for t in ots if t]
    if ots:
        add(min(ots), "🛒 Customer ordered (chat)", "", info="order time from the chat sheet", k="order")
    t0 = min([_j_ts(l.get("imported_at")) for l in lines if l.get("imported_at")] or [None])
    imp_by = ", ".join(sorted({l.get("imported_by") or "" for l in lines} - {""}))
    add(t0, "🧾 Order came in (imported)", imp_by,
        info=f"{len(lines)} medicine(s) · deliver by {lines[0].get('delivery_time') or '—'}", k="import")

    # 2) store check / decision (In store / to arrange / not available)
    dec = [l for l in lines if l.get("decided_at")]
    if dec:
        cnt = {}
        for l in lines:
            cnt[l.get("status", "Pending")] = cnt.get(l.get("status", "Pending"), 0) + 1
        in_store = cnt.get("In Store", 0)
        add(max(_j_ts(l["decided_at"]) for l in dec), "🔎 Store check — what to arrange",
            ", ".join(sorted({l.get("decided_by") or "" for l in dec} - {""})),
            info=f"{in_store} in store · {len(lines) - in_store - cnt.get('Not Available', 0)} to arrange"
                 + (f" · {cnt['Not Available']} not available" if cnt.get("Not Available") else ""), k="store")

    # 3) one branch per arrangement (distributor bill)
    branches = [_arr_branch(a_no, arrs, als, ctx, add) for a_no in arr_nos]

    # 4) all medicines ready, then the call
    picked = [l for l in lines if l.get("status") == "In Store" and l.get("store_checked_at")]
    if picked:
        nf = [l for l in picked if l.get("store_check") != "Picked"]
        add(max(_j_ts(l["store_checked_at"]) for l in picked), "🏪 Picked from the shelf",
            ", ".join(sorted({l.get("store_checked_by") or "" for l in picked} - {""})),
            info=f"{len(picked) - len(nf)} picked" + (f" · ⚠️ {len(nf)} not found" if nf else ""), k="shelf")
    to_pick = [l for l in lines if l.get("status") == "In Store" and l.get("store_check") != "Picked"]
    if to_pick:
        add(None, f"⏳ Now: {len(to_pick)} in-store medicine(s) to pick from the shelf", "",
            info=", ".join(l.get("item_name", "") for l in to_pick[:5]), k="now")
    if all(line_ready(l) for l in lines):
        done_t = [_naive(line_ready_at(l)) for l in lines if line_ready_at(l)]
        add(max(done_t) if done_t else None, "✅ All medicines ready", "",
            info="everything picked from the shelf / received", k="ready")
    calls = ctx["calls_by_order"].get(order_no, [])
    nr = sorted([t for t in calls if t.get("task_type") == "Customer Not Reachable"], key=lambda t: t.get("id") or 0)
    for i, t in enumerate(nr, 1):
        pr = (t.get("details") or {}).get("proof") or []
        add(_j_at(t.get("date"), t.get("time")), f"📵 Called — not reachable (try {i})", t.get("person", ""),
            info=f"{len(pr)} screenshot(s)", photo=pr, k="nr")
    called = [l for l in lines if l.get("delivery_status")]
    if called:
        n_ok = sum(1 for l in called if l.get("delivery_status") == "Delivered")
        res = ("✅ Delivered" if n_ok == len(lines) else "❌ Not delivered" if n_ok == 0 else f"🟡 Partly delivered ({n_ok}/{len(lines)})")
        reasons = sorted({l.get("delivery_reason") or "" for l in called if l.get("delivery_status") != "Delivered"} - {""})
        proof = [p for t in calls if t.get("task_type") == "Customer Delivery Update"
                 for p in ((t.get("details") or {}).get("proof") or [])]
        add(max([_j_ts(l.get("delivery_at")) for l in called if l.get("delivery_at")] or [None]), f"📞 Call done → {res}",
            ", ".join(sorted({l.get("delivery_by") or "" for l in called} - {""})),
            info="; ".join(reasons) + (f" · 📸 {len(proof)} screenshot(s)" if proof else ""), photo=proof, k="call")
    else:
        add(None, "⏳ Now: waiting for the call to customer" + (f" · 📵 tried {len(nr)}×" if nr else ""), "", k="now")

    first = lines[0]
    return {"lines": lines, "events": _order_events(ev), "photos": photos,
            "branches": branches, "nr": len(nr), "arranged": bool(arr_nos),
            "head": {"customer": first.get("customer_name", ""), "phone": first.get("customer_phone", ""),
                     "area": first.get("area", ""), "sched": first.get("scheduled_date", ""),
                     "deliver_by": first.get("delivery_time") or ""}}


# columns of the 📅 All orders table: (column, step keys, name of the wait that ends here)
J_COLS = [("Ordered to distributor", ("ordered",), "Ordering"),
          ("Picked up", ("picked",), "Pickup"),
          ("Arrived at warehouse", ("arrived", "register"), "Travel to warehouse"),
          ("Cross checked", ("checked",), "Cross check"),
          ("All ready", ("ready",), "Shelf pick / ready"),
          ("Call done", ("call",), "Call")]
J_LATE = 180


def journey_summary(j, now_n=None):
    """one row of numbers for the 📅 All orders table"""
    now_n = now_n or now_ist().replace(tzinfo=None)
    evs = [e for e in j["events"] if e["when"]]
    t_in = min([e["when"] for e in evs if e["k"] in ("order", "import")] or [None])
    out = {"came_in": t_in, "steps": {}, "gaps": {}}
    prev = t_in
    for col, ks, _ in J_COLS:
        ts = [e["when"] for e in evs if e["k"] in ks]
        if col == "Arrived at warehouse":                # the real arrival beats the register entry
            real = [e["when"] for e in evs if e["k"] == "arrived"]
            ts = real or ts
        w = max(ts) if ts else None                     # the customer waits for the LAST bill
        out["steps"][col] = w
        if w and prev:
            out["gaps"][col] = max(0.0, (w - prev).total_seconds() / 60)
        if w:
            prev = w
    call = out["steps"]["Call done"]
    out["closed"] = bool(call)
    out["total"] = ((call or now_n) - t_in).total_seconds() / 60 if t_in else None
    out["late"] = out["total"] is not None and out["total"] >= J_LATE
    res = next((e["step"].split("→", 1)[1].strip() for e in evs if e["k"] == "call"), "")
    nows = [e["step"].replace("⏳ Now: ", "") for e in j["events"] if not e["when"] and e["k"] == "now"]
    out["now"] = res or ("⏳ " + nows[0] if nows else "⏳")
    out["result"] = res
    out["nr"] = j.get("nr", 0)
    return out


@st.cache_data(ttl=120, show_spinner=False)
def journeys_for_period(lo_s, hi_s, area):
    """{order_no: (journey, summary)} for every customer order whose ORDER date (chat time, else import) is in [lo, hi]"""
    lo, hi = datetime.strptime(lo_s, "%Y-%m-%d"), datetime.strptime(hi_s, "%Y-%m-%d")
    since = IST.localize(lo - timedelta(days=1)).isoformat()
    until = IST.localize(hi + timedelta(days=2)).isoformat()
    def build(q):
        q = q.eq("removed", False).gte("imported_at", since).lt("imported_at", until)
        return q.eq("area", area) if area != "All Areas" else q
    lines = fetch_all("customer_order_lines", build)
    by = {}
    for l in lines:
        by.setdefault(str(l.get("order_no")), []).append(l)
    keep = {}
    for o, ls in by.items():
        ts = [_j_ts(l.get("order_time")) for l in ls if l.get("order_time")] or \
             [_j_ts(l.get("imported_at")) for l in ls if l.get("imported_at")]
        ts = [t for t in ts if t]
        if ts and lo.date() <= min(ts).date() <= hi.date():
            keep[o] = ls
    if not keep:
        return {}
    ctx = _load_journey_ctx([l for ls in keep.values() for l in ls])
    now_n = now_ist().replace(tzinfo=None)
    out = {}
    for o, ls in keep.items():
        j = build_journey(ls, ctx)
        out[o] = (j, journey_summary(j, now_n))
    return out


J_SHOW = ["All", "⏳ Still open", "🔴 Late (over 3 hours)", "❌ Not delivered", "📵 Not reachable"]


def _jcell(w, gap, ref):
    if not w:
        return ""
    return _fmt_when(w, ref) + (f" ({fmt_age(int(gap))})" if gap is not None else "")


def _show_all_journeys(kp, show_phone):
    lo, hi, _b = report_period(f"{kp}_all")
    c1, c2, c3 = st.columns([2, 2, 2])
    with c1:
        area = st.selectbox("Area", ["All Areas"] + load_areas(), key=f"{kp}_all_area")
    with c2:
        show = st.selectbox("Show", J_SHOW, key=f"{kp}_all_show")
    with c3:
        st.write("")
        only_arr = st.checkbox("Only orders sent to a distributor (arrangement)", value=True, key=f"{kp}_all_arr")
    st.caption("Date = the customer's order date (chat-sheet time; the import time when it is missing).")
    try:
        with st.spinner("Building the journeys…"):
            data = journeys_for_period(lo.strftime("%Y-%m-%d"), hi.strftime("%Y-%m-%d"), area)
    except Exception as e:
        st.error(f"Could not load: {e}")
        return
    items = [(o, j, s) for o, (j, s) in data.items() if j["arranged"] or not only_arr]
    if not items:
        st.info("No customer orders in this period / area.")
        return

    # ── period summary (before the Show filter)
    closed = [s for _, _, s in items if s["closed"] and s["total"] is not None]
    avg_t = sum(s["total"] for s in closed) / len(closed) if closed else None
    in3 = sum(1 for s in closed if s["total"] < J_LATE)
    open_late = sum(1 for _, _, s in items if not s["closed"] and s["late"])
    step_avg = {}
    for col, _, nm in J_COLS:
        g = [s["gaps"][col] for _, _, s in items if col in s["gaps"]]
        if g:
            step_avg[nm] = sum(g) / len(g)
    res = lambda r: sum(1 for _, _, s in items if s["result"].startswith(r))
    m = st.columns(5)
    m[0].metric("Orders", len(items))
    m[1].metric("Avg came in → call", fmt_age(int(avg_t)) if avg_t is not None else "—")
    m[2].metric("Within 3 hours", f"{round(100 * in3 / len(closed))}%" if closed else "—",
                help="of the orders where the call is done")
    m[3].metric("✅ / ❌ / 🟡", f"{res('✅')} / {res('❌')} / {res('🟡')}")
    m[4].metric("⏳ Open (🔴 late)", f"{len(items) - len(closed)} ({open_late})")
    if step_avg:
        worst = max(step_avg, key=step_avg.get)
        st.markdown(f"🔴 **Most time is lost in: {worst}** — avg {fmt_age(int(step_avg[worst]))} · "
                    + " · ".join(f"{k} {fmt_age(int(v))}" for k, v in step_avg.items()))
    nr_n = sum(1 for _, _, s in items if s["nr"])
    if nr_n:
        st.caption(f"📵 {nr_n} order(s) had a 'not reachable' call.")

    # ── area-wise / day-wise summary
    by_kind = st.radio("Summary by", ["📍 Area", "📅 Day"], horizontal=True, key=f"{kp}_all_by")
    grp = {}
    for o, j, s in items:
        key = j["head"]["area"] or "—" if by_kind == "📍 Area" else (s["came_in"].strftime("%Y-%m-%d") if s["came_in"] else "—")
        grp.setdefault(key, []).append(s)
    srows = []
    for key in sorted(grp):
        ss = grp[key]
        cl = [s for s in ss if s["closed"] and s["total"] is not None]
        r = {("Area" if by_kind == "📍 Area" else "Day"):
             key if by_kind == "📍 Area" or key == "—" else datetime.strptime(key, "%Y-%m-%d").strftime("%a %d %b"),
             "Orders": len(ss), "Call done": len(cl),
             "Avg total": fmt_age(int(sum(s["total"] for s in cl) / len(cl))) if cl else "—",
             "Within 3h": f"{round(100 * sum(1 for s in cl if s['total'] < J_LATE) / len(cl))}%" if cl else "—",
             "🔴 Late": sum(1 for s in ss if s["late"])}
        for col, _, nm in J_COLS:
            g = [s["gaps"][col] for s in ss if col in s["gaps"]]
            r[nm] = fmt_age(int(sum(g) / len(g))) if g else ""
        srows.append(r)
    st.dataframe(pd.DataFrame(srows).astype(str), hide_index=True, width='stretch')
    st.caption("Step columns = average wait before that step finished (e.g. Pickup = ordered → picked up).")

    # ── one row per order
    if show == "⏳ Still open":
        items = [x for x in items if not x[2]["closed"]]
    elif show.startswith("🔴"):
        items = [x for x in items if x[2]["late"]]
    elif show.startswith("❌"):
        items = [x for x in items if x[2]["result"].startswith(("❌", "🟡"))]
    elif show.startswith("📵"):
        items = [x for x in items if x[2]["nr"]]
    items.sort(key=lambda x: -(x[2]["total"] or 0))
    st.markdown(f"**{len(items)} order(s)** — slowest first")
    if not items:
        return
    rows, xrows = [], []
    for o, j, s in items:
        h, ref = j["head"], s["came_in"]
        slow = max(s["gaps"], key=s["gaps"].get) if s["gaps"] else None
        slow_nm = next((nm for col, _, nm in J_COLS if col == slow), "")
        r = {"Order": f"#{o}", "Area": h["area"], "Customer": h["customer"]}
        if show_phone:
            r["Phone"] = h["phone"]
        r["Came in"] = _fmt_when(ref, None) if ref else ""
        x = dict(r, **{"Came in": ref.strftime("%Y-%m-%d %H:%M") if ref else ""})
        for col, _, _ in J_COLS:
            r[col] = _jcell(s["steps"][col], s["gaps"].get(col), ref)
            x[col] = s["steps"][col].strftime("%Y-%m-%d %H:%M") if s["steps"][col] else ""
            x[col + " (mins)"] = int(s["gaps"][col]) if col in s["gaps"] else ""
        tot = (("🔴 " if s["late"] else "🟢 ") + fmt_age(int(s["total"])) + ("" if s["closed"] else " ⏳")) if s["total"] is not None else ""
        r.update({"Total": tot, "Slowest step": f"{slow_nm} {fmt_age(int(s['gaps'][slow]))}" if slow else "",
                  "Now": s["now"] + (f" · 📵 {s['nr']}×" if s["nr"] else "")})
        x.update({"Total (mins)": int(s["total"]) if s["total"] is not None else "", "Late": "Yes" if s["late"] else "",
                  "Slowest step": slow_nm, "Status": s["now"], "Not reachable tries": s["nr"]})
        rows.append(r)
        xrows.append(x)
    st.dataframe(pd.DataFrame(rows).astype(str), hide_index=True, width='stretch')
    buf = io.BytesIO()
    with pd.ExcelWriter(buf, engine="openpyxl") as w:
        pd.DataFrame(xrows).to_excel(w, index=False, sheet_name="Orders")
        pd.DataFrame(srows).to_excel(w, index=False, sheet_name="Summary")
    st.download_button("📥 Download Excel", buf.getvalue(), key=f"{kp}_all_dl",
                       file_name=f"order-journeys-{lo:%d%b}-{hi:%d%b}-{area.replace(' ', '_')}.xlsx",
                       mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
    st.divider()
    labels = {f"#{o} — {j['head']['customer']} — {j['head']['area']} — {s['now']}": o for o, j, s in items[:300]}
    pick = st.selectbox("🔍 Open the full journey of", ["—"] + list(labels), key=f"{kp}_all_pick")
    if pick != "—":
        o = labels[pick]
        _show_journey_detail(data[o][0], o, f"{kp}_all", show_phone)


def find_arrangements(text, days=30):
    """arrangements whose number contains the text ('025', 'ARR-20261030-025') — newest first"""
    t = (text or "").strip().upper().lstrip("#")
    if not t:
        return []
    lo = (today_ist() - timedelta(days=days)).strftime("%Y-%m-%d")
    try:
        rows = supabase.table("arrangements").select("*").ilike("arrangement_no", f"%{t}%")\
            .gte("order_placed_date", lo).limit(200).execute().data or []
    except Exception:
        return []
    return sorted(rows, key=lambda a: (str(a.get("order_placed_date") or ""), a.get("id") or 0), reverse=True)


@st.cache_data(ttl=60, show_spinner=False)
def arr_journey(a_no):
    """every step of ONE distributor bill (ARR) + the customer orders waiting on it"""
    a_no = _ano(a_no)
    als = supabase.table("arrangement_lines").select("*").eq("arrangement_no", a_no).execute().data or []
    lines = []
    for part in _chunks(sorted({a.get("line_id") for a in als} - {None}), 100):
        lines += supabase.table("customer_order_lines").select("*").in_("id", part).eq("removed", False).execute().data or []
    ctx = _load_journey_ctx(lines, als=als, extra_arrs=[a_no])
    ev, photos = [], []
    def add(when, step, who="", branch=None, info="", photo=None, k=""):
        ev.append({"when": when, "step": step, "who": who or "", "branch": branch, "info": info, "k": k})
        for p in (photo if isinstance(photo, list) else [photo] if photo else []):
            photos.append((step, p))
    _arr_branch(a_no, ctx["arrs"], als, ctx, add)
    return {"arr": ctx["arrs"].get(a_no, {}), "events": _order_events(ev), "photos": photos, "lines": lines,
            "porter": ctx["porter_by_arr"].get(a_no, [])}


def _show_arr_journey(kp, show_phone):
    q = st.text_input("🔎 Arrangement number", key=f"{kp}_arrq", placeholder="e.g. 025 · ARR-20261030-025").strip()
    if not q:
        return
    found = find_arrangements(q)
    if not found:
        st.info("No arrangement with this number in the last 30 days.")
        return
    labels = {f"#{a.get('arrangement_no')} — {a.get('distributor', '')} — {a.get('area', '')} — {a.get('status', '')}":
              str(a.get("arrangement_no")) for a in found[:50]}
