# ── 🏆 LEAGUE: warehouse (Stock) · delivery pilots · call team ───────────────────
# Each metric is scored 0-100 against the best in the league for the period, then weighted.
LEAGUE_PERIODS = ["This week", "Last week", "This month", "Last month", "📅 Choose dates"]
STOCK_METRICS = [  # key, label, weight, higher_is_better, unit
    ("speed", "⏱️ Bill speed (arrival → upload)", 30, False, "min"),
    ("sameday", "📅 Same-day upload", 20, True, "%"),
    ("ontime", "🚚 Customer items on time", 20, True, "%"),
    ("check", "⚡ Check speed", 15, False, "sec/item"),
    ("quality", "✅ Quality (photos + cross check)", 15, True, "%"),
    ("entry", "📥 Entry delay (arrival → entered)", 10, False, "min"),
    ("proof", "📸 Bills with arrival proof", 10, True, "%"),
]
DELIVERY_METRICS = [
    ("ontime", "⏰ Pickups on time", 50, True, "%"),
    ("perday", "📦 Pickups per day", 30, True, ""),
    ("kmper", "🛵 KM per pickup", 20, False, "km"),
]
CALL_METRICS = [
    ("conv", "✅ Delivered (conversion)", 35, True, "%"),
    ("speed", "⏱️ Call speed (ready → marked)", 35, False, "min"),
    ("cph", "📞 Calls per hour", 30, True, ""),
]

def league_period(kp, container=None):
    from datetime import timedelta
    box = container or st
    t = today_ist()
    p = box.selectbox("Period", LEAGUE_PERIODS, key=f"{kp}_per")
    if p == "This week":
        lo, hi = t - timedelta(days=t.weekday()), t
    elif p == "Last week":
        hi = t - timedelta(days=t.weekday() + 1); lo = hi - timedelta(days=6)
    elif p == "This month":
        lo, hi = t.replace(day=1), t
    elif p == "Last month":
        hi = t.replace(day=1) - timedelta(days=1); lo = hi.replace(day=1)
    else:
        r = box.date_input("From – to", value=(t - timedelta(days=6), t), key=f"{kp}_rng", format="DD/MM/YYYY")
        lo, hi = (r if isinstance(r, (list, tuple)) and len(r) == 2 else (t, t))
    return lo.strftime("%Y-%m-%d"), hi.strftime("%Y-%m-%d"), p

def _median(xs):
    xs = sorted(x for x in xs if x is not None)
    if not xs:
        return None
    n = len(xs)
    return xs[n // 2] if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2

def league_score(raw, metrics):
    """raw: {name: {key: value or None}} -> {name: (score, {key: points})}"""
    best = {}
    for k, _, _, hib, _ in metrics:
        vals = [v[k] for v in raw.values() if v.get(k) is not None]
        if vals:
            best[k] = max(vals) if hib else min(vals)
    out = {}
    for name, v in raw.items():
        pts, wsum, tot = {}, 0, 0.0
        for k, _, w, hib, _ in metrics:
            x, b = v.get(k), best.get(k)
            if x is None or b is None:
                continue
            if hib:
                p = 100.0 * x / b if b else 100.0
            else:
                p = 100.0 * b / x if x else 100.0
            pts[k] = min(100.0, p)
            tot += pts[k] * w
            wsum += w
        out[name] = (round(tot / wsum, 1) if wsum else None, pts)
    return out

def _fmt_metric(v, unit):
    if v is None:
        return "—"
    if unit == "%":
        return f"{round(v)}%"
    if unit == "min":
        return fmt_age(int(v))
    return f"{round(v, 1)} {unit}".strip()

@st.cache_data(ttl=600, show_spinner=False)
def league_stock_raw(lo, hi):
    """Per warehouse/area metrics for bills registered between lo and hi"""
    areas = load_areas()
    jr = build_bill_journeys(lo, hi, hi)
    raw = {a: {"_bills": 0} for a in areas}
    speed, same, qual = {a: [] for a in areas}, {a: [] for a in areas}, {a: [] for a in areas}
    for b in jr:
        a = (b["d"] or {}).get("area", "")
        if a not in raw:
            continue
        raw[a]["_bills"] += 1
        arr, up = b.get("arrived"), b.get("uploaded")
        if arr and up and up >= arr:
            speed[a].append((up - arr).total_seconds() / 60)
        if arr:
            same[a].append(1 if (up and up.date() == arr.date()) else 0)
        cc = b["stages"][0]
        has_reg_photo = bool((b["d"] or {}).get("invoice_image"))
        has_cc_photo = bool(cc.get("task") and ((cc["task"].get("details") or {}).get("bill_check_image")))
        if up:
            qual[a].append(1 if (has_reg_photo and cc.get("task") and has_cc_photo) else 0)
    # cross check speed (sec per item) by area
    chk = {a: [] for a in areas}
    for t in fetch_all("daily_tasks", lambda q: q.eq("task_type", "Bill Cross Check").gte("date", lo).lte("date", hi)):
        d = t.get("details") or {}
        n = _to_float(d.get("no_items"), 0)
        s = task_secs(t)
        if d.get("area") in chk and n > 0 and s:
            chk[d.get("area")].append(s / n)
    # customer items received by their promised time
    ont = {a: [] for a in areas}
    try:
        lines = fetch_all("customer_order_lines", lambda q: q.gte("scheduled_date", lo).lte("scheduled_date", hi))
    except Exception:
        lines = []
    for l in lines:
        a = l.get("area")
        if a not in ont or l.get("removed") or not l.get("delivery_time"):
            continue
        if l.get("status") != "Received":
            continue
        di = due_info(l, to_ist(l.get("completed_at")) or now_ist())
        if di:
            ont[a].append(1 if di[1] >= 0 else 0)
    ent = {a: [] for a in areas}
    prf = {a: [] for a in areas}
    for b in jr:
        a = (b["d"] or {}).get("area", "")
        if a in ent:
            prf[a].append(1 if b.get("arr_src") != "⚠️ none" else 0)
            if b.get("arr_src") != "⚠️ none" and b.get("entry_delay") is not None:
                ent[a].append(b["entry_delay"])
    for a in areas:
        raw[a].update({
            "entry": _median(ent[a]),
            "proof": 100.0 * sum(prf[a]) / len(prf[a]) if prf[a] and any(prf[a]) else None,
            "speed": _median(speed[a]),
            "sameday": 100.0 * sum(same[a]) / len(same[a]) if same[a] else None,
            "ontime": 100.0 * sum(ont[a]) / len(ont[a]) if ont[a] else None,
            "check": _median(chk[a]),
            "quality": 100.0 * sum(qual[a]) / len(qual[a]) if qual[a] else None,
        })
    return {a: v for a, v in raw.items() if v["_bills"]}

def _present_days(lo, hi):
    """{person: set(dates)} from clock-ins"""
    out = {}
    try:
        for e in fetch_all("attendance_log", lambda q: q.eq("event", "clock_in").gte("date", lo).lte("date", hi)):
            out.setdefault(e.get("person"), set()).add(e.get("date"))
    except Exception:
        pass
    return out

def _present_hours(lo, hi):
    """{person: hours present (clock in -> out, minus breaks)}"""
    out = {}
    try:
        ev = fetch_all("attendance_log", lambda q: q.gte("date", lo).lte("date", hi))
    except Exception:
        return out
    by = {}
    for e in ev:
        by.setdefault((e.get("person"), e.get("date")), []).append(e)
    for (p, d), es in by.items():
        s = att_state(sorted(es, key=lambda e: str(e.get("at"))))
        if s["clock_in"]:
            end = s["clock_out"] or (now_ist() if d == date_str() else s["clock_in"])
            out[p] = out.get(p, 0) + max(0, (end - s["clock_in"]).total_seconds() - s["break_secs"]) / 3600
    return out

@st.cache_data(ttl=600, show_spinner=False)
def league_delivery_raw(lo, hi):
    people = delivery_people()
    pk = [t for t in fetch_all("daily_tasks", lambda q: q.eq("task_type", "Pickup").gte("date", lo).lte("date", hi))
          if t.get("status") != "In Progress"]
    days = _present_days(lo, hi)
    try:
        kms = fetch_all("km_log", lambda q: q.gte("date", lo).lte("date", hi))
    except Exception:
        kms = []
    raw = {}
    for p in sorted(set(people) | {t.get("person") for t in pk if t.get("person")}):
        mine = [t for t in pk if t.get("person") == p]
        ot = [(t.get("details") or {}).get("on_time") for t in mine if (t.get("details") or {}).get("on_time")]
        nd = len(days.get(p, set())) or len({t.get("date") for t in mine})
        km = sum(float(k.get("km") or 0) for k in kms if k.get("person") == p and k.get("km") is not None)
        raw[p] = {"_pickups": len(mine), "_days": nd,
                  "ontime": 100.0 * sum(1 for x in ot if x == "Yes") / len(ot) if ot else None,
                  "perday": len(mine) / nd if nd else None,
                  "kmper": km / len(mine) if km and mine else None}
    return {p: v for p, v in raw.items() if v["_pickups"] or v["_days"]}

@st.cache_data(ttl=600, show_spinner=False)
def league_call_raw(lo, hi):
    calls = fetch_all("daily_tasks", lambda q: q.eq("task_type", "Call Log").gte("date", lo).lte("date", hi))
    hours = _present_hours(lo, hi)
    try:
        lines = fetch_all("customer_order_lines", lambda q: q.gte("delivery_at", lo).lte("delivery_at", hi + "T23:59:59+05:30"))
    except Exception:
        lines = []
    people = sorted({u["name"] for u in (load_users() or {}).values() if u.get("team") == "Call"}
                    | {t.get("person") for t in calls if t.get("person")}
                    | {l.get("delivery_by") for l in lines if l.get("delivery_by")})
    # order ready time = when its last line was completed
    ready = {}
    for l in lines:
        c = to_ist(l.get("completed_at"))
        if c:
            ready[l.get("order_no")] = max(ready.get(l.get("order_no"), c), c)
    raw = {}
    for p in people:
        n_calls = sum(_to_float((t.get("details") or {}).get("calls_made"), 0) for t in calls if t.get("person") == p)
        mine = [l for l in lines if l.get("delivery_by") == p]
        dl = sum(1 for l in mine if l.get("delivery_status") == "Delivered")
        nd = sum(1 for l in mine if l.get("delivery_status") == "Not Delivered")
        waits = []
        for o in {l.get("order_no") for l in mine}:
            r = ready.get(o)
            m = min((to_ist(l.get("delivery_at")) for l in mine if l.get("order_no") == o and to_ist(l.get("delivery_at"))),
                    default=None)
            if r and m and m >= r:
                waits.append((m - r).total_seconds() / 60)
        h = hours.get(p, 0)
        raw[p] = {"_calls": int(n_calls), "_marked": dl + nd,
                  "conv": 100.0 * dl / (dl + nd) if dl + nd else None,
                  "speed": _median(waits),
                  "cph": n_calls / h if h and n_calls else None}
    return {p: v for p, v in raw.items() if v["_calls"] or v["_marked"]}

def league_table(raw, metrics, name_col):
    sc = league_score(raw, metrics)
    order = sorted(raw, key=lambda n: -(sc[n][0] or -1))
    medals = ["🥇", "🥈", "🥉"]
    rows = []
    for i, n in enumerate(order):
        s, pts = sc[n]
        weak = min(pts, key=pts.get) if pts else None
        r = {"#": medals[i] if i < 3 else str(i + 1), name_col: n, "Score": s if s is not None else "—"}
        for k, label, w, hib, unit in metrics:
            r[label] = _fmt_metric(raw[n].get(k), unit)
        r["Work on"] = next((l for k, l, *_ in metrics if k == weak), "") if weak and pts[weak] < 95 else "—"
        rows.append(r)
    return pd.DataFrame(rows), order, sc

def show_league(kp="lg"):
    st.subheader("🏆 League")
    st.caption("Trial — scores compare everyone with the best in the league for the period (best = 100 for each metric). "
               "Weights can be changed after the trial.")
    c1, c2 = st.columns([2, 1])
    with c2:
        lo, hi, plabel = league_period(kp)
    with c1:
        board = st.radio("Board", ["🏬 Stock warehouses", "🛵 Delivery", "📞 Call team"], horizontal=True, key=f"{kp}_b")
    st.caption(f"{lo} → {hi}")
    if board.startswith("🏬"):
        raw = league_stock_raw(lo, hi)
        if not raw:
            st.info("No bills in this period.")
            return
        df, order, sc = league_table(raw, STOCK_METRICS, "Warehouse")
        df.insert(3, "Bills", [raw[n]["_bills"] for n in order])
        st.dataframe(df, hide_index=True, width='stretch')
        st.caption("Weights: " + " · ".join(f"{l} {w}%" for _, l, w, *_ in STOCK_METRICS))
        with st.expander("💰 Prize for the winning warehouse (split by days present)"):
            pool = st.number_input("Prize pool ₹", min_value=0, step=500, value=3000, key=f"{kp}_pool")
            win = order[0]
            days = _present_days(lo, hi)
            staff = {}
            try:
                for r in fetch_all("work_area_log", lambda q: q.gte("date", lo).lte("date", hi)):
                    if r.get("area") == win and r.get("date") in days.get(r.get("person"), set()):
                        staff.setdefault(r.get("person"), set()).add(r.get("date"))
            except Exception:
                pass
            if not staff:
                st.caption(f"🥇 {win} — no staff area records for this period (needs 📍 area selection).")
            else:
                tot = sum(len(v) for v in staff.values())
                pay = pd.DataFrame([{"Person": p, "Days in " + win: len(d), "Share ₹": round(pool * len(d) / tot)}
                                    for p, d in sorted(staff.items(), key=lambda kv: -len(kv[1]))])
                st.markdown(f"**🥇 {win}** — ₹{pool:,} shared by {len(staff)} people")
                st.dataframe(pay, hide_index=True, width='stretch')
    else:
        is_del = board.startswith("🛵")
        raw = league_delivery_raw(lo, hi) if is_del else league_call_raw(lo, hi)
        metrics = DELIVERY_METRICS if is_del else CALL_METRICS
        if not raw:
            st.info("No activity in this period.")
            return
        df, order, sc = league_table(raw, metrics, "Person")
        if is_del:
            df.insert(3, "Pickups", [raw[n]["_pickups"] for n in order])
        else:
            df.insert(3, "Calls", [raw[n]["_calls"] for n in order])
            df.insert(4, "Orders marked", [raw[n]["_marked"] for n in order])
        st.dataframe(df, hide_index=True, width='stretch')
        st.caption("Weights: " + " · ".join(f"{l} {w}%" for _, l, w, *_ in metrics))
        prize = st.number_input("Prize for #1 ₹", min_value=0, step=100, value=1000, key=f"{kp}_p_{board[:2]}")
        st.markdown(f"🥇 **{order[0]}** — ₹{prize:,}")

def league_mini(team):
    """Small live board on the team's home screen (this week)"""
    from datetime import timedelta
    t = today_ist()
    lo, hi = (t - timedelta(days=t.weekday())).strftime("%Y-%m-%d"), t.strftime("%Y-%m-%d")
    try:
        if team == "Stock":
            raw, metrics, me = league_stock_raw(lo, hi), STOCK_METRICS, st.session_state.get("work_area")
        elif team == "Delivery":
            raw, metrics, me = league_delivery_raw(lo, hi), DELIVERY_METRICS, st.session_state.name
        elif team == "Call":
            raw, metrics, me = league_call_raw(lo, hi), CALL_METRICS, st.session_state.name
        else:
            return
    except Exception:
        return
    if len(raw) < 2:
        return
    sc = league_score(raw, metrics)
    order = sorted(raw, key=lambda n: -(sc[n][0] or -1))
    medals = ["🥇", "🥈", "🥉"]
    lines = [f"{medals[i] if i < 3 else i + 1} {'**' if n == me else ''}{n}{'**' if n == me else ''} — {sc[n][0]}"
             for i, n in enumerate(order)]
    tip = ""
    if me in sc and sc[me][1]:
        weak = min(sc[me][1], key=sc[me][1].get)
        if sc[me][1][weak] < 95:
            tip = "  ·  your weakest: " + next(l for k, l, *_ in metrics if k == weak)
    with st.expander("🏆 League — this week: " + " · ".join(lines[:3]) , expanded=False):
        st.markdown("\n\n".join(lines))
        if tip:
            st.caption(tip.strip(" ·"))

# ── ADMIN DASHBOARD ───────────────────────────────────────────────────────────

# ══════════════════════════════════════════════════════════════════════════════
# 📦 PHOTO ARCHIVE — weekly ZIP download + safe cleanup (keeps Supabase under 1 GB)
#   A photo is deleted from Supabase ONLY when it is older than N days (default 7)
#   AND admin has confirmed the ZIP containing it was saved.
#   Records (bill no, amount, person, timings, league) are never deleted.
# ══════════════════════════════════════════════════════════════════════════════
import json
STORAGE_LIMIT_GB = 1.0
PHOTO_TABLES = [            # (table, date column, kind of date) — rows are scanned for photo file names
    ("daily_tasks", "date", "text"),
    ("arrangements", "created_at", "ts"),
    ("porter_bookings", "created_at", "ts"),
    ("km_log", "date", "text"),
]
_PHOTO_KIND = {"bill_check": "Bill check", "bill_arr": "Bill upload", "bill": "Bill", "arr": "Arrangement order",
               "pickup": "Pickup medicines", "placement": "Placement", "invoice": "Invoice", "handover": "Porter handover",
               "dist_recv": "Received from distributor", "receipt": "Porter receipt", "payment": "Payment",
               "bounce": "Bounce study", "km_start": "KM start", "km_end": "KM end"}
_FILE_RE = re.compile(r"[A-Za-z0-9_\-]+\.(?:jpg|jpeg|png|pdf)", re.I)
_NAME_TS = re.compile(r"^(.*?)_(\d{8})_(\d{6})")


def get_app_setting(key, default=None):
    try:
        r = supabase.table("app_settings").select("value").eq("key", key).execute().data
        return r[0]["value"] if r else default
    except Exception:
        return default


def set_app_setting(key, value):
    supabase.table("app_settings").upsert({"key": key, "value": str(value)}, on_conflict="key").execute()


def photo_keep_days():
    try:
        return max(1, int(float(get_app_setting("photo_keep_days", 7))))
    except Exception:
        return 7


def _photo_info_from_name(name, created_at=""):
    """prefix + photo date/time from the file name (bill_20261005_104233_ab12.jpg); falls back to storage time"""
    m = _NAME_TS.match(name)
    if m:
        prefix, d, t = m.groups()
        try:
            dt = datetime.strptime(d + t, "%Y%m%d%H%M%S")
            return prefix, dt.strftime("%Y-%m-%d"), dt.strftime("%I-%M%p").lower()
        except ValueError:
            pass
    prefix = name.split("_")[0] if "_" in name else "photo"
    try:
        dt = datetime.fromisoformat(str(created_at).replace("Z", "+00:00")).astimezone(IST)
        return prefix, dt.strftime("%Y-%m-%d"), dt.strftime("%I-%M%p").lower()
    except Exception:
        return prefix, "unknown-date", ""


def _kind_of(prefix):
    if prefix.startswith("receipt"):
        return "Porter receipt"
    return _PHOTO_KIND.get(prefix, prefix.replace("_", " ").title())


def _list_storage_raw():
    """every file in the Images bucket: [{name, size, created_at}] (raises on error)"""
    out, offset = [], 0
    bucket = supabase.storage.from_("Images")
    while True:
        batch = bucket.list("", {"limit": 1000, "offset": offset, "sortBy": {"column": "name", "order": "asc"}}) or []
        for f in batch:
            if f.get("id") is None:          # a folder, not a file
                continue
            meta = f.get("metadata") or {}
            out.append({"name": f["name"], "size": int(meta.get("size") or 0), "created_at": f.get("created_at", "")})
        if len(batch) < 1000:
            return out
        offset += 1000


@st.cache_data(ttl=600, show_spinner=False)
def _list_storage_cached():
    return _list_storage_raw()


def list_storage_files():
    try:
        return _list_storage_cached(), ""
    except Exception as e:
        return [], str(e)
list_storage_files.clear = _list_storage_cached.clear


def load_photo_archive():
    """{name: row} of photos already saved in a ZIP"""
    rows, offset = {}, 0
    try:
        while True:
            batch = supabase.table("photo_archive").select("*").range(offset, offset + 999).execute().data or []
            for r in batch:
                rows[r["name"]] = r
            if len(batch) < 1000:
                return rows
            offset += 1000
    except Exception:
        return rows


def _pick(row, *keys):
    det = row.get("details") if isinstance(row.get("details"), dict) else {}
    for k in keys:
        v = row.get(k) or det.get(k)
        if v not in (None, "", "None"):
            return str(v)
    return ""


def photo_index(names, d_from, d_to):
    """file name -> who / what / where, by scanning the rows of the days around the photos"""
    want, found = set(names), {}
    lo = (d_from - timedelta(days=3)).strftime("%Y-%m-%d")
    hi = (d_to + timedelta(days=10)).strftime("%Y-%m-%d")
    for table, col, kind in PHOTO_TABLES:
        rows, offset = [], 0
        try:
            while True:
                q = supabase.table(table).select("*")
                q = q.gte(col, lo).lte(col, hi + ("T23:59:59" if kind == "ts" else ""))
                batch = q.range(offset, offset + 999).execute().data or []
                rows += batch
                if len(batch) < 1000:
                    break
                offset += 1000
        except Exception:
            try:     # table without that date column -> latest rows
                rows = supabase.table(table).select("*").order("id", desc=True).limit(3000).execute().data or []
            except Exception:
                continue
        for r in rows:
            blob = json.dumps(r, default=str)
            hits = [n for n in set(_FILE_RE.findall(blob)) if n in want]
            if not hits:
                continue
            info = {
                "Person": _pick(r, "person", "order_by", "picked_by", "handover_by", "received_by", "booked_by", "uploaded_by"),
                "Team": _pick(r, "team"),
                "Task": _pick(r, "task_type") or table.replace("_", " ").title(),
                "Area": _pick(r, "work_area", "area", "warehouse"),
                "Distributor": _pick(r, "distributor", "distributor_name"),
                "Bill / Invoice no": _pick(r, "bill_no", "bill_number", "invoice_no", "bill_order_id"),
                "Arrangement no": _pick(r, "arrangement_no", "arr_no"),
                "Amount": _pick(r, "amount", "bill_amount", "total_amount"),
                "Record": f"{table} #{r.get('id', '')}",
            }
            for n in hits:
                if n not in found or not found[n]["Person"]:
                    found[n] = info
    return found


def _safe(s, n=30):
    s = re.sub(r"[^A-Za-z0-9\-]+", "-", str(s or "")).strip("-")
    return s[:n]


def build_photo_zip(files, d_from, d_to, progress=None):
    """ZIP: <date>/<Area>_<Person>_<Kind>_<Bill>_<time>.jpg  +  photo_index.xlsx"""
    import zipfile
    idx = photo_index([f["name"] for f in files], d_from, d_to)
    buf, rows, used = io.BytesIO(), [], set()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_STORED) as z:     # JPEGs don't shrink further; store = fast
        for i, f in enumerate(files):
            name = f["name"]
            prefix, day, tm = _photo_info_from_name(name, f.get("created_at"))
            info = idx.get(name, {})
            ext = name.rsplit(".", 1)[-1].lower() if "." in name else "jpg"
            parts = [_safe(info.get("Area"), 12), _safe(info.get("Person"), 20), _safe(_kind_of(prefix), 25),
                     _safe(info.get("Bill / Invoice no") or info.get("Arrangement no"), 20), tm]
            base = "_".join(p for p in parts if p) or _safe(name, 40)
            fn, k = f"{day}/{base}.{ext}", 2
            while fn in used:
                fn, k = f"{day}/{base}_{k}.{ext}", k + 1
            used.add(fn)
            status = "Saved"
            try:
                data = supabase.storage.from_("Images").download(name)
                if ext != "pdf":
                    data, _, _ = compress_image(data, name)     # old full-size photos shrink here too
                z.writestr(fn, data)
            except Exception as e:
                status = f"Could not download: {e}"
            rows.append({"Date": day, "Time": tm.replace("-", ":"), "Photo of": _kind_of(prefix),
                         "Person": info.get("Person", ""), "Team": info.get("Team", ""), "Task": info.get("Task", ""),
                         "Area": info.get("Area", ""), "Distributor": info.get("Distributor", ""),
                         "Bill / Invoice no": info.get("Bill / Invoice no", ""), "Arrangement no": info.get("Arrangement no", ""),
                         "Amount": info.get("Amount", ""), "File in ZIP": fn if status == "Saved" else "",
                         "Original name": name, "Record": info.get("Record", "not linked"), "Status": status})
            if progress:
                progress.progress((i + 1) / max(len(files), 1), text=f"Packing photo {i + 1} of {len(files)}")
        xbuf = io.BytesIO()
        with pd.ExcelWriter(xbuf, engine="openpyxl") as w:
            pd.DataFrame(rows).to_excel(w, index=False, sheet_name="Photos")
        z.writestr("photo_index.xlsx", xbuf.getvalue())
    ok = [r["Original name"] for r in rows if r["Status"] == "Saved"]
    return buf.getvalue(), ok, rows


def cleanup_old_photos(force=False):
    """delete photos older than keep-days that are saved in a ZIP. Runs once a day (first admin visit)."""
    today = date_str()
    if not force and get_app_setting("photo_cleanup_last") == today:
        return None
    keep = photo_keep_days()
    cutoff = (today_ist() - timedelta(days=keep)).strftime("%Y-%m-%d")
    arch = load_photo_archive()
    files, err = list_storage_files()
    if err:
        return f"Cleanup skipped — storage not reachable ({err})"
    todo = []
    for f in files:
        a = arch.get(f["name"])
        if not a or a.get("deleted_at"):
            continue
        _, day, _ = _photo_info_from_name(f["name"], f.get("created_at"))
        if day != "unknown-date" and day < cutoff:
            todo.append(f["name"])
    done = 0
    for i in range(0, len(todo), 100):
        chunk = todo[i:i + 100]
        try:
            supabase.storage.from_("Images").remove(chunk)
            supabase.table("photo_archive").update({"deleted_at": now_iso()}).in_("name", chunk).execute()
            done += len(chunk)
        except Exception as e:
            return f"Cleanup stopped after {done} photos: {e}"
    try:
        set_app_setting("photo_cleanup_last", today)
    except Exception:
        pass
    if done:
        list_storage_files.clear()
    return f"🧹 Removed {done} saved photo(s) older than {keep} days" if done else ""


def removed_photo_note(name):
    """'saved in ZIP …' text if this photo was archived and deleted, else ''"""
    try:
        r = supabase.table("photo_archive").select("zip_name,deleted_at").eq("name", str(name).strip()).execute().data
        if r and r[0].get("deleted_at"):
            return f"📷 Photo removed from the app after {photo_keep_days()} days — it is saved in **{r[0].get('zip_name', 'the weekly ZIP')}** (see photo_index.xlsx)."
    except Exception:
        pass
    return ""


def show_photo_archive(kp="ph"):
    st.subheader("📦 Photos — weekly download & cleanup")
    files, err = list_storage_files()
    if err:
        st.error("⚠️ Can't read photo storage right now (Supabase may be restricted).")
        st.caption(f"Technical detail: {err}")
        return
    arch = load_photo_archive()
    total = sum(f["size"] for f in files) / 1024 ** 3
    pct = total / STORAGE_LIMIT_GB
    c1, c2, c3 = st.columns(3)
    c1.metric("Photo storage", f"{total:.2f} GB", f"of {STORAGE_LIMIT_GB:.0f} GB free plan", delta_color="off")
    pending = [f for f in files if f["name"] not in arch]
    c2.metric("Not yet downloaded", len(pending))
    c3.metric("Keep photos for", f"{photo_keep_days()} days")
    st.progress(min(pct, 1.0), text=f"{pct * 100:.0f}% used (database is separate)")
    if pct >= 0.8:
        st.error("🔴 Storage almost full — download the ZIP and run cleanup now, or Supabase will block the app.")
    elif pct >= 0.6:
        st.warning("🟠 Storage above 60% — download this week's ZIP soon.")
    if st.button("🔄 Refresh storage numbers", key=f"{kp}_rf"):
        list_storage_files.clear()
        st.rerun()

    st.markdown("#### 1️⃣ Download photos")
    if not pending:
        st.success("✅ Every photo is already saved in a ZIP.")
    else:
        days = sorted({_photo_info_from_name(f["name"], f.get("created_at"))[1] for f in pending} - {"unknown-date"})
        first = datetime.strptime(days[0], "%Y-%m-%d").date() if days else today_ist()
        st.caption(f"Oldest photo not downloaded yet: **{first.strftime('%d %b %Y')}**. "
                   "Tip: save the ZIP inside your Google Drive folder on the computer — it goes to Drive by itself.")
        rng = st.date_input("Photos from – to", value=(first, min(first + timedelta(days=6), today_ist())),
                            max_value=today_ist(), key=f"{kp}_rng", format="DD/MM/YYYY")
        if isinstance(rng, (list, tuple)) and len(rng) == 2:
            d_from, d_to = rng
            sel = [f for f in pending
                   if d_from.strftime("%Y-%m-%d") <= _photo_info_from_name(f["name"], f.get("created_at"))[1] <= d_to.strftime("%Y-%m-%d")]
            if d_from <= first:     # undated old files ride along with the first ZIP
                sel += [f for f in pending if _photo_info_from_name(f["name"], f.get("created_at"))[1] == "unknown-date"]
            mb = sum(f["size"] for f in sel) / 1024 ** 2
            st.write(f"**{len(sel)} photos** ({mb:.0f} MB in storage — the ZIP will be smaller)")
            if len(sel) > 2500:
                st.warning("That is a lot of photos for one ZIP — pick fewer days so the app doesn't run out of memory.")
            if sel and st.button(f"📦 Prepare ZIP ({len(sel)} photos)", type="primary", key=f"{kp}_mk"):
                bar = st.progress(0.0, text="Starting…")
                data, ok, rows = build_photo_zip(sel, d_from, d_to, bar)
                zname = f"RapidSurge_photos_{d_from.strftime('%d%b')}-{d_to.strftime('%d%b%Y')}.zip"
                st.session_state[f"{kp}_zip"] = {"data": data, "ok": ok, "name": zname,
                                                 "bad": len(rows) - len(ok), "linked": sum(1 for r in rows if r["Record"] != "not linked")}
                bar.empty()
        z = st.session_state.get(f"{kp}_zip")
        if z:
            st.success(f"ZIP ready: **{len(z['ok'])} photos**, {len(z['data']) / 1024 ** 2:.1f} MB — "
                       f"{z['linked']} linked to a person/bill.")
            if z["bad"]:
                st.warning(f"{z['bad']} photo(s) could not be downloaded — they stay in the app and are not marked saved.")
            st.download_button("⬇️ Download ZIP", z["data"], file_name=z["name"], mime="application/zip",
                               key=f"{kp}_dl", type="primary")
            st.markdown("#### 2️⃣ Confirm it is saved")
            st.caption("Open the ZIP on your computer once. Only after you confirm can these photos be cleaned up later.")
            ok_box = st.checkbox("✅ I opened the ZIP and it is saved on my computer / Google Drive", key=f"{kp}_ok")
            if st.button("Mark these photos as saved", disabled=not ok_box, key=f"{kp}_mark"):
                try:
                    recs = [{"name": n, "zip_name": z["name"], "archived_at": now_iso(),
                             "archived_by": st.session_state.name} for n in z["ok"]]
                    for i in range(0, len(recs), 500):
                        supabase.table("photo_archive").upsert(recs[i:i + 500], on_conflict="name").execute()
                    st.session_state.pop(f"{kp}_zip", None)
                    st.success(f"✅ {len(recs)} photos marked as saved. They will be removed from the app "
                               f"once they are older than {photo_keep_days()} days.")
                    st.rerun()
                except Exception as e:
                    st.error(f"Could not mark photos: {e} — did you run photo_archive_setup.sql?")

    st.markdown("#### 3️⃣ Cleanup")
    keep = photo_keep_days()
    cutoff = (today_ist() - timedelta(days=keep)).strftime("%Y-%m-%d")
    ready = [f for f in files if f["name"] in arch and not arch[f["name"]].get("deleted_at")
             and _photo_info_from_name(f["name"], f.get("created_at"))[1] < cutoff]
    waiting = [f for f in files if f["name"] not in arch
               and _photo_info_from_name(f["name"], f.get("created_at"))[1] < cutoff]
    st.write(f"Ready to remove (saved + older than {keep} days): **{len(ready)}** "
             f"({sum(f['size'] for f in ready) / 1024 ** 2:.0f} MB)")
    if waiting:
        st.info(f"{len(waiting)} photo(s) are older than {keep} days but NOT downloaded yet — they are kept until you save them.")
    st.caption("Cleanup also runs by itself once a day when admin opens the app.")
    if ready and st.button(f"🧹 Remove {len(ready)} saved photos now", key=f"{kp}_cl"):
        msg = cleanup_old_photos(force=True)
        st.success(msg or "Nothing to remove.")
        st.rerun()

    with st.expander("⚙️ Settings"):
        nd = st.number_input("Keep photos in the app for (days)", 1, 90, keep, key=f"{kp}_kd",
                             help="Photos stay viewable in the app this long, even after you download them.")
        if st.button("Save", key=f"{kp}_sv"):
            try:
                set_app_setting("photo_keep_days", int(nd))
                st.success("Saved")
            except Exception as e:
                st.error(f"Could not save: {e} — did you run photo_archive_setup.sql?")



# ══════════════════════════════════════════════════════════════════════════════
# 🎯 WORK BLOCKS (plan the next 1–2 hours) + 🔎 REVIEWS (1:30 PM · 5:30 PM · 8 PM · full day)
#   Teams: Stock, Purchase, Call (Delivery later). Managers / admin are not asked to plan.
#   Progress is counted automatically from tasks the person finishes during the block.
# ══════════════════════════════════════════════════════════════════════════════
BLOCK_TEAMS = ("Stock", "Purchase", "Call")
BLOCK_HOURS = (1, 2)
BLOCK_SKIP_MINS = 20
BLOCK_REASONS = ["Waiting for bills / stock", "Called for other work", "Phone / app issue",
                 "Customer urgent work", "Planned too much", "Other"]
_OTHER_TYPES = ["Other", "Other Task", "Purchase Return", "Rack Cleaning", "Inventory Check", "Inventory",
                "Porter Receipt", "Distributor Delivery Receipt", "Order Import", "Order Sheet Upload",
                "PharmaRack Search", "Medicine Search", "Bounce Medicine Study", "Assigned Task"]
PLAN_ITEMS = {   # key, label, task types counted (or a special counter)
    "Stock": [("crosscheck", "✔️ Bill Cross Check", ["Bill Cross Check"]),
              ("upload", "📤 Bill Upload", ["Bill Upload (Software)", "Bill Upload"]),
              ("placement", "📍 Placement", "placement"),
              ("register", "📒 Register Entry", ["Register Entry"]),
              ("storepick", "🏪 In-Store Pick", "storepick")],
    "Purchase": [("po", "💊 Medicines to order — Purchase / Order Sheet", ("sum", ["Purchase Order"], "no_sku")),
                 ("arr", "💊 Medicines to order — Arrangement", ("sum", ["Arrangement Order", "Arrangement"], "no_medicines")),
                 ("register", "📒 Register Entry", ["Register Entry"]),
                 ("crosscheck", "✔️ Bill Cross Check", ["Bill Cross Check"])],
    "Call": [("calls", "📞 Calls made", "calls"),
             ("marked", "🚚 Delivery status marked", "marked")],
}
PLAN_HELP = {
    "crosscheck": "1 = one bill cross-checked", "upload": "1 = one bill uploaded in the software",
    "placement": "1 = one bill placed on the racks by you (warehouse-team placements don't count)",
    "register": "1 = one distributor bill entered", "storepick": "1 = one customer medicine picked from the shelf",
    "arr": "How many medicines you will order through arrangement orders (an order of 3 medicines = 3)",
    "po": "How many medicines (SKUs) you will order — Purchase Order or Order Sheet (an order of 12 SKUs = 12)",
    "return": "1 = one purchase return entry", "calls": "1 = one call made (from your Call Log)",
    "marked": "1 = one customer medicine marked Delivered / Not delivered",
}
PLAN_MAX_PER_HR = 30          # no history at all -> anything above this per hour is surely a typo
REVIEW_SLOTS = [("mid", "1:30 PM", (13, 30)), ("eve", "5:30 PM", (17, 30)), ("night", "8:00 PM", (20, 0))]
RATINGS = {"green": "🟢 On track", "orange": "🟠 Needs push", "red": "🔴 Problem"}


def _naive(dt):
    """any datetime -> naive IST (so DB times and task times compare safely)"""
    if dt is None:
        return None
    if getattr(dt, "tzinfo", None):
        return dt.astimezone(IST).replace(tzinfo=None)
    return dt


def _now_n():
    return _naive(now_ist())


def _iso(dt_naive):
    return IST.localize(dt_naive).isoformat()


def is_planner(user_team=None, role=None):
    team = user_team if user_team is not None else st.session_state.get("team")
    role = role if role is not None else st.session_state.get("role")
    return team in BLOCK_TEAMS and role not in ("admin", "manager")


def is_reviewer():
    return st.session_state.get("role") in ("admin", "manager")


# ── counting what was done ────────────────────────────────────────────────────
def _tasks_of(person, lo_n, hi_n, by_start=False):
    """finished tasks of a person between two naive-IST datetimes
    (by_start: by the time the task STARTED — a task begun near the end of a block finishes after it)"""
    days = sorted({lo_n.strftime("%Y-%m-%d"), hi_n.strftime("%Y-%m-%d")})
    try:
        rows = fetch_all("daily_tasks", lambda q: q.eq("person", person).gte("date", days[0]).lte("date", days[-1]))
    except Exception:
        return []
    out = []
    for t in rows:
        if t.get("status") == "In Progress":
            continue
        when = _naive(_task_dt(t, "end_time")) or _naive(to_ist(t.get("created_at")))
        if by_start:
            s_ = _naive(_task_dt(t, "start_time"))
            if s_ and when and s_ > when:              # crossed midnight
                s_ -= timedelta(days=1)
            when = s_ or when
            if when and lo_n <= when < hi_n:
                t["_when"] = when
                out.append(t)
            continue
        if when and lo_n <= when <= hi_n:
            t["_when"] = when
            out.append(t)
    return out


def _amount(how, tasks):
    """count / sum for an item from a list of tasks (None = needs another table)"""
    if isinstance(how, list):
        return sum(1 for t in tasks if t.get("task_type") in how)
    if isinstance(how, tuple) and how[0] == "sum":
        return int(sum(_to_float((t.get("details") or {}).get(how[2]), 0) for t in tasks if t.get("task_type") in how[1]))
    if how == "calls":
        return int(sum(_to_float((t.get("details") or {}).get("calls_made"), 0)
                       for t in tasks if t.get("task_type") == "Call Log"))
    if how == "placement":
        return sum(1 for t in tasks if t.get("task_type") == "Stock Placement"
                   and (t.get("details") or {}).get("placed_by_type") != "Warehouse team")
    return None


def _count_item(how, person, tasks, lo_n, hi_n):
    n = _amount(how, tasks)
    if n is not None:
        return n
    col_by, col_at = {"storepick": ("store_checked_by", "store_checked_at"),
                      "marked": ("delivery_by", "delivery_at")}[how]
    try:
        rows = supabase.table("customer_order_lines").select(f"{col_by},{col_at}").eq(col_by, person)\
            .gte(col_at, _iso(lo_n)).lte(col_at, _iso(hi_n)).execute().data or []
    except Exception:
        return 0
    return len(rows)


def block_progress(block, upto=None):
    """[(label, target, done)], percent (None if nothing countable)"""
    lo = _naive(to_ist(block.get("start_at")))
    hi = upto or min(_now_n(), block_end(block))
    items = block.get("items") or []
    if not lo or not items:
        return [], None
    person = block.get("person")
    tasks = _tasks_of(person, lo, hi, by_start=True)
    hows = {k: how for k, _, how in PLAN_ITEMS.get(block.get("team"), [])}
    rows, parts = [], []
    for it in items:
        tgt = int(it.get("target") or 0)
        if it.get("self"):                      # "Other" work: the person tells us at the end
            done = it.get("done")
            rows.append((it.get("label", "Other"), tgt, done))
            if tgt > 0 and done is not None:
                parts.append(min(done / tgt, 1.0))
            continue
        how = hows.get(it.get("key"))
        done = _count_item(how, person, tasks, lo, hi) if how else 0
        rows.append((it.get("label", it.get("key")), tgt, done))
        if tgt > 0:
            parts.append(min(done / tgt, 1.0))
    return rows, (round(100 * sum(parts) / len(parts)) if parts else None)


@st.cache_data(ttl=60, show_spinner=False)
def _break_secs_between(person, lo_n, hi_n):
    """seconds on break between two times (breaks don't eat into a block)"""
    try:
        ev = supabase.table("attendance_log").select("event,at").eq("person", person)\
            .eq("date", lo_n.strftime("%Y-%m-%d")).order("at").execute().data or []
    except Exception:
        return 0
    tot, start = 0, None
    for e in ev:
        t = _naive(to_ist(e.get("at")))
        if e.get("event") == "break_start":
            start = t
        elif e.get("event") in ("break_end", "clock_out") and start:
            a, b = max(start, lo_n), min(t, hi_n)
            tot += max(0, (b - a).total_seconds())
            start = None
    if start:
        a, b = max(start, lo_n), hi_n
        tot += max(0, (b - a).total_seconds())
    return tot


def block_end(block):
    """planned end + any break taken inside the block"""
    s = _naive(to_ist(block.get("start_at")))
    e = _naive(to_ist(block.get("end_at")))
    if not s or not e:
        return _now_n()
    if block.get("kind") == "skip":
        return e
    return e + timedelta(seconds=_break_secs_between(block.get("person"), s, e + timedelta(hours=3)))


def _usual_pace(person, team):
    """{item key: per hour} from the last 7 days (excluding today)"""
    lo = (today_ist() - timedelta(days=7)).strftime("%Y-%m-%d")
    hi = (today_ist() - timedelta(days=1)).strftime("%Y-%m-%d")
    try:
        rows = [t for t in fetch_all("daily_tasks", lambda q: q.eq("person", person).gte("date", lo).lte("date", hi))
                if t.get("status") != "In Progress"]
    except Exception:
        return {}
    hours = max(_present_hours(lo, hi).get(person, 0), 0)
    if hours < 2:                                   # no clock-in history -> 8 h per day with tasks
        hours = 8 * len({t.get("date") for t in rows})
    if hours < 2:
        return {}
    out = {}
    for k, _, how in PLAN_ITEMS.get(team, []):
        n = _amount(how, rows) or 0
        if n:
            out[k] = n / hours
    return out


@st.cache_data(ttl=1800, show_spinner=False)
def _team_pace(team):
    """{item key: per person-hour} for a whole team over the last 7 days"""
    lo = (today_ist() - timedelta(days=7)).strftime("%Y-%m-%d")
    hi = (today_ist() - timedelta(days=1)).strftime("%Y-%m-%d")
    users = load_users() or {}
    members = {u.get("name") for u in users.values() if u.get("team") == team}
    try:
        rows = [t for t in fetch_all("daily_tasks", lambda q: q.eq("team", team).gte("date", lo).lte("date", hi))
                if t.get("status") != "In Progress" and t.get("person") in members]
    except Exception:
        return {}
    ph = _present_hours(lo, hi)
    hours, days_by = 0, {}
    for t in rows:
        days_by.setdefault(t.get("person"), set()).add(t.get("date"))
    for p, ds in days_by.items():
        hours += ph.get(p) if ph.get(p, 0) >= 2 else 8 * len(ds)
    if hours < 4:
        return {}
    out = {}
    for k, _, how in PLAN_ITEMS.get(team, []):
        n = _amount(how, rows) or 0
        if n:
            out[k] = n / hours
    return out


def _need_order_lines():
    """customer medicines that still have to be ordered from a distributor"""
    return [l for l in get_open_lines(None)
            if l.get("remainder_note") not in ("In Store", "Not Available") and remaining_qty(l) > 0]


@st.cache_data(ttl=120, show_spinner=False)
def purchase_pending():
    """what is waiting for the purchase team right now (default view: overdue + today)"""
    out = {}
    try:
        today = date_str()
        lo3 = (today_ist() - timedelta(days=3)).strftime("%Y-%m-%d")
        out["arr"] = sum(1 for l in _need_order_lines() if lo3 <= (l.get("scheduled_date") or "") <= today)
    except Exception:
        pass
    try:
        rows = fetch_all("order_sheet_lines", lambda q: q.eq("sheet_date", date_str()).eq("status", "Pending"))
        out["po"] = sum(1 for l in rows if not l.get("superseded_by"))
    except Exception:
        pass
    out["crosscheck"] = stock_pending("All Areas").get("crosscheck", 0)
    return out


def pending_view(team, key, area):
    """📦 View & filter the pending work behind a plan line"""
