# ══════════════════════════════════════════════════════════════════════════════
# 📋 REPORTS — 👤 Staff summary (what each person did) · 📍 Area summary (where we are lagging)
# Read-only: built from daily_tasks, attendance_log, work_area_log, bill_arrivals, bounce_items,
# customer_order_lines and the normal-order follow-up. No new tables.
# ══════════════════════════════════════════════════════════════════════════════
REP_PERIODS = ["Today", "Yesterday", "This week", "Last 10 days", "Weekly (last 4 weeks)",
               "Monthly (last 3 months)", "📅 Custom dates"]
REP_REST_MINS = 15          # no task and no break for this long (between clock-in and clock-out) = rest time
REP_FLAG = 0.25             # 25% worse / better than the area's own last-4-weeks average -> 🔴 / 🟢
REP_BASE_DAYS = 28
REP_BASE_MIN_DAYS = 5       # flags start once the area has this many working days in the last 4 weeks


def _ds(d):
    return d.strftime("%Y-%m-%d")


def _rep_weeks(lo, hi):
    out, s = [], lo - timedelta(days=lo.weekday())
    while s <= hi:
        e = s + timedelta(days=6)
        a, b = max(s, lo), min(e, hi)
        out.append((f"{a.strftime('%d %b')}–{b.strftime('%d %b')}", a, b))
        s = e + timedelta(days=1)
    return out


def _rep_months(lo, hi):
    out, s = [], lo.replace(day=1)
    while s <= hi:
        nxt = (s.replace(day=28) + timedelta(days=4)).replace(day=1)
        out.append((s.strftime("%b %Y"), max(s, lo), min(nxt - timedelta(days=1), hi)))
        s = nxt
    return out


def rep_buckets(choice, today, custom=None):
    """-> (lo, hi, [(label, from, to)]) for a period choice"""
    if choice == "Today":
        lo = hi = today
    elif choice == "Yesterday":
        lo = hi = today - timedelta(days=1)
    elif choice == "This week":
        lo, hi = today - timedelta(days=today.weekday()), today
    elif choice == "Last 10 days":
        lo, hi = today - timedelta(days=9), today
    elif choice.startswith("Weekly"):
        lo, hi = today - timedelta(days=today.weekday()) - timedelta(weeks=3), today
        return lo, hi, _rep_weeks(lo, hi)
    elif choice.startswith("Monthly"):
        m = today.replace(day=1)
        for _ in range(2):
            m = (m - timedelta(days=1)).replace(day=1)
        return m, today, _rep_months(m, today)
    else:
        lo, hi = custom
        if (hi - lo).days > 13:
            return lo, hi, _rep_weeks(lo, hi)
    days = [(d.strftime("%a %d/%m"), d, d) for d in (lo + timedelta(days=i) for i in range((hi - lo).days + 1))]
    return lo, hi, days


def report_period(kp):
    today = today_ist()
    c1, c2 = st.columns([2, 3])
    with c1:
        choice = st.selectbox("Period", REP_PERIODS, key=f"{kp}_per")
    custom = None
    if choice.startswith("📅"):
        with c2:
            v = st.date_input("From – to", value=(today - timedelta(days=6), today), max_value=today, key=f"{kp}_dates")
        v = list(v) if isinstance(v, (list, tuple)) else [v]
        custom = (v[0], v[-1]) if v else (today, today)
    lo, hi, buckets = rep_buckets(choice, today, custom)
    with c2 if not custom else st.container():
        st.caption(f"📅 {lo.strftime('%d %b %Y')} → {hi.strftime('%d %b %Y')} · {(hi - lo).days + 1} day(s)")
    return lo, hi, buckets


def _rep_load_people(lo_s, hi_s):
    tasks = fetch_all("daily_tasks", lambda q: q.gte("date", lo_s).lte("date", hi_s))
    try:
        att = fetch_all("attendance_log", lambda q: q.gte("date", lo_s).lte("date", hi_s))
    except Exception:
        att = []
    try:
        wal = fetch_all("work_area_log", lambda q: q.gte("date", lo_s).lte("date", hi_s))
    except Exception:
        wal = []
    return tasks, att, wal


@_lru_cache(maxsize=5000)
def _rep_day0(day_s):
    return datetime.strptime(day_s, "%Y-%m-%d")


def _rep_dt(day_s, tstr):
    t = parse_task_time(tstr)
    if not t:
        return None
    return _rep_day0(str(day_s)[:10]).replace(hour=t.hour, minute=t.minute, second=t.second)


def _rep_span(t):
    s = _rep_dt(t.get("date"), t.get("start_time")) or _rep_dt(t.get("date"), t.get("time"))
    e = _rep_dt(t.get("date"), t.get("end_time")) or s
    if s and e and e < s:
        e += timedelta(days=1)
    return s, e


def person_day_stats(tasks, events, day_s, now_n=None):
    """one person, one day -> clock in/out, present, work (overlaps once), lunch, other breaks, rest (15+ min idle)"""
    now_n = now_n or _now_n()
    events = sorted(events, key=lambda e: str(e.get("at")))
    s = att_state(events)
    cin, cout = _naive(s["clock_in"]), _naive(s["clock_out"])
    is_today = day_s == _ds(now_n)
    breaks, cur = [], None
    for e in events:
        t, ev = _naive(to_ist(e.get("at"))), e.get("event")
        if ev == "break_start":
            cur = (t, e.get("break_type") or "Break")
        elif ev in ("break_end", "clock_out") and cur:
            breaks.append((cur[0], t, cur[1]))
            cur = None
    if cur:
        breaks.append((cur[0], now_n if is_today else cur[0], cur[1]))
    done = [t for t in tasks if t.get("status") != "In Progress"]
    spans = [p for p in (_rep_span(t) for t in done) if p[0]]
    day_start = cin or (min(p[0] for p in spans) if spans else None)
    day_end = cout or (now_n if is_today and cin else (max(p[1] for p in spans) if spans else None))
    present = (day_end - cin).total_seconds() if cin and day_end and day_end > cin else 0
    lunch = [b for b in breaks if "lunch" in str(b[2]).lower()]
    nowork = [b for b in breaks if nw_parse(b[2])]
    other = [b for b in breaks if b not in lunch and b not in nowork]
    bsecs = lambda bs: sum(max(0, (b[1] - b[0]).total_seconds()) for b in bs)
    rest_secs, rest_n = 0, 0
    if cin and day_end and day_end > cin:          # rest time only between clock-in and clock-out
        day_start = cin
        cover = sorted([(a, b) for a, b in spans if b] + [(b[0], b[1]) for b in breaks if b[0] and b[1]])
        cursor = day_start
        for a, b in cover + [(day_end, day_end)]:
            a = max(a, day_start)
            if a > cursor and (min(a, day_end) - cursor).total_seconds() >= REP_REST_MINS * 60:
                rest_secs += (min(a, day_end) - cursor).total_seconds()
                rest_n += 1
            if b > cursor:
                cursor = b
            if cursor >= day_end:
                break
    return {"cin": cin, "cout": cout, "present": present, "work": _merged_secs(spans), "tasks": len(done),
            "lunch": bsecs(lunch), "lunch_n": len(lunch), "brk": bsecs(other), "brk_n": len(other),
            "rest": rest_secs, "rest_n": rest_n,
            "nowork": bsecs(nowork), "nowork_ok": bsecs([b for b in nowork if nw_parse(b[2])[1] == 0]),
            "nowork_list": [(b[0], b[1], nw_parse(b[2])[0], nw_parse(b[2])[1]) for b in nowork]}


def _rep_t(secs):
    return fmt_secs(secs) if secs else "—"


def _rep_inr(v):
    v = int(round(v or 0))
    s = str(abs(v))
    if len(s) > 3:
        head, tail = s[:-3], s[-3:]
        head = ",".join([head[max(0, i - 2):i] for i in range(len(head), 0, -2)][::-1])
        s = head + "," + tail
    return ("-" if v < 0 else "") + "₹" + s


# ── 👤 STAFF SUMMARY ──────────────────────────────────────────────────────────
REP_ROWS = {   # team -> [(row label, task types or a special key)]; anything else goes to "Others"
    "Stock": [("Inventory Check", ["Inventory Check"]), ("Register Entry", ["Register Entry"]),
              ("Bill Cross Check", ["Bill Cross Check"]), ("Bill Upload", ["Bill Upload (Software)", "Bill Upload"]),
              ("Stock Placement", ["Stock Placement"]), ("In-Store Pick", ["In-Store Pick Check"])],
    "Purchase": [("Order Sheet / PharmaRack", "PO_SHEET"), ("Purchase Order (other)", "PO_OTHER"),
                 ("Arrangement Order", ["Arrangement Order", "Arrangement"]), ("Purchase Return", ["Purchase Return"]),
                 ("Invoice No / Follow-up", ["Invoice No Added", "Order Follow-up"])],
    "Call": [("Call Log", ["Call Log"]), ("Customer Delivery", ["Customer Delivery Update"]),
             ("Medicine Search", ["Medicine Search"])],
    "Delivery": [("Pickup", ["Pickup"]), ("Delivery Trip", ["Delivery Trip"])],
}
REP_TEAM_ORDER = ["Stock", "Purchase", "Call", "Delivery"]


def rep_row_of(t, team):
    """row label of a task; team can be one team or a list (people who work in several teams)"""
    if isinstance(team, (list, tuple)):
        multi = len(team) > 1
        own = t.get("team") if t.get("team") in team else None
        for tm in ([own] if own else []) + [x for x in team if x != own]:
            lbl = rep_row_of(t, tm)
            if lbl != "Others":
                return (TEAM_ICON.get(tm, "") + " " + lbl) if multi else lbl
        return "Others"
    tt = t.get("task_type", "")
    for label, how in REP_ROWS.get(team, []):
        if how in ("PO_SHEET", "PO_OTHER"):
            if tt == "Purchase Order":
                sheet = (t.get("details") or {}).get("source") in ("Order Sheet", "PharmaRack Upload")
                if sheet == (how == "PO_SHEET"):
                    return label
        elif tt in how:
            return label
    return "Others"


def rep_qty(t):
    """SKU / item count of a task (0 when the task has none)"""
    d = t.get("details") or {}
    tt = t.get("task_type", "")
    num = lambda k: int(_to_float(d.get(k), 0))
    if tt == "Pickup":
        return num("no_sku_received")
    if tt == "Inventory Check":
        return num("no_items")
    if tt == "In-Store Pick Check":
        return num("picked") + num("not_found")
    return task_qty_detail(t)[0]


def _rep_speed(secs, qty, n):
    if secs and qty:
        x = secs / qty
        return f"{round(x)} secs / SKU" if x < 90 else f"{x / 60:.1f} min / SKU"
    if secs and n:
        return f"{secs / n / 60:.1f} min / task"
    return ""


@st.cache_data(ttl=300, max_entries=24, show_spinner=False)
def _staff_cached(lo_s, hi_s, users_items, extra_items=()):
    lo, hi = datetime.strptime(lo_s, "%Y-%m-%d").date(), datetime.strptime(hi_s, "%Y-%m-%d").date()
    return staff_summary_data(lo, hi, dict(users_items), extra={k: list(v) for k, v in extra_items})


def staff_summary_data(lo, hi, users, now_n=None, extra=None):
    """-> {person: {...}} totals for the period (users: {name: main team}; extra: {name: [extra teams]})"""
    extra = extra or {}
    now_n = now_n or _now_n()
    tasks, att, wal = _rep_load_people(_ds(lo), _ds(hi))
    by_pd, ev_pd, area_of = {}, {}, {}
    for t in tasks:
        if t.get("person") in users:
            by_pd.setdefault((t["person"], str(t.get("date"))[:10]), []).append(t)
    for e in att:
        if e.get("person") in users:
            ev_pd.setdefault((e["person"], str(e.get("date"))[:10]), []).append(e)
    for w in sorted(wal, key=lambda w: str(w.get("chosen_at") or "")):
        if w.get("person") in users and w.get("area"):
            area_of.setdefault(w["person"], {})
            area_of[w["person"]][w["area"]] = area_of[w["person"]].get(w["area"], 0) + 1
    out = {}
    for name, team in users.items():
        teams = [team] + [x for x in extra.get(name, []) if x != team]
        multi = len(teams) > 1
        P = {"name": name, "team": team, "teams": teams, "days": 0, "days_active": 0, "present": 0, "work": 0,
             "tasks": 0, "qty": 0, "lunch": 0, "lunch_n": 0, "brk": 0, "brk_n": 0, "rest": 0, "rest_n": 0,
             "rows": {}, "per_day": [], "team_secs": {}}
        for tm in teams:
            for label, _ in REP_ROWS.get(tm, []):
                P["rows"][(TEAM_ICON.get(tm, "") + " " + label) if multi else label] = {"n": 0, "secs": 0, "qty": 0}
        P["rows"]["Others"] = {"n": 0, "secs": 0, "qty": 0}
        d = lo
        while d <= hi:
            k = (name, _ds(d))
            tl, el = by_pd.get(k, []), ev_pd.get(k, [])
            if tl or el:
                s = person_day_stats(tl, el, _ds(d), now_n)
                P["days"] += 1 if s["cin"] else 0
                P["days_active"] += 1
                for f in ("present", "work", "tasks", "lunch", "lunch_n", "brk", "brk_n", "rest", "rest_n"):
                    P[f] += s[f]
                for t in tl:
                    if t.get("status") == "In Progress":
                        continue
                    r = P["rows"].setdefault(rep_row_of(t, teams), {"n": 0, "secs": 0, "qty": 0})
                    r["n"] += 1
                    secs = task_secs(t)
                    r["secs"] += secs
                    tm = t.get("team") if t.get("team") in teams else team
                    P["team_secs"][tm] = P["team_secs"].get(tm, 0) + secs
                    q = rep_qty(t)
                    r["qty"] += q
                    P["qty"] += q
                P["per_day"].append((_ds(d), s))
            d += timedelta(days=1)
        a = area_of.get(name) or {}
        P["area"] = max(a, key=a.get) if a else ""
        out[name] = P
    return out


def _staff_card_df(P):
    days = max(P["days_active"], 1)           # per day = per day with any work / attendance
    multi = days > 1
    rows = []
    for label, r in P["rows"].items():
        rows.append({"Task Type": label, "No": r["n"], "Total Time": _rep_t(r["secs"]),
                     "SKU / Qty": r["qty"] or "", "Speed": _rep_speed(r["secs"], r["qty"], r["n"]),
                     **({"Per day": _rep_t(r["secs"] / days)} if multi else {})})
    blank = {"Task Type": "", "No": "", "Total Time": "", "SKU / Qty": "", "Speed": "", **({"Per day": ""} if multi else {})}
    def line(lbl, n, secs, qty=""):
        return {**blank, "Task Type": lbl, "No": n, "Total Time": _rep_t(secs), "SKU / Qty": qty,
                **({"Per day": _rep_t(secs / days)} if multi else {})}
    rows += [blank,
             line("🛠️ Work time (all tasks)", P["tasks"], P["work"], P["qty"] or ""),
             line("🍱 Lunch time", P["lunch_n"], P["lunch"]),
             line("☕ Break time (Tea + Personal)", P["brk_n"], P["brk"]),
             line(f"💤 Rest time (no activity {REP_REST_MINS}+ min)", P["rest_n"], P["rest"]),
             line("⏱️ Total time (clock-in → clock-out)", P["days"], P["present"])]
    return pd.DataFrame(rows).astype(str)


def _staff_compare_df(data):
    rows = []
    for P in data:
        base = P["present"] - P["lunch"] - P["brk"]
        rows.append({"Person": P["name"], "Team": " + ".join(P.get("teams") or [P["team"]]), "Area": P["area"],
                     "Days present": P["days"],
                     "Total time": _rep_t(P["present"]), "Work time": _rep_t(P["work"]),
                     "Rest time": _rep_t(P["rest"]), "Lunch": _rep_t(P["lunch"]), "Breaks": _rep_t(P["brk"]),
                     "Tasks": P["tasks"], "SKU / Qty": P["qty"],
                     "Active %": f"{round(100 * P['work'] / base)}%" if base > 0 else "—"})
    return pd.DataFrame(rows)


# ── ⏸️ NO WORK RIGHT NOW: waiting for stock etc. — checked against the team's open work, managers give work ────
NW_REASONS = ["📦 Stock not arrived yet", "🧾 Waiting for bills / distributor", "💻 App / software / internet down",
              "🙋 Waiting for instructions", "Other"]
NW_BACKUP = {   # team -> [(button, form key, task name for ✏️ Other Task)]
    "Stock": [("📦 Inventory check", "inventory", None), ("📅 Expiry check", "other", "Expiry check"),
              ("🗄️ Rack arranging", "other", "Rack arranging"), ("🧹 Cleaning", "other", "Cleaning")],
    "Purchase": [("🧾 Follow up pending invoices", "invoice", None), ("💰 Check rates / distributors", "other", "Rate check")],
    "Call": [("📵 Call back not-reachable customers", "custdel", None), ("💬 Feedback calls", "other", "Feedback calls")],
    "Delivery": [("🏬 Help at the warehouse", "other", "Help at warehouse")],
}
NW_LIMIT_MINS = 60
NW_RED_MINS = 30


def nw_parse(bt):
    """'No work: <reason> || w=3 || 3 bills …' -> (reason, waiting count, waiting text) or None"""
    bt = str(bt or "")
    if not bt.startswith("No work"):
        return None
    parts = [p.strip() for p in bt.split("||")]
    reason = parts[0].split(":", 1)[1].strip() if ":" in parts[0] else ""
    w = int(_to_float(parts[1][2:], 0)) if len(parts) > 1 and parts[1].startswith("w=") else 0
    return reason, w, parts[2] if len(parts) > 2 else ""


def work_waiting(team, area=None):
    """open work in this person's queue right now -> (count, ['3 bills arrived, not entered', …])"""
    out = []
    try:
        if team == "Stock":
            left = sum(int(a.get("bills") or 0) - a.get("_entered", 0) for a in load_open_arrivals(1)
                       if (not area or area == "All Areas" or a.get("area") == area))
            if left > 0:
                out.append((left, f"{left} bill(s) arrived, not entered"))
            sp = stock_pending(area or "All Areas")
            for k, lbl in (("crosscheck", "to cross-check"), ("upload", "to upload"), ("placement", "to place"),
                           ("storepick", "in-store medicine(s) to pick")):
                if sp.get(k):
                    out.append((sp[k], f"{sp[k]} {'bill(s) ' if k != 'storepick' else ''}{lbl}"))
        elif team == "Purchase":
            since = IST.localize(datetime.combine(today_ist() - timedelta(days=3), datetime.min.time())).isoformat()
            n = len(fetch_all("customer_order_lines", lambda q: q.eq("removed", False).eq("status", "Pending")
                              .gte("imported_at", since)))
            if n:
                out.append((n, f"{n} customer medicine(s) not ordered"))
            inv = count_missing_invoices()
            if inv:
                out.append((inv, f"{inv} invoice no(s) to add"))
        elif team == "Call":
            n = ready_to_call_count()
            if n:
                out.append((n, f"{n} order(s) ready to call"))
        elif team == "Delivery":
            lo = (today_ist() - timedelta(days=1)).strftime("%Y-%m-%d")
            n = len(fetch_all("arrangements", lambda q: q.eq("status", "Pending").eq("pickup_type", "Self Pick")
                              .gte("order_placed_date", lo)))
            if n:
                out.append((n, f"{n} pickup(s) waiting"))
    except Exception:
        pass
    return sum(n for n, _ in out), [t for _, t in out]


def end_no_work_if_any():
    """starting real work ends '⏸️ No work' by itself"""
    try:
        ev = supabase.table("attendance_log").select("*").eq("person", st.session_state.name)\
            .eq("date", date_str()).order("at").execute().data or []
        s = att_state(ev)
        if s["on_break"] and nw_parse(s["on_break"][1]):
            att_log("break_end", s["on_break"][1])
    except Exception:
        pass


def show_no_work_start(active_key):
    """reason picker under the attendance bar"""
    with st.container(border=True):
        st.markdown("**⏸️ No work right now — why?**")
        r = st.radio("Reason", NW_REASONS, index=None, key="nw_reason", label_visibility="collapsed")
        other = st.text_input("Write the reason", key="nw_other") if r == "Other" else ""
        b1, b2 = st.columns(2)
        with b1:
            if st.button("⏸️ Start 'No work'", type="primary", key="nw_go", width='stretch'):
                if active_key:
                    st.error("Finish or cancel your running task first.")
                elif not r or (r == "Other" and not other.strip()):
                    st.error("Choose the reason (or write it).")
                else:
                    n, txt = work_waiting(st.session_state.team, st.session_state.get("work_area"))
                    reason = other.strip() if r == "Other" else r
                    att_log("break_start", f"No work: {reason} || w={n} || {'; '.join(txt)}")
                    st.session_state["nw_pick"] = False
                    st.rerun()
        with b2:
            if st.button("✖️ Cancel", key="nw_cancel", width='stretch'):
                st.session_state["nw_pick"] = False
                st.rerun()


def show_no_work_card(b_start, b_type, now):
    """while on '⏸️ No work': work waiting, tasks from managers, backup work, back to work"""
    reason, w0, _ = nw_parse(b_type)
    mins = int((now - b_start).total_seconds() // 60)
    st.warning(f"⏸️ **No work** since {b_start.strftime('%I:%M %p')} — {fmt_age(mins)} · {reason}. "
               "Your manager can see this and may give you work.")
    team = st.session_state.team
    n, txt = work_waiting(team, st.session_state.get("work_area"))
    if n:
        st.error("⚠️ There IS work waiting for your team: " + " · ".join(txt) + " — press ▶️ Back to work and do it.")
    show_my_assigned_tasks()
    opts = NW_BACKUP.get(team, [])
    if opts:
        st.markdown("**🧰 Backup work while you wait** — this counts as normal task time:")
        cols = st.columns(len(opts))
        for col, (lbl, form, name) in zip(cols, opts):
            with col:
                if st.button(lbl, key=f"nw_bk_{form}_{name or ''}", width='stretch'):
                    att_log("break_end", b_type)
                    st.session_state[FORM_KEYS.get(team, "")] = form
                    if name:
                        st.session_state["other_prefill"] = name
                    if form == "custdel":
                        st.session_state["cd_tab"] = "again"
                    st.rerun()
    if st.button("▶️ Back to work", type="primary", width='stretch', key="nw_end"):
        att_log("break_end", b_type)
        st.rerun()


def no_work_now():
    """everyone on '⏸️ No work' right now -> [dict]"""
    try:
        ev = fetch_all("attendance_log", lambda q: q.eq("date", date_str()))
    except Exception:
        return []
    by = {}
    for e in ev:
        by.setdefault(e.get("person"), []).append(e)
    users = {u["name"]: u for u in (load_users() or {}).values()}
    now = now_ist()
    out = []
    for p, es in by.items():
        es = sorted(es, key=lambda e: str(e.get("at")))
        s = att_state(es)
        if s["on_break"] and nw_parse(s["on_break"][1]) and not s["clock_out"]:
            reason, w0, t0 = nw_parse(s["on_break"][1])
            last = [e for e in es if e.get("event") == "break_start"][-1]
            team = (users.get(p) or {}).get("team") or last.get("team") or ""
            area = last.get("area") or ""
            n, txt = work_waiting(team, area)
            out.append({"person": p, "team": team, "area": area, "since": s["on_break"][0], "reason": reason,
                        "mins": int((now - s["on_break"][0]).total_seconds() // 60), "waiting": n, "waiting_txt": txt})
    return sorted(out, key=lambda r: -r["mins"])


def show_no_work_panel(kp="nwp"):
    """managers / admin: who has no work right now + 📌 give work"""
    rows = no_work_now()
    if not rows:
        return
    with st.container(border=True):
        red = sum(1 for r in rows if r["mins"] >= NW_RED_MINS)
        (st.error if red else st.warning)(f"⏸️ **{len(rows)} {'person has' if len(rows) == 1 else 'people have'} no work right now**"
                                          + (f" — 🔴 {red} for {NW_RED_MINS}+ min" if red else ""))
        st.dataframe(pd.DataFrame([{
            "": "🔴" if r["mins"] >= NW_RED_MINS else "", "Staff": r["person"],
            "Role · Area": f"{TEAM_ICON.get(r['team'], '')} {r['team']}" + (f" · {r['area']}" if r["area"] else ""),
            "Since": f"{r['since'].strftime('%I:%M %p')} ({fmt_age(r['mins'])})", "Reason": r["reason"],
            "Work waiting?": ("⚠️ " + " · ".join(r["waiting_txt"])) if r["waiting"] else "✅ none"} for r in rows]).astype(str),
            hide_index=True, width='stretch')
        msg = st.session_state.pop(f"{kp}_msg", None)
        if msg:
            st.success(msg)
        c1, c2, c3, c4 = st.columns([2, 3, 3, 1])
        by = {r["person"]: r for r in rows}
        with c1:
            who = st.selectbox("📌 Give work to", list(by), key=f"{kp}_who")
        team = by[who]["team"]
        picks = [lbl for lbl, _, _ in NW_BACKUP.get(team, [])] + ["✏️ Write my own"]
        with c2:
            what = st.selectbox("Work", picks, key=f"{kp}_what_{who}")
        with c3:
            txt = st.text_input("Details", key=f"{kp}_txt_{who}",
                                placeholder="Write the task" if what.startswith("✏️") else "e.g. rack A, top 2 shelves")
        with c4:
            st.write("")
            if st.button("📌 Assign", type="primary", key=f"{kp}_go", width='stretch'):
                title = txt.strip() if what.startswith("✏️") else what
                if not title:
                    st.error("Write the task.")
                    return
                try:
                    supabase.table("assigned_tasks").insert({
                        "title": title[:120], "details": ("" if what.startswith("✏️") else txt.strip()) or "Given during ⏸️ No work",
                        "assigned_to": who, "team": team, "due_date": date_str(), "priority": "Urgent",
                        "status": "Pending", "is_template": False, "active": True,
                        "assigned_by": st.session_state.name, "assigned_at": now_iso()}).execute()
                    st.session_state[f"{kp}_msg"] = f"📌 Work given to {who}: {title}"
                    st.rerun()
                except Exception as e:
                    st.error(f"Could not save — has assigned_tasks_setup.sql been run? ({e})")


def _nw_blocks(day_lo, day_hi):
    """every '⏸️ No work' stretch in a period -> [(person, area, start, end, reason, waiting)]"""
    ev = fetch_all("attendance_log", lambda q: q.gte("date", _ds(day_lo)).lte("date", _ds(day_hi)))
    by = {}
    for e in ev:
        by.setdefault((e.get("person"), str(e.get("date"))[:10]), []).append(e)
    now_n = _now_n()
    out = []
    for (p, d), es in by.items():
        cur = None
        for e in sorted(es, key=lambda e: str(e.get("at"))):
            t = _naive(to_ist(e.get("at")))
            if e.get("event") == "break_start":
                cur = (t, e) if nw_parse(e.get("break_type")) else None
            elif e.get("event") in ("break_end", "clock_out") and cur:
                r, w, _ = nw_parse(cur[1].get("break_type"))
                out.append((p, cur[1].get("area") or "", cur[0], t, r, w))
                cur = None
        if cur:
            r, w, _ = nw_parse(cur[1].get("break_type"))
            out.append((p, cur[1].get("area") or "", cur[0], now_n if d == _ds(now_n) else cur[0], r, w))
    return out


def _heat(v, top, fmt, marks=("🟨", "🟧", "🟥")):
    if not v:
        return ""
    k = 2 if v >= top * 0.66 else 1 if v >= top * 0.33 else 0
    return f"{marks[k]} {fmt(v)}"


def show_nowork_pattern(kp="nwpat"):
    st.markdown("#### ⏸️ No-work pattern — when the team waits, and when stock really arrives")
    lo, hi, _b = report_period(kp)
    rs = st.selectbox("Reason", ["All reasons"] + NW_REASONS[:-1], key=f"{kp}_reason")
    try:
        blocks = _nw_blocks(lo, hi)
        arr = fetch_all("bill_arrivals", lambda q: q.gte("date", _ds(lo)).lte("date", _ds(hi)))
    except Exception as e:
        st.error(f"Could not load: {e}")
        return
    if rs != "All reasons":
        blocks = [b for b in blocks if b[4] == rs]
    hours = list(range(7, 24))
    nw = {}
    for p, area, s, e, r, w in blocks:
        t = s
        while t < e:
            nxt = min(e, t.replace(minute=0, second=0, microsecond=0) + timedelta(hours=1))
            nw[(area or "No area", t.hour)] = nw.get((area or "No area", t.hour), 0) + (nxt - t).total_seconds()
            t = nxt
    st.markdown("**1. When the team waits** — total ⏸️ No-work time per hour"
                + (f" ({rs})" if rs != "All reasons" else ""))
    if nw:
        top = max(nw.values())
        areas = sorted({a for a, _ in nw})
        st.dataframe(pd.DataFrame([{"Area": a, **{f"{h % 12 or 12}{'am' if h < 12 else 'pm'}":
                                                   _heat(nw.get((a, h), 0), top, lambda v: _sr_hm(v)) for h in hours}}
                                   for a in areas]).astype(str), hide_index=True, width='stretch')
        tot = sum((b[3] - b[2]).total_seconds() for b in blocks)
        bad = sum((b[3] - b[2]).total_seconds() for b in blocks if b[5])
        st.caption(f"Total ⏸️ No work: {_sr_hm(tot)} in {len(blocks)} stretch(es)"
                   + (f" · ⚠️ {_sr_hm(bad)} of it while work was waiting" if bad else ""))
    else:
        st.info("No '⏸️ No work' recorded in this period yet — the pattern fills in as the team uses the button.")
    st.markdown("**2. When stock arrives** — bills per hour (📥 Bills arrived photos)")
    ah = {}
    for a in arr:
        t = _naive(to_ist(a.get("arrived_at")))
        if t:
            k = (a.get("area") or "—", t.hour)
            ah[k] = ah.get(k, 0) + int(a.get("bills") or 1)
    if ah:
        top = max(ah.values())
        st.dataframe(pd.DataFrame([{"Area": a, **{f"{h % 12 or 12}{'am' if h < 12 else 'pm'}":
                                                   _heat(ah.get((a, h), 0), top, str, ("▫️", "🟩", "🟩🟩")) for h in hours}}
                                   for a in sorted({a for a, _ in ah})]).astype(str), hide_index=True, width='stretch')
    else:
        st.info("No bill arrivals in this period.")
    st.markdown("**3. When each distributor's stock arrives**")
    try:
        arrs = fetch_all("arrangements", lambda q: q.gte("order_placed_date", _ds(lo)).lte("order_placed_date", _ds(hi)))
    except Exception:
        arrs = []
    placed = {}
    for a in arrs:
        t = parse_task_time(a.get("order_placed_time"))
        if t and a.get("distributor"):
            placed.setdefault(_bill_norm(a["distributor"]), []).append(t.hour * 60 + t.minute)
    by = {}
    for a in arr:
        t = _naive(to_ist(a.get("arrived_at")))
        if t and a.get("distributor"):
            by.setdefault(a["distributor"], []).extend([t.hour * 60 + t.minute] * int(a.get("bills") or 1))
    hm = lambda m: datetime(2000, 1, 1, int(m) // 60, int(m) % 60).strftime("%I:%M %p")
    rows = []
    for d, ms in by.items():
        ms = sorted(ms)
        med = ms[len(ms) // 2]
        pl = placed.get(_bill_norm(d))
        rows.append({"": "🟢" if med < 10 * 60 else "🟡" if med < 12 * 60 else "🔴", "Distributor": d, "Bills": len(ms),
                     "Usual arrival": hm(med), "Earliest": hm(ms[0]),
                     "Orders placed (avg)": hm(sum(pl) / len(pl)) if pl else "", "_m": med})
    if rows:
        rows.sort(key=lambda r: -r["_m"])
        st.dataframe(pd.DataFrame([{k: v for k, v in r.items() if k != "_m"} for r in rows]).astype(str),
                     hide_index=True, width='stretch')
        st.caption("Usual arrival = the middle arrival time of that distributor's bills. 🟢 before 10 AM · 🟡 before 12 PM · "
                   "🔴 12 PM or later — ask the 🔴 ones to deliver in the hours your team is waiting.")
    else:
        st.info("No distributor arrivals in this period.")


# ── 📣 DAILY STAFF REPORT — shared in the WhatsApp group (2 PM · 7 PM · 11:15 PM · next morning) ─────────
SR_DEFAULT = {"target": 85, "yellow": 70, "break_full": 60, "break_short": 30, "full_hours": 8,
              "posts": ["14:00", "19:00", "23:15", "09:00"],
              "speed": {"Register Entry": 5, "Bill Cross Check": 15, "Bill Upload (Software)": 10, "Stock Placement": 15,
                        "Arrangement Order": 10, "Purchase Order": 20, "Call Log": 5, "Pickup": 45}}
SR_POST_NAME = ["🌤️ 2 PM check", "🌇 7 PM check", "🌙 Final report", "☀️ Morning — yesterday"]


def sr_cfg():
    try:
        c = json.loads(get_app_setting("staff_report_cfg", "{}") or "{}")
    except Exception:
        c = {}
    out = dict(SR_DEFAULT, **{k: v for k, v in c.items() if k in SR_DEFAULT})
    out["speed"] = dict(SR_DEFAULT["speed"], **(c.get("speed") or {}))
    return out


def _sr_cover(tasks, events, day_s, now_n):
    """(clock-in, day end, [(start, end)] of tasks + breaks) for idle stretches"""
    s = att_state(sorted(events, key=lambda e: str(e.get("at"))))
    cin, cout = _naive(s["clock_in"]), _naive(s["clock_out"])
    is_today = day_s == _ds(now_n)
    cover, cur = [], None
    for e in sorted(events, key=lambda e: str(e.get("at"))):
        t, ev = _naive(to_ist(e.get("at"))), e.get("event")
        if ev == "break_start":
            cur = t
        elif ev in ("break_end", "clock_out") and cur:
            cover.append((cur, t))
            cur = None
    if cur:
        cover.append((cur, now_n if is_today else cur))
    for t in tasks:
        if t.get("status") == "In Progress" and is_today:
            st_ = _rep_dt(t.get("date"), t.get("start_time"))
            if st_:
                cover.append((st_, now_n))
        elif t.get("status") != "In Progress":
            a, b = _rep_span(t)
            if a:
                cover.append((a, b or a))
    end = cout or (now_n if is_today and cin else None)
    return cin, end, sorted(cover)


def longest_idle(tasks, events, day_s, now_n):
    """longest stretch between clock-in and clock-out with no task and no break -> (secs, start, end)"""
    cin, end, cover = _sr_cover(tasks, events, day_s, now_n)
    if not cin or not end or end <= cin:
        return 0, None, None
    best, cursor = (0, None, None), cin
    for a, b in cover + [(end, end)]:
        a = max(a, cin)
        if a > cursor:
            g = (min(a, end) - cursor).total_seconds()
            if g > best[0]:
                best = (g, cursor, min(a, end))
        if b > cursor:
            cursor = b
        if cursor >= end:
            break
    return best


def _sr_used(s):
    working = max(0, s["present"] - s["lunch"] - s["brk"] - s.get("nowork_ok", 0))
    return working, (100 * s["work"] / working if working > 0 else None)


@st.cache_data(ttl=120, show_spinner=False)
def staff_day_report(day_s, upto_s=None):
    """every staff member for one day (upto_s = 'HH:MM' for 'today so far') -> list of rows + absent list"""
    cfg = sr_cfg()
    day = datetime.strptime(day_s, "%Y-%m-%d")
    now_n = _now_n() if day_s == _ds(_now_n()) else day.replace(hour=23, minute=59)
    lo = _ds(day - timedelta(days=7))
    tasks, att, wal = _rep_load_people(lo, day_s)
    users = [u for u in (load_users() or {}).values()
             if u.get("role") not in ("admin", "manager") and u.get("active", True) is not False]
    xmap = extra_teams_map()
    uname = {u["name"]: k for k, u in (load_users() or {}).items()}
    by_pd, ev_pd, area_pd = {}, {}, {}
    for t in tasks:
        by_pd.setdefault((t.get("person"), str(t.get("date"))[:10]), []).append(t)
    for e in att:
        ev_pd.setdefault((e.get("person"), str(e.get("date"))[:10]), []).append(e)
    for w in wal:
        if w.get("area"):
            area_pd.setdefault((w.get("person"), str(w.get("date"))[:10]), []).append(w["area"])
    roster = load_roster(day_s)
    try:
        assigned = supabase.table("assigned_tasks").select("assigned_to,assigned_by,assigned_at")\
            .eq("due_date", day_s).eq("is_template", False).execute().data or []
    except Exception:
        assigned = []
    rows, absent = [], []
    for u in users:
        name, team = u["name"], u.get("team", "")
        teams = [team] + [x for x in xmap.get(uname.get(name, ""), []) if x != team]
        tl, el = by_pd.get((name, day_s), []), ev_pd.get((name, day_s), [])
        if not tl and not el:
            r = roster.get(name) or {}
            if r.get("status") in ("Off", "Leave"):
                absent.append((name, team, "🏖️ Off" if r["status"] == "Off" else "🤒 Leave"))
            elif day_s == _ds(_now_n()) and r.get("start_time") and parse_task_time(r["start_time"]) and \
                    parse_task_time(r["start_time"]).time() > _now_n().time():
                absent.append((name, team, f"🕒 starts {r['start_time']}"))
            else:
                absent.append((name, team, "❌ No clock-in"))
            continue
        s = person_day_stats(tl, el, day_s, now_n)
        if not s["cin"] and not s["tasks"]:
            absent.append((name, team, "⚠️ Logged in, not clocked in"))
            continue
        working, used = _sr_used(s)
        breaks = s["lunch"] + s["brk"]
        allow = (cfg["break_full"] if s["present"] >= cfg["full_hours"] * 3600 else cfg["break_short"]) * 60
        idle = longest_idle(tl, el, day_s, now_n)
        done = [t for t in tl if t.get("status") != "In Progress"]
        secs_by_team = {}
        for t in done:
            tm = t.get("team") if t.get("team") in teams else team
            secs_by_team[tm] = secs_by_team.get(tm, 0) + task_secs(t)
        role = max(secs_by_team, key=secs_by_team.get) if secs_by_team else team
        # speed: the slowest main task against its target
        slow = None
        for tt, tgt in cfg["speed"].items():
            xs = [task_secs(t) for t in done if t.get("task_type") == tt and task_secs(t) > 0]
            if xs and tgt:
                avg = sum(xs) / len(xs) / 60
                if avg > tgt * 1.25 and (not slow or avg / tgt > slow[1] / slow[2]):
                    slow = (tt, avg, tgt, len(xs))
        # trend: used % vs own last 7 days
        prev = []
        for i in range(1, 8):
            d_ = _ds(day - timedelta(days=i))
            ptl, pel = by_pd.get((name, d_), []), ev_pd.get((name, d_), [])
            if ptl or pel:
                ps = person_day_stats(ptl, pel, d_, now_n)
                pw, pu = _sr_used(ps)
                if pu is not None and pw >= 3600:
                    prev.append(pu)
        base = sum(prev) / len(prev) if prev else None
        trend = "" if used is None or base is None else "↑" if used >= base + 3 else "↓" if used <= base - 3 else "→"
        areas = area_pd.get((name, day_s), [])
        given = [a for a in assigned if a.get("assigned_to") == name and any(
            s_ <= (_naive(to_ist(a.get("assigned_at"))) or datetime.min) <= e_ + timedelta(minutes=5)
            for s_, e_, _, _ in s["nowork_list"])]
        nw_reasons = sorted({r_ for _, _, r_, _ in s["nowork_list"]})
        rows.append({"nowork": s["nowork"], "nowork_bad": s["nowork"] - s["nowork_ok"], "nowork_why": ", ".join(nw_reasons),
                     "given_by": ", ".join(sorted({a.get("assigned_by") or "" for a in given} - {""})),"name": name, "team": role, "teams": teams, "area": max(set(areas), key=areas.count) if areas else "",
                     "cin": s["cin"], "cout": s["cout"], "working": working, "task": s["work"], "breaks": breaks,
                     "over": max(0, breaks - allow), "allow": allow, "off": max(0, working - s["work"]), "used": used,
                     "tasks": s["tasks"], "idle": idle, "slow": slow, "trend": trend, "base": base})
    return rows, absent


def sr_ranked(rows):
    """copies of the rows with 🥇 / 🔻 inside each role — only among the people shown"""
    rows = [dict(r, rank="") for r in rows]
    for tm in set(r["team"] for r in rows):
        grp = sorted([r for r in rows if r["team"] == tm and r["used"] is not None and r["working"] >= 3600],
                     key=lambda r: -r["used"])
        for i, r in enumerate(grp):
            r["rank"] = "🥇" if i == 0 and len(grp) > 1 else "🔻" if i == len(grp) - 1 and len(grp) > 1 else ""
    return rows


def sr_hidden():
    try:
        return set(json.loads(get_app_setting("staff_report_hide", "[]") or "[]"))
    except Exception:
        return set()


def _sr_flag(used, cfg):
    if used is None:
        return "⚪"
    return "🟢" if used >= cfg["target"] else "🟡" if used >= cfg["yellow"] else "🔴"


def _sr_hm(secs):
    secs = int(secs or 0)
    h, m = secs // 3600, (secs % 3600) // 60
    return f"{h}h {m:02d}m" if h else f"{m}m"


def staff_report_text(day_s, rows, absent, final, title):
    cfg = sr_cfg()
    d = datetime.strptime(day_s, "%Y-%m-%d")
    lines = [f"📊 {title} — {d.strftime('%a %d %b')}", "━━━━━━━━━━━━━━━"]
    for tm in REP_TEAM_ORDER + sorted({r["team"] for r in rows} - set(REP_TEAM_ORDER)):
        grp = sorted([r for r in rows if r["team"] == tm], key=lambda r: -(r["used"] or -1))
        if not grp:
            continue
        lines.append(f"{TEAM_ICON.get(tm, '👤')} {tm.upper()}")
        for r in grp:
            bits = [f"{round(r['used'])}% {_sr_flag(r['used'], cfg)}" if r["used"] is not None else "—",
                    f"{_sr_hm(r['working'])} worked", f"{r['tasks']} tasks" + (f" {r['trend']}" if r["trend"] else "")]
            if r["idle"][0] >= 30 * 60:
                bits.append(f"💤 {_sr_hm(r['idle'][0])} idle ({r['idle'][1].strftime('%I:%M')}–{r['idle'][2].strftime('%I:%M %p')})")
            if r["over"] >= 5 * 60:
                bits.append(f"☕ breaks {_sr_hm(r['breaks'])} (+{_sr_hm(r['over'])})")
            if r["slow"]:
                bits.append(f"🐢 {r['slow'][0]} avg {round(r['slow'][1])}m (target {r['slow'][2]}m)")
            if r.get("nowork", 0) >= 5 * 60:
                bits.append(f"⏸️ No work {_sr_hm(r['nowork'])}" + (" 🟡" if r["nowork"] >= NW_LIMIT_MINS * 60 else "")
                            + (f" ({r['nowork_why']})" if r["nowork_why"] else "")
                            + (" ⚠️ work was waiting" if r["nowork_bad"] >= 60 else "")
                            + (f" → 📌 work given by {r['given_by']}" if r["given_by"] else ""))
            if r["tasks"] <= 2 and r["working"] >= 3 * 3600:
                bits.append(f"⚠️ only {r['tasks']} task(s) timed")
            mark = (r.get("rank") or "") if final else ""
            lines.append(f"{mark + ' ' if mark else ''}{r['name']}" + (f" · {r['area']}" if r["area"] else "")
                         + " — " + " · ".join(bits))
        lines.append("")
    tw = sum(r["working"] for r in rows)
    tt = sum(r["task"] for r in rows)
    if rows:
        lines.append("━━━━━━━━━━━━━━━")
    if tw:
        bases = [r["base"] for r in rows if r["base"] is not None]
        lines.append(f"Team: {_sr_hm(tw)} worked · {round(100 * tt / tw)}% on tasks (target {cfg['target']}%)"
                     + (f" · last 7 days {round(sum(bases) / len(bases))}%" if bases else ""))
    if final:
        good = [r for r in rows if r["used"] is not None and r["working"] >= 4 * 3600]
        if good:
            best = max(good, key=lambda r: r["used"])
            lines.append(f"🏆 Star of the day: {best['name']} ({round(best['used'])}%)")
    for lbl in ("❌ No clock-in", "⚠️ Logged in, not clocked in", "🤒 Leave", "🏖️ Off"):
        ns = [n for n, _, w in absent if w == lbl]
        if ns:
            lines.append(f"{lbl}: " + ", ".join(ns))
    later = [f"{n} ({w.split('starts ')[1]})" for n, _, w in absent if w.startswith("🕒")]
    if later:
        lines.append("🕒 Shift later: " + ", ".join(later))
    return "\n".join(lines).replace("\n\n━", "\n━")


def sr_due_slot(now=None):
    """the latest post time that has passed today and is not marked posted -> (index, 'HH:MM') or None"""
    now = now or now_ist()
    cfg = sr_cfg()
    try:
        done = json.loads(get_app_setting(f"staff_report_posted_{now.strftime('%Y-%m-%d')}", "[]") or "[]")
    except Exception:
        done = []
    passed = []
    for i, hm in enumerate(cfg["posts"]):
        try:
            h, m = [int(x) for x in hm.split(":")]
        except Exception:
            continue
        if (now.hour, now.minute) >= (h, m):
            passed.append(((h, m), i, hm))
    if not passed:
        return None
    _, i, hm = max(passed)                       # the most recent post time; posting it covers the earlier ones
    return None if i in done else (i, hm)


def sr_slots_upto(i):
    """slot i and every slot with an earlier time of day"""
    def hm(x):
        try:
            return tuple(int(v) for v in x.split(":"))
        except Exception:
            return (99, 0)
    posts = sr_cfg()["posts"]
    return [j for j, x in enumerate(posts) if hm(x) <= hm(posts[i])]


