def _fu_raw_between(lo_s, hi_s):
    orders = [t for t in fetch_all("daily_tasks", lambda q: q.eq("task_type", "Purchase Order").gte("date", lo_s).lte("date", hi_s))
              if (t.get("details") or {}).get("fu") and t.get("status") != "In Progress"]
    if not orders:
        return orders, [], [], []
    regs = fetch_all("daily_tasks", lambda q: q.eq("task_type", "Register Entry").gte("date", lo_s))
    ups = fetch_all("daily_tasks", lambda q: q.eq("task_type", "Bill Upload (Software)").gte("date", lo_s))
    try:
        photos = fetch_all("bill_arrivals", lambda q: q.gte("date", lo_s))
    except Exception:
        photos = []
    return orders, regs, ups, photos


def _rep_load_area(lo_s, hi_s):
    """everything the area report needs from lo_s - 3 days to hi_s"""
    pre = _ds(datetime.strptime(lo_s, "%Y-%m-%d") - timedelta(days=3))
    D = {"journeys": build_bill_journeys(pre, hi_s, hi_s)}
    try:
        D["arrivals"] = fetch_all("bill_arrivals", lambda q: q.gte("date", pre).lte("date", hi_s))
    except Exception:
        D["arrivals"] = []
    try:
        lo_iso = IST.localize(datetime.strptime(lo_s, "%Y-%m-%d")).isoformat()
        D["bounces"] = fetch_all("bounce_items", lambda q: q.gte("reported_at", lo_iso))
    except Exception:
        D["bounces"] = []
    try:
        D["lines"] = fetch_all("customer_order_lines", lambda q: q.gte("scheduled_date", lo_s).lte("scheduled_date", hi_s))
    except Exception:
        D["lines"] = []
    try:
        D["fu"] = _fu_raw_between(lo_s, hi_s)
    except Exception:
        D["fu"] = ([], [], [], [])
    try:
        D["att"] = fetch_all("attendance_log", lambda q: q.gte("date", lo_s).lte("date", hi_s))
    except Exception:
        D["att"] = []
    try:
        D["wal"] = fetch_all("work_area_log", lambda q: q.gte("date", lo_s).lte("date", hi_s))
    except Exception:
        D["wal"] = []
    return D


def _mean(xs):
    xs = [x for x in xs if x is not None]
    return sum(xs) / len(xs) if xs else None


def _area_ctx(D, now_n):
    """pre-computed pieces shared by every column (fu records, stock staff per day)"""
    fu = fu_records(D["fu"], now_n=now_n) if D["fu"][0] else []
    area_of = {}
    for w in sorted(D["wal"], key=lambda w: str(w.get("chosen_at") or "")):
        if w.get("area"):
            area_of[(w.get("person"), str(w.get("date"))[:10])] = w["area"]      # last choice of the day wins
    ev = {}
    for e in D["att"]:
        ev.setdefault((e.get("person"), str(e.get("date"))[:10]), []).append(e)
    last_end = {}      # latest task end per person-day (only used when someone forgot to clock out)
    for j in D["journeys"]:
        for t in [j["reg"]] + [s["task"] for s in j["stages"] if s.get("task")]:
            last_end.setdefault((t.get("person"), str(t.get("date"))[:10]), []).append(t.get("end_time") or t.get("time") or "")
    staff = {}        # date -> [(person, area, present secs)]
    today_s = _ds(now_n)
    for (p, d), a in area_of.items():
        evs = sorted(ev.get((p, d), []), key=lambda e: str(e.get("at")))
        if not any(e.get("event") == "clock_in" for e in evs):
            continue
        s = att_state(evs)
        cin, cout = _naive(s["clock_in"]), _naive(s["clock_out"])
        end = cout or (now_n if d == today_s else
                       (_rep_dt(d, max(last_end[(p, d)], key=time_sort_key)) if last_end.get((p, d)) else None))
        staff.setdefault(d, []).append((p, a, (end - cin).total_seconds() if cin and end and end > cin else 0))
    return {"fu": fu, "staff": staff}


def area_metrics(D, ctx, area, blo, bhi, now_n):
    """all metrics of one area (None = all areas) for dates blo..bhi -> {key: value}"""
    lo_s, hi_s = _ds(blo), _ds(bhi)
    inb = lambda s: s is not None and lo_s <= str(s)[:10] <= hi_s
    ina = lambda a: area in (None, "", "All Areas") or a == area
    end = min(datetime.combine(bhi + timedelta(days=1), datetime.min.time()), now_n)
    jb = ctx.setdefault("_j_by_area", {})
    if area not in jb:                                   # split the bills by area once, reused by every column
        jb[area] = [j for j in D["journeys"] if ina(j["d"].get("area"))]
    from8 = _ds(blo - timedelta(days=8))                # bills entered up to 8 days before the column still count
    J = [j for j in jb[area] if from8 <= str(j["reg"].get("date"))[:10] <= hi_s]
    M = {}
    # incoming
    M["arrived"] = sum(int(_to_float(a.get("bills"), 0)) for a in D["arrivals"] if inb(a.get("date")) and ina(a.get("area")))
    reg_b = [j for j in J if inb(j["reg"].get("date"))]
    M["entered"] = len(reg_b)
    M["entered_arr"] = sum(1 for j in reg_b if str(j["d"].get("arrangement_no") or "").strip())
    M["sku"] = sum(int(_to_float(j["d"].get("no_items"), 0)) for j in reg_b)
    M["amount"] = sum(_to_float(j["d"].get("bill_amount"), 0) for j in reg_b)
    # work done in the period (each bill's step counted on the day it was done)
    done = {0: [], 1: [], 2: []}
    for j in J:
        for i, s in enumerate(j["stages"]):
            if s.get("task") and inb(s["task"].get("date")):
                done[i].append(s["task"])
    M["checked"], M["uploaded"], M["placed"] = len(done[0]), len(done[1]), len(done[2])
    M["t_check"], M["t_upload"], M["t_place"] = (sum(task_secs(t) for t in done[i]) for i in (0, 1, 2))
    M["avg_check"] = M["t_check"] / M["checked"] if M["checked"] else None
    M["avg_upload"] = M["t_upload"] / M["uploaded"] if M["uploaded"] else None
    M["avg_place"] = M["t_place"] / M["placed"] if M["placed"] else None
    issues = 0
    for t in done[0]:
        dd = t.get("details") or {}
        issues += sum(int(_to_float(dd.get(f), 0)) for f, _ in ISSUE_FIELDS)
    M["issues"] = issues
    # pending at the end of the period (bills entered in the 7 days before)
    recent = [j for j in J if j["entered"] and end - timedelta(days=7) <= j["entered"] <= end]
    late = lambda x: x is None or x > end
    M["pend_check"] = sum(1 for j in recent if late(j["checked"]))
    M["pend_upload"] = sum(1 for j in recent if late(j["uploaded"]))
    M["pend_place"] = sum(1 for j in recent if j.get("need_pl") and late(j["placed"]))
    entered_by_arr = {}
    for j in J:
        aid = str(j["d"].get("arrival_id") or "")
        if aid and j["entered"] and j["entered"] <= end:
            entered_by_arr[aid] = entered_by_arr.get(aid, 0) + 1
    pe = 0
    for a in D["arrivals"]:
        t = _naive(to_ist(a.get("arrived_at")))
        if ina(a.get("area")) and t and end - timedelta(days=2) <= t <= end:
            pe += max(0, int(_to_float(a.get("bills"), 0)) - entered_by_arr.get(str(a.get("id")), 0))
    M["pend_entry"] = pe
    # staff
    days = (bhi - blo).days + 1
    rows = [r for d, rs in ctx["staff"].items() if lo_s <= d <= hi_s for r in rs if ina(r[1])]
    M["staff"] = round(len(rows) / days, 1) if rows else 0
    M["staff_hours"] = sum(r[2] for r in rows)
    M["per_hr"] = round(M["uploaded"] / (M["staff_hours"] / 3600), 2) if M["staff_hours"] >= 600 else None
    # waiting — bills that ARRIVED in the period, followed until done (even on a later day)
    arr_b = [j for j in J if j["arrived"] and lo_s <= _ds(j["arrived"]) <= hi_s]
    waits = {"w_entry": [], "w_check": [], "w_upload": [], "w_place": []}
    w2 = 0
    for j in arr_b:
        mine = []
        if j["entry_delay"] is not None and j["entry_delay"] >= 0:
            mine.append(("w_entry", j["entry_delay"]))
        prev = j["entered"] or j["arrived"]           # each step's wait starts when the step before it ended
        for k, s in zip(("w_check", "w_upload", "w_place"), j["stages"]):
            if not s.get("task"):
                break
            if s.get("start") and prev and s["start"] >= prev and (k != "w_place" or j.get("need_pl")):
                mine.append((k, (s["start"] - prev).total_seconds() / 60))
            prev = s.get("end") or prev
        for k, v in mine:
            waits[k].append(v)
        still = j.get("next") and _stage_wait_mins(j, end) >= 120
        w2 += 1 if (any(v >= 120 for _, v in mine) or still) else 0
    for k, v in waits.items():
        M[k] = _mean(v)
    M["to_soft"] = _mean([(j["uploaded"] - j["arrived"]).total_seconds() / 60 for j in arr_b
                          if j["uploaded"] and j["uploaded"] >= j["arrived"]])
    M["wait2h"] = w2
    cand = {k: M[k] for k in AREA_STAGE_LABEL if M.get(k) is not None}
    if cand:
        k = max(cand, key=cand.get)
        M["bottleneck"] = f"{AREA_STAGE_LABEL[k]} — {fmt_age(int(cand[k]))} avg wait" if cand[k] >= 1 else "—"
    else:
        M["bottleneck"] = "—"
    # quality
    M["bounces"] = sum(1 for b in D["bounces"] if inb(_ds(_naive(to_ist(b.get("reported_at")))) if b.get("reported_at") else None)
                       and ina(b.get("area")))
    # customer orders
    cl = [l for l in D["lines"] if inb(l.get("scheduled_date")) and ina(l.get("area")) and not l.get("removed")
          and l.get("status") not in ("Removed", "Closed")]
    due_now = [l for l in cl if str(l.get("scheduled_date")) <= _ds(now_n)]
    ok = 0
    for l in due_now:
        due = None
        try:
            due = datetime.strptime(f"{l.get('scheduled_date')} {(l.get('delivery_time') or '11:59 PM').strip()}", "%Y-%m-%d %I:%M %p")
        except Exception:
            due = datetime.strptime(str(l.get("scheduled_date"))[:10], "%Y-%m-%d").replace(hour=23, minute=59)
        ra = _naive(line_ready_at(l))
        if line_ready(l) and ra and ra <= due:
            ok += 1
    M["cust_total"] = len(cl)
    M["cust_ontime"] = round(100 * ok / len(due_now)) if due_now else None
    fu = [r for r in ctx["fu"] if inb(_ds(r["at"])) and ina(r["area"]) and r["stage"] != "closed"]
    for key, urg in (("fu_vu", "Very Urgent"), ("fu_reg", "Regular")):
        den = [r for r in fu if r["urg"] == urg and (r["stage"] == "imported" or now_n > r["deadline"])]
        M[key] = round(100 * sum(1 for r in den if r["stage"] == "imported" and r["flag"] == "✅") / len(den)) if den else None
    M["fu_late"] = sum(1 for r in fu if r["stage"] in ("ordered", "arrived") and r["flag"] == "🔴")
    return M


def area_baseline(D, ctx, area, lo, now_n):
    """daily average of every flagged metric over the REP_BASE_DAYS days before lo"""
    vals, working = {}, 0
    for i in range(1, REP_BASE_DAYS + 1):
        d = lo - timedelta(days=i)
        m = area_metrics(D, ctx, area, d, d, now_n)
        if not (m["arrived"] or m["entered"] or m["checked"] or m["uploaded"]):
            continue                                   # no bill work that day (holiday / no data) -> not in the average
        working += 1
        for k, _, _, better in AREA_METRICS:
            if better and m.get(k) is not None:
                vals.setdefault(k, []).append(m[k])
    if working < REP_BASE_MIN_DAYS:
        return {}                                      # too little history -> no 🔴 / 🟢 yet
    return {k: _mean(v) for k, v in vals.items()}


def _area_fmt(kind, v):
    if v is None:
        return "—"
    if kind == "n":
        return f"{int(v):,}"
    if kind == "inr":
        return _rep_inr(v)
    if kind == "t":
        return fmt_secs(v) if v else "0"
    if kind == "m":
        return fmt_age(int(round(v)))
    if kind == "pct":
        return f"{int(v)}%"
    if kind == "x":
        return f"{v:g}"
    return str(v)


def _area_flag(better, v, base):
    if not better or v is None or base is None or base == 0:
        return ""
    if better == "low":
        return "🔴 " if v > base * (1 + REP_FLAG) else ("🟢 " if v < base * (1 - REP_FLAG) else "")
    return "🔴 " if v < base * (1 - REP_FLAG) else ("🟢 " if v > base * (1 + REP_FLAG) else "")


@st.cache_data(ttl=600, max_entries=24, show_spinner=False)
def area_report(view, area, lo_s, hi_s, buckets, areas):
    """-> [(column label, metrics, baseline)] — only these small results are kept in memory"""
    now_n = _now_n()
    lo, hi = datetime.strptime(lo_s, "%Y-%m-%d").date(), datetime.strptime(hi_s, "%Y-%m-%d").date()
    D = _rep_load_area(_ds(lo - timedelta(days=REP_BASE_DAYS)), hi_s)
    ctx = _area_ctx(D, now_n)
    pick = lambda s_: datetime.strptime(s_, "%Y-%m-%d").date()
    if view == "One area":
        base = area_baseline(D, ctx, area, lo, now_n)
        cols = [(lbl, area_metrics(D, ctx, area, pick(a), pick(b), now_n), base) for lbl, a, b in buckets]
        if len(buckets) > 1:
            cols.append(("Total / Avg", area_metrics(D, ctx, area, lo, hi, now_n), base))
        return cols
    return [(a, area_metrics(D, ctx, a, lo, hi, now_n), area_baseline(D, ctx, a, lo, now_n)) for a in list(areas) + ["All Areas"]]


def area_table(cols, base):
    """cols: [(column label, metrics dict, baseline dict or None)] -> DataFrame"""
    rows = []
    for k, label, kind, better in AREA_METRICS:
        r = {"": label}
        for name, m, b in cols:
            r[name] = "" if kind == "sec" else _area_flag(better, m.get(k), (b or {}).get(k)) + _area_fmt(kind, m.get(k))
        rows.append(r)
    return pd.DataFrame(rows)


def show_area_summary(kp="ra"):
    st.markdown("#### 📍 Area summary — where we are lagging")
    lo, hi, buckets = report_period(kp)
    areas = load_areas()
    c1, c2, c3 = st.columns([2, 2, 1])
    with c1:
        view = st.radio("View", ["One area", "Compare areas"], horizontal=True, key=f"{kp}_view")
    with c2:
        area = st.selectbox("Area", areas + ["All Areas"], key=f"{kp}_area") if view == "One area" else None
    with c3:
        st.write("")
        if st.button("🔄 Refresh", key=f"{kp}_ref"):
            area_report.clear()
            st.rerun()
    try:
        msg = "Adding up the numbers…" + (" (weekly / monthly can take up to a minute the first time)" if len(buckets) > 10
                                          or (hi - lo).days > 20 else "")
        with st.spinner(msg):
            cols = area_report(view, area, _ds(lo), _ds(hi), tuple((l, _ds(a), _ds(b)) for l, a, b in buckets),
                               tuple(areas))
        no_hist = view == "One area" and not cols[0][2]
        title = (f"📍 {area} · " if view == "One area" else "📍 All areas compared · ") + \
            f"{lo.strftime('%d %b')} – {hi.strftime('%d %b %Y')}"
    except Exception as e:
        st.error(f"Could not build the area summary: {e}")
        return
    st.markdown(f"**{title}**")
    df = area_table(cols, None)
    st.dataframe(df, hide_index=True, width='stretch', height=min(38 * (len(df) + 1), 1500))
    st.caption(f"🔴 / 🟢 = more than {int(REP_FLAG * 100)}% worse / better than that area's own daily average of the "
               f"{REP_BASE_DAYS} days before this period. Work done = steps done on that day. Waiting = bills that "
               "arrived on that day, followed until done (even the next day). Pending = bills of the last 7 days not "
               "done at the end of the day.")
    if view == "One area" and no_hist:
        st.caption(f"ℹ️ 🔴 / 🟢 start once this area has {REP_BASE_MIN_DAYS} working days in the 4 weeks before the period.")
    if view == "One area":
        last = cols[-1][1]
        if last.get("bottleneck") not in (None, "—"):
            st.info(f"🚧 Biggest delay in this period: {last['bottleneck']}")
    buf = io.BytesIO()
    with pd.ExcelWriter(buf, engine="openpyxl") as w:
        pd.DataFrame([{"": title}]).to_excel(w, index=False, header=False, sheet_name="Area Summary")
        df.to_excel(w, index=False, sheet_name="Area Summary", startrow=2)
        try:
            ws = w.sheets["Area Summary"]
            ws.column_dimensions["A"].width = 52
            for c in ws.iter_cols(min_col=2, max_col=ws.max_column):
                ws.column_dimensions[c[0].column_letter].width = 22
        except Exception:
            pass
    st.download_button("⬇️ Download Excel", buf.getvalue(),
                       f"area-summary-{(area or 'all').replace(' ', '-')}-{_ds(lo)}-to-{_ds(hi)}.xlsx",
                       "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", key=f"{kp}_xl")


# ── 🚚 ARRANGEMENT SUMMARY — how long each step of a customer's arrangement order takes ─────────────────
ARR_STEPS = [   # key, label, owner, default target (minutes; None = no target)
    ("s1", "1️⃣ Customer order → order to distributor", "Purchase", 30),
    ("s2", "2️⃣ Order placed → picked up (self pick / porter)", "Distributor + pilot / porter", 120),
    ("s3", "3️⃣ Picked up → reached warehouse", "Pilot / porter", 60),
    ("s23", "2️⃣+3️⃣ Distributor delivers: order placed → reached warehouse", "Distributor", 180),
    ("s4", "4️⃣ Reached warehouse → bill uploaded", "Stock", 60),
    ("s5", "5️⃣ Order ready → customer call marked", "Call", 30),
    ("s6", "⏳ Pilot waiting at the distributor", "Distributor", 20),
    ("tot", "🏁 Total: customer order → call marked", "Everyone", None),
]
ARR_SPLITS = {"Distributor": "dist", "Area": "area", "Pickup type": "ptype", "Pilot": "pilot"}


def arr_targets():
    t = {k: d for k, _, _, d in ARR_STEPS}
    try:
        t.update({k: int(v) for k, v in json.loads(get_app_setting("arr_targets", "{}") or "{}").items() if k in t})
    except Exception:
        pass
    return t


def _arr_dt(v):
    return _naive(to_ist(v)) if v else None


def _mins_between(a, b):
    return (b - a).total_seconds() / 60 if a and b and b >= a else None


def arr_measure(lo_s, hi_s, now_n=None):
    """every step time of the arrangements placed lo_s..hi_s -> (records, promise records)
    record: {step, mins, dist, area, ptype, pilot, ref, date}"""
    now_n = now_n or _now_n()
    hi3 = _ds(datetime.strptime(hi_s, "%Y-%m-%d") + timedelta(days=3))
    arrs = fetch_all("arrangements", lambda q: q.gte("order_placed_date", lo_s).lte("order_placed_date", hi_s))
    if not arrs:
        return [], []
    by_no = {str(a.get("arrangement_no")): a for a in arrs}
    als = []
    for part in _chunks(list(by_no), 80):
        als += fetch_all("arrangement_lines", lambda q, p=part: q.in_("arrangement_no", p))
    orders = sorted({str(a.get("order_no")) for a in als if a.get("order_no")})
    lines = []
    for part in _chunks(orders, 80):
        lines += fetch_all("customer_order_lines", lambda q, p=part: q.in_("order_no", p))
    line_by_id = {l["id"]: l for l in lines}
    pick = {}
    for t in fetch_all("daily_tasks", lambda q: q.eq("task_type", "Pickup").gte("date", lo_s).lte("date", hi3)):
        n = str((t.get("details") or {}).get("arrangement_no") or "")
        if n and t.get("status") != "In Progress":
            pick.setdefault(n, []).append(t)
    porter = {}
    try:
        for b in fetch_all("porter_bookings", lambda q: q.gte("date", lo_s).lte("date", hi3)):
            t = _any_time(b.get("handover_time"))
            if not t:
                continue
            at = datetime.combine(datetime.strptime(str(b.get("date"))[:10], "%Y-%m-%d").date(), t)
            for n in re.split(r"[,\s]+", str(b.get("arrangement_nos") or "")):
                n = n.strip().lstrip("#")
                if n and (n not in porter or at < porter[n]):
                    porter[n] = at
    except Exception:
        pass
    jour = {}
    for j in build_bill_journeys(lo_s, hi3, hi3):
        n = str(j["d"].get("arrangement_no") or "").strip().lstrip("#")
        if n and (n not in jour or (j["arrived"] and jour[n]["arrived"] and j["arrived"] < jour[n]["arrived"])):
            jour[n] = j
    recs, attr = [], {}
    for n, a in by_no.items():
        ptype = a.get("pickup_type") or "Self Pick"
        pilot = a.get("pickup_by") if ptype == "Self Pick" else ("Porter" if ptype == "Porter" else "Distributor")
        at = {"dist": a.get("distributor") or "—", "area": a.get("area") or "—", "ptype": ptype,
              "pilot": pilot or "—", "ref": f"#{n}", "date": str(a.get("order_placed_date"))[:10]}
        attr[n] = at
        placed = _arr_dt(a.get("created_at"))
        if ptype == "Self Pick":
            picked = _arr_dt(a.get("picked_up_at"))
            if not picked and pick.get(n):
                picked = _rep_span(sorted(pick[n], key=lambda t: t.get("id") or 0)[-1])[1]
        elif ptype == "Porter":
            picked = porter.get(n)
        else:
            picked = None
        j = jour.get(n)
        reached = j["arrived"] if j else None
        uploaded = j["uploaded"] if j else None
        if ptype == "Distributor Delivers":
            steps = [("s23", _mins_between(placed, reached))]
        else:
            steps = [("s2", _mins_between(placed, picked)), ("s3", _mins_between(picked, reached))]
        steps.append(("s4", _mins_between(reached, uploaded)))
        for t in pick.get(n, []):
            s_, e_ = _rep_span(t)
            steps.append(("s6", _mins_between(s_, e_)))
        recs += [dict(at, step=k, mins=m) for k, m in steps if m is not None]
    for al in als:
        l = line_by_id.get(al.get("line_id"))
        m = _mins_between(_arr_dt((l or {}).get("order_time")), _arr_dt(al.get("ordered_at")))
        if m is not None:
            recs.append(dict(attr.get(str(al.get("arrangement_no")), {}), step="s1", mins=m))
    # per customer order: ready -> call, total, called before the promised time
    arr_of = {}
    for al in als:
        arr_of.setdefault(str(al.get("order_no")), set()).add(str(al.get("arrangement_no")))
    by_order = {}
    for l in lines:
        if not l.get("removed") and l.get("status") not in ("Removed", "Closed"):
            by_order.setdefault(str(l.get("order_no")), []).append(l)
    promise = []
    for o, ls in by_order.items():
        ats = [attr[x] for x in arr_of.get(o, ()) if x in attr]
        if not ats:
            continue
        one = lambda k: ats[0][k] if len({x[k] for x in ats}) == 1 else "Several"
        g = {"dist": one("dist"), "area": ls[0].get("area") or "—", "ptype": one("ptype"), "pilot": one("pilot"),
             "ref": f"Order {o}", "date": min(x["date"] for x in ats)}
        ready = None
        if all(line_ready(l) for l in ls):
            rs = [_naive(line_ready_at(l)) for l in ls]
            ready = max(r for r in rs if r) if any(rs) else None
        calls = [_arr_dt(l.get("delivery_at")) for l in ls if l.get("delivery_status")]
        call = min(c for c in calls if c) if any(calls) else None
        ot = min((_arr_dt(l.get("order_time")) for l in ls if l.get("order_time")), default=None)
        for k, m in (("s5", _mins_between(ready, call)), ("tot", _mins_between(ot, call))):
            if m is not None:
                recs.append(dict(g, step=k, mins=m))
        if call:
            sd = _any_date(ls[0].get("scheduled_date"))
            tm = _any_time(ls[0].get("delivery_time")) if ls[0].get("delivery_time") else None
            if sd:
                due = datetime.combine(sd, tm) if tm else datetime.combine(sd, datetime.max.time())
                promise.append(dict(g, on_time=call <= due))
    return recs, promise


@st.cache_data(ttl=600, max_entries=24, show_spinner=False)
def arr_report(lo_s, hi_s):
    return arr_measure(lo_s, hi_s)


def _arr_stats(vals, target):
    if not vals:
        return None
    v = sorted(vals)
    n = len(v)
    med = v[n // 2] if n % 2 else (v[n // 2 - 1] + v[n // 2]) / 2
    return {"n": n, "avg": sum(v) / n, "med": med,
            "within": round(100 * sum(1 for x in v if x <= target) / n) if target else None}


def _fm(m):
    return fmt_age(int(round(m))) if m is not None else "—"


def arr_summary_df(recs, targets):
    rows = []
    for k, label, owner, _ in ARR_STEPS:
        s = _arr_stats([r["mins"] for r in recs if r["step"] == k], targets.get(k))
        tgt = targets.get(k)
        rows.append({"Step": label, "Owner": owner, "Count": s["n"] if s else 0,
                     "Average": ("🔴 " if s and tgt and s["avg"] > tgt else "") + (_fm(s["avg"]) if s else "—"),
                     "Typical (median)": _fm(s["med"]) if s else "—",
                     "Within target": f"{s['within']}%" if s and s["within"] is not None else "—",
                     "Target": _fm(tgt) if tgt else "—"})
    return pd.DataFrame(rows).astype(str)


def arr_split_df(recs, by, targets):
    groups = sorted({r.get(by, "—") for r in recs})
    rows = []
    for g in groups:
        mine = [r for r in recs if r.get(by, "—") == g]
        row = {by_label(by): g, "Arrangements": len({r["ref"] for r in mine if r["ref"].startswith("#")})}
        for k, label, _, _ in ARR_STEPS:
            s = _arr_stats([r["mins"] for r in mine if r["step"] == k], targets.get(k))
            tgt = targets.get(k)
            row[label.split(" ", 1)[0] + " " + label.split(" ", 1)[1][:28]] = \
                (("🔴 " if tgt and s["avg"] > tgt else "") + f"{_fm(s['avg'])} ({s['n']})") if s else "—"
        rows.append(row)
    rows.sort(key=lambda r: -r["Arrangements"])
    return pd.DataFrame(rows).astype(str)


def by_label(by):
    return {v: k for k, v in ARR_SPLITS.items()}.get(by, by)


def show_arrangement_summary(kp="rar"):
    st.markdown("#### 🚚 Arrangement summary — how long each step takes")
    lo, hi, _ = report_period(kp)
    c1, c2, c3 = st.columns([2, 2, 1])
    with c1:
        area = st.selectbox("Area", ["All Areas"] + load_areas(), key=f"{kp}_area")
    with c2:
        split = st.selectbox("Split by", list(ARR_SPLITS), key=f"{kp}_split")
    with c3:
        st.write("")
        if st.button("🔄 Refresh", key=f"{kp}_ref"):
            arr_report.clear()
            st.rerun()
    try:
        with st.spinner("Adding up the arrangement times…"):
            recs, promise = arr_report(_ds(lo), _ds(hi))
    except Exception as e:
        st.error(f"Could not build the arrangement summary: {e}")
        return
    if area != "All Areas":
        recs = [r for r in recs if r.get("area") == area]
        promise = [p for p in promise if p.get("area") == area]
    st.caption(f"Arrangement orders placed {lo.strftime('%d %b')} – {hi.strftime('%d %b %Y')}"
               + (f" · {area}" if area != "All Areas" else "") + ". Each step is measured from the end of the one before.")
    if not recs:
        st.info("No arrangement orders with times in this period.")
        return
    targets = arr_targets()
    if promise:
        ok = sum(1 for p in promise if p["on_time"])
        st.metric(f"📞 Customers called before the promised delivery time ({ok} of {len(promise)} orders)",
                  f"{round(100 * ok / len(promise))}%")
    summ = arr_summary_df(recs, targets)
    st.dataframe(summ, hide_index=True, width='stretch')
    no_time = not any(r["step"] in ("s1", "tot") for r in recs)
    st.caption("🔴 = average slower than the target. Typical (median) = the middle value — one overnight bill can't "
               "push it up. Step 5 starts when every medicine of the order is ready (received / picked / not available)."
               + (" ⚠️ Steps 1 and Total need the customer's order time — import it with the order Excel "
                  "(📥 Customer Orders → 🕐 guide)." if no_time else ""))
    by = ARR_SPLITS[split]
    st.markdown(f"**By {split.lower()}** — average (count)")
    sp = arr_split_df(recs, by, targets)
    st.dataframe(sp, hide_index=True, width='stretch')
    with st.expander("🐢 Slowest 10 for each step"):
        rows = []
        for k, label, _, _ in ARR_STEPS:
            for r in sorted([r for r in recs if r["step"] == k], key=lambda r: -r["mins"])[:10]:
                rows.append({"Step": label, "Took": _fm(r["mins"]), "Arrangement / order": r["ref"],
                             "Distributor": r.get("dist"), "Area": r.get("area"), "Pilot": r.get("pilot"),
                             "Date": r.get("date")})
        st.dataframe(pd.DataFrame(rows).astype(str), hide_index=True, width='stretch')
    if st.session_state.get("role") == "admin":
        with st.expander("🎯 Targets (minutes)"):
            new = {}
            cols = st.columns(4)
            for i, (k, label, _, d) in enumerate([s for s in ARR_STEPS if s[3] is not None]):
                with cols[i % 4]:
                    new[k] = int(st.number_input(label, 1, 2000, int(targets.get(k) or d), key=f"{kp}_t_{k}"))
            if st.button("💾 Save targets", key=f"{kp}_tsave"):
                set_app_setting("arr_targets", json.dumps(new))
                st.success("✅ Targets saved")
                st.rerun()
    buf = io.BytesIO()
    with pd.ExcelWriter(buf, engine="openpyxl") as w:
        summ.to_excel(w, index=False, sheet_name="Steps")
        sp.to_excel(w, index=False, sheet_name=f"By {split}"[:30])
    st.download_button("⬇️ Download Excel", buf.getvalue(), f"arrangement-times-{_ds(lo)}-to-{_ds(hi)}.xlsx",
                       "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", key=f"{kp}_xl")


# ── 🛵 DELIVERY SUMMARY — every delivery pilot side by side ──────────────────────────────────────────────
DEL_TARGETS = {"ontime": 90, "wait": 20, "to_wh": 60, "overnight": 0, "extra_km": 15, "own_pilot": 8}
DEL_TARGET_LABEL = {"ontime": "On-time pickups at least (%)", "wait": "Waiting at distributor at most (min)",
                    "to_wh": "Pickup → warehouse at most (min)", "overnight": "Bills kept overnight at most",
                    "extra_km": "Extra KM over expected at most (%)",
                    "own_pilot": "Pickups a day for an own pilot"}


def del_targets():
    t = dict(DEL_TARGETS)
    try:
        t.update({k: float(v) for k, v in json.loads(get_app_setting("del_targets", "{}") or "{}").items() if k in t})
    except Exception:
        pass
    return t


def delivery_pilots():
    users, xmap = load_users() or {}, extra_teams_map()
    return sorted({u["name"] for k, u in users.items()
                   if u.get("team") == "Delivery" or "Delivery" in xmap.get(k, [])})


def _num(v):
    try:
        return float(v) if str(v).strip() not in ("", "None", "nan") else None
    except Exception:
        return None


def delivery_measure(lo_s, hi_s, now_n=None):
    """-> [pilot dict] for lo_s..hi_s (numbers, flags and every pickup)"""
    now_n = now_n or _now_n()
    lo, hi = datetime.strptime(lo_s, "%Y-%m-%d").date(), datetime.strptime(hi_s, "%Y-%m-%d").date()
    T = del_targets()
    tasks = fetch_all("daily_tasks", lambda q: q.in_("task_type", ["Pickup", "Delivery Trip"]).gte("date", lo_s).lte("date", hi_s))
    tasks = [t for t in tasks if t.get("status") != "In Progress"]
    names = set(delivery_pilots()) | {t.get("person") for t in tasks if t.get("task_type") == "Pickup" and t.get("person")}
    if not names:
        return []
    staff = _staff_cached(lo_s, hi_s, tuple(sorted((x, "Delivery") for x in names)))      # shared with the Staff tab
    try:
        to_wh = {}
        for r in arr_report(lo_s, hi_s)[0]:                                               # shared with the Arrangement tab
            if r["step"] == "s3":
                to_wh.setdefault(r.get("pilot"), []).append(r["mins"])
    except Exception:
        to_wh = {}
    try:
        hos = fetch_all("pilot_handovers", lambda q: q.gte("date", lo_s).lte("date", hi_s))
    except Exception:
        hos = []
    try:
        logs = fetch_all("km_log", lambda q: q.gte("date", lo_s).lte("date", hi_s))
    except Exception:
        logs = []
    routes, sett = load_routes() or {}, km_settings()
    by_pd = {}
    for t in tasks:
        by_pd.setdefault((t.get("person"), str(t.get("date"))[:10]), []).append(t)
    out = []
    for n in sorted(names):
        S = staff.get(n) or {}
        pk = sorted([t for t in tasks if t.get("person") == n and t.get("task_type") == "Pickup"],
                    key=lambda t: (str(t.get("date")), time_sort_key(t.get("start_time"))))
        rows, waits, delays, yes, no, short, skus = [], [], [], 0, 0, 0, 0
        for t in pk:
            d = t.get("details") or {}
            s_, e_ = _rep_span(t)
            w = _mins_between(s_, e_)
            if w is not None:
                waits.append(w)
            ot, dl = d.get("on_time"), _num(d.get("delay_mins"))
            if ot == "Yes":
                yes += 1
            elif ot == "No":
                no += 1
                if dl is not None:
                    delays.append(dl)
            o_, r_ = _num(d.get("no_sku_ordered")), _num(d.get("no_sku_received"))
            skus += int(r_ or 0)
            is_short = o_ is not None and r_ is not None and o_ > 0 and r_ < o_
            short += 1 if is_short else 0
            rows.append({"Date": _rep_day0(str(t.get("date"))[:10]).strftime("%d %b"), "ARR #": d.get("arrangement_no", ""),
                         "Distributor": d.get("distributor", ""), "Target": d.get("target_pickup", "") or "—",
                         "Reached": d.get("time_reached") or (s_.strftime("%I:%M %p") if s_ else ""),
                         "Handed over": d.get("time_handover") or (e_.strftime("%I:%M %p") if e_ else ""),
                         "Waited": _fm(w),
                         "Result": "✅ on time" if ot == "Yes" else (f"🔴 late {_fm(dl)}" if ot == "No" else "— no target"),
                         "SKUs ordered → received": (f"{int(o_ or 0)} → {int(r_ or 0)}" + (" ⚠️ short" if is_short else ""))
                         if o_ is not None or r_ is not None else ""})
        mine_h = [h for h in hos if n in (h.get("from_person"), h.get("to_person"))]
        overnight = len({str(h.get("arrangement_no")) for h in mine_h if h.get("kind") == "overnight" and h.get("to_person") == n})
        given = sum(1 for h in mine_h if h.get("kind") != "overnight" and h.get("from_person") == n and h.get("to_person") != n)
        taken = sum(1 for h in mine_h if h.get("kind") != "overnight" and h.get("to_person") == n and h.get("from_person") != n)
        km, km_cmp, exp_cmp = 0.0, 0.0, 0.0
        for l in logs:
            if l.get("person") != n:
                continue
            meter = _num(l.get("km"))
            if meter is None and _num(l.get("end_km")) is not None and _num(l.get("start_km")) is not None:
                meter = _num(l["end_km"]) - _num(l["start_km"])
            if meter is None:
                continue
            km += meter
            seq = day_places(by_pd.get((n, str(l.get("date"))[:10]), []))
            exp, missing = expected_km(seq, routes, (sett.get(n) or {}).get("home_km"))
            if seq and not missing and exp > 0:
                km_cmp += meter
                exp_cmp += exp
        days = S.get("days") or len({str(t.get("date")) for t in pk})
        P = {"name": n, "days": days, "present": S.get("present", 0), "rest": S.get("rest", 0),
             "pickups": len(pk), "per_day": round(len(pk) / days, 1) if days else None,
             "trips": sum(1 for t in tasks if t.get("person") == n and t.get("task_type") == "Delivery Trip"),
             "skus": skus, "ontime": round(100 * yes / (yes + no)) if yes + no else None,
             "late_by": _mean(delays), "wait": _mean(waits), "to_wh": _mean(to_wh.get(n, [])),
             "short": short, "overnight": overnight, "given": given, "taken": taken,
             "km": round(km, 1) if km else None, "km_per": round(km / len(pk), 1) if km and pk else None,
             "extra_km": round(100 * (km_cmp - exp_cmp) / exp_cmp) if exp_cmp else None, "rows": rows}
        P["flags"] = [k for k, bad in (("ontime", P["ontime"] is not None and P["ontime"] < T["ontime"]),
                                       ("wait", P["wait"] is not None and P["wait"] > T["wait"]),
                                       ("to_wh", P["to_wh"] is not None and P["to_wh"] > T["to_wh"]),
                                       ("overnight", P["overnight"] > T["overnight"]),
                                       ("extra_km", P["extra_km"] is not None and P["extra_km"] > T["extra_km"])) if bad]
        if P["pickups"] or P["days"] or P["trips"] or P["km"]:
            out.append(P)
    out.sort(key=lambda P: (-len(P["flags"]), P["name"].lower()))
    return out


@st.cache_data(ttl=600, max_entries=24, show_spinner=False)
def delivery_report(lo_s, hi_s):
    return delivery_measure(lo_s, hi_s)


def delivery_table(data):
    red = lambda P, k, txt: ("🔴 " if k in P["flags"] else "") + txt
    rows = []
    for P in data:
        rows.append({
            "Pilot": P["name"], "🚩": len(P["flags"]) or "", "Days": P["days"], "Hours": _rep_t(P["present"]),
            "Rest": _rep_t(P["rest"]), "Pickups": P["pickups"], "Per day": P["per_day"] if P["per_day"] is not None else "—",
            "Trips": P["trips"], "SKUs": P["skus"],
            "On time": red(P, "ontime", f"{P['ontime']}%" if P["ontime"] is not None else "—"),
            "Late by (avg)": _fm(P["late_by"]), "Waiting at distributor": red(P, "wait", _fm(P["wait"])),
            "Pickup → warehouse": red(P, "to_wh", _fm(P["to_wh"])), "Short pickups": P["short"],
            "Bills overnight": red(P, "overnight", str(P["overnight"])),
            "Handovers given / taken": f"{P['given']} / {P['taken']}",
            "KM": P["km"] if P["km"] is not None else "—", "KM / pickup": P["km_per"] if P["km_per"] is not None else "—",
            "KM vs expected": red(P, "extra_km", (f"{P['extra_km']:+d}%" if P["extra_km"] is not None else "—"))})
    return pd.DataFrame(rows).astype(str)


def show_delivery_summary(kp="rdl"):
    st.markdown("#### 🛵 Delivery summary — every pilot side by side")
    lo, hi, _ = report_period(kp)
    c1, c2 = st.columns([4, 1])
    with c2:
        if st.button("🔄 Refresh", key=f"{kp}_ref"):
            delivery_report.clear()
            overlap_report.clear()
            st.rerun()
    try:
        with st.spinner("Adding up the pickups…"):
            data = delivery_report(_ds(lo), _ds(hi))
    except Exception as e:
        st.error(f"Could not build the delivery summary: {e}")
        return
    if not data:
        st.info("No delivery pilots or pickups in this period.")
        return
    T = del_targets()
    st.dataframe(delivery_table(data), hide_index=True, width='stretch')
    st.caption(f"🔴 = outside the target: on time below {T['ontime']:g}% · waiting over {T['wait']:g} min · pickup → "
               f"warehouse over {T['to_wh']:g} min · bills kept overnight · KM more than {T['extra_km']:g}% above expected. "
               "Pilots with the most 🔴 are on top. Waiting = 'reached distributor' → 'medicines handed over'. "
               "KM vs expected uses only days where every route has a distance (🛵 Delivery KM → Routes).")
    for P in data:
        if not P["rows"]:
            continue
        with st.expander(f"{'🔴 ' * len(P['flags'])}{P['name']} — {P['pickups']} pickup(s)", expanded=False):
            st.dataframe(pd.DataFrame(P["rows"]).astype(str), hide_index=True, width='stretch')
    st.divider()
    show_overlap_cost(kp, lo, hi)
    st.divider()
    if st.session_state.get("role") == "admin":
        with st.expander("🎯 Targets"):
            new = {}
            cols = st.columns(len(DEL_TARGETS))
            for col, k in zip(cols, DEL_TARGETS):
                with col:
                    new[k] = st.number_input(DEL_TARGET_LABEL[k], 0, 1000, int(T[k]), key=f"{kp}_t_{k}")
            if st.button("💾 Save targets", key=f"{kp}_tsave"):
                set_app_setting("del_targets", json.dumps(new))
                delivery_report.clear()
                overlap_report.clear()
                st.success("✅ Targets saved")
                st.rerun()
    buf = io.BytesIO()
    with pd.ExcelWriter(buf, engine="openpyxl") as w:
        delivery_table(data).to_excel(w, index=False, sheet_name="Summary")
        used = {"Summary"}
        for P in data:
            if not P["rows"]:
                continue
            nm = re.sub(r"[\[\]\*\?/\\:]", "", P["name"])[:28] or "Pilot"
            while nm in used:
                nm = nm[:25] + "_"
            used.add(nm)
            pd.DataFrame(P["rows"]).to_excel(w, index=False, sheet_name=nm)
    st.download_button("⬇️ Download Excel (summary + one sheet per pilot)", buf.getvalue(),
                       f"delivery-summary-{_ds(lo)}-to-{_ds(hi)}.xlsx",
                       "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", key=f"{kp}_xl")


# ── 🔁 OVERLAP & COST (inside the 🛵 Delivery tab) ─────────────────────────────────────────────────────
OVERLAP_MINS = 60            # two pilots at the same distributor within this many minutes = one visit too many
PILOT_WORK_DAYS = 26         # monthly salary ÷ this = cost of one working day


def pilot_salaries():
    try:
        v = json.loads(get_app_setting("pilot_salary", "{}") or "{}")
        return {k: float(x) for k, x in v.items() if x not in (None, "")}
    except Exception:
        return {}


def overlap_measure(lo_s, hi_s, pilots_data, own_pilot_min=8):
    """-> {"wh": per-warehouse pickups, "dist": distributor overlap, "cost": cost per pickup, "porter": porter cost}"""
    arrs = fetch_all("arrangements", lambda q: q.gte("order_placed_date", lo_s).lte("order_placed_date", hi_s))
    work_days = len({str(a.get("order_placed_date"))[:10] for a in arrs}) or 1
    wh = {}
    for a in arrs:
        w = wh.setdefault(a.get("area") or "—", {"Self Pick": 0, "Porter": 0, "Distributor Delivers": 0})
        pt = a.get("pickup_type") or "Self Pick"
        w[pt] = w.get(pt, 0) + 1
    wh_rows = []
    for area, w in sorted(wh.items(), key=lambda kv: -(kv[1]["Self Pick"] + kv[1]["Porter"])):
        per_day = round((w["Self Pick"] + w["Porter"]) / work_days, 1)
        wh_rows.append({"Warehouse / area": area, "Self pick": w["Self Pick"], "Porter": w["Porter"],
                        "Distributor delivers": w["Distributor Delivers"], "Pickups per working day": per_day,
                        "Suggestion": "✅ enough for its own pilot" if per_day >= own_pilot_min
                        else "🛵 Porter or share a nearby pilot"})
    # distributor visited by 2+ pilots within the same hour
    pk = [t for t in fetch_all("daily_tasks", lambda q: q.eq("task_type", "Pickup").gte("date", lo_s).lte("date", hi_s))
          if t.get("status") != "In Progress" and (t.get("details") or {}).get("distributor")]
    by = {}
    for t in pk:
        s_, e_ = _rep_span(t)
        if s_:
            by.setdefault((_norm_col(t["details"]["distributor"]), str(t.get("date"))[:10]), []).append((s_, e_, t))
    dist = {}
    for (dk, day), visits in by.items():
        visits.sort(key=lambda v: v[0])
        name = visits[0][2]["details"]["distributor"]
        D = dist.setdefault(dk, {"Distributor": name, "Visits": 0, "Days": set(), "Extra visits": 0, "Pilots": set(),
                                 "Waiting lost (min)": 0.0, "Example": ""})
        D["Visits"] += len(visits)
        D["Days"].add(day)
        i = 0
        while i < len(visits):                          # a group = visits starting within OVERLAP_MINS of the first one
            grp = [visits[i]]
            j = i + 1
            while j < len(visits) and (visits[j][0] - visits[i][0]).total_seconds() <= OVERLAP_MINS * 60:
                grp.append(visits[j])
                j += 1
            people = {g[2].get("person") for g in grp}
            if len(people) > 1:
                extra = grp[1:]
                D["Extra visits"] += len(extra)
                D["Pilots"] |= people
                D["Waiting lost (min)"] += sum(_mins_between(g[0], g[1]) or 0 for g in extra)
                if not D["Example"]:
                    D["Example"] = f"{_rep_day0(day).strftime('%d %b')}: " + ", ".join(
                        f"{g[2].get('person')} {g[0].strftime('%I:%M %p')}" for g in grp)
            i = j
    dist_rows = [dict(D, Days=len(D["Days"]), Pilots=", ".join(sorted(p for p in D["Pilots"] if p)),
                      **{"Waiting lost (min)": round(D["Waiting lost (min)"])}) for D in dist.values()]
    dist_rows.sort(key=lambda r: (-r["Extra visits"], -r["Visits"]))
    # cost per pickup: salary share for the days present + fuel (KM × ₹/km from Delivery KM settings)
    sal, sett = pilot_salaries(), km_settings()
    default_rate = float((sett.get("*") or {}).get("rate_per_km") or 0)
    cost_rows = []
    for P in pilots_data:
        rate = (sett.get(P["name"]) or {}).get("rate_per_km")
        rate = float(rate) if rate is not None else default_rate
        days = P["days"] or 0
        s_share = sal.get(P["name"], 0) / PILOT_WORK_DAYS * days
        fuel = (P["km"] or 0) * rate
        total = s_share + fuel
        cost_rows.append({"Pilot": P["name"], "Days present": days, "Pickups": P["pickups"],
                          "Salary share ₹": round(s_share), "Fuel / KM ₹": round(fuel), "Total ₹": round(total),
                          "Cost per pickup ₹": round(total / P["pickups"]) if P["pickups"] and total else None,
                          "_no_salary": P["name"] not in sal})
    # porter: what we actually paid (💰 Porter Payment)
    try:
        bks = fetch_all("porter_bookings", lambda q: q.gte("date", lo_s).lte("date", hi_s))
    except Exception:
        bks = []
    paid = [b for b in bks if _num(b.get("porter_cost"))]
    n_arr = sum(len([x for x in re.split(r"[,\s]+", str(b.get("arrangement_nos") or "")) if x.strip()]) or 1 for b in paid)
    spent = sum(_num(b.get("porter_cost")) for b in paid)
    porter = {"trips": len(paid), "arrangements": n_arr if paid else 0, "spent": round(spent),
              "per_trip": round(spent / len(paid)) if paid else None,
              "per_arr": round(spent / n_arr) if paid else None, "unpaid": len(bks) - len(paid)}
    return {"wh": wh_rows, "work_days": work_days, "dist": dist_rows, "cost": cost_rows, "porter": porter}


@st.cache_data(ttl=600, max_entries=24, show_spinner=False)
def overlap_report(lo_s, hi_s, own_pilot_min):
    return overlap_measure(lo_s, hi_s, delivery_report(lo_s, hi_s), own_pilot_min)


def show_overlap_cost(kp, lo, hi):
    st.markdown("### 🔁 Overlap & cost — when does a warehouse need its own pilot?")
    T = del_targets()
    try:
        with st.spinner("Checking overlaps and costs…"):
            R = overlap_report(_ds(lo), _ds(hi), float(T.get("own_pilot", 8)))
    except Exception as e:
        st.error(f"Could not build overlap & cost: {e}")
        return
    st.markdown(f"**📦 Pickups per warehouse** — {R['work_days']} working day(s)")
    if R["wh"]:
        st.dataframe(pd.DataFrame(R["wh"]).astype(str), hide_index=True, width='stretch')
        st.caption(f"Pickups per working day = (self pick + porter) ÷ days with arrangement orders. "
                   f"{T.get('own_pilot', 8):g}+ a day = enough work for a dedicated pilot.")
    else:
        st.caption("No arrangement orders in this period.")
    st.markdown(f"**🔁 Distributors visited by 2+ pilots within {OVERLAP_MINS} min**")
    over = [r for r in R["dist"] if r["Extra visits"]]
    if over:
        tot = sum(r["Extra visits"] for r in over)
        lost = sum(r["Waiting lost (min)"] for r in over)
        st.warning(f"🔁 {tot} extra visit(s) in this period — one pilot could have collected for both · "
                   f"about {fmt_age(lost)} of waiting at distributors could be saved.")
        st.dataframe(pd.DataFrame(over).astype(str), hide_index=True, width='stretch')
        st.caption("Fix: the pilot who goes first collects for the other warehouse too and hands over the bills "
                   "(🤝 Hand over to another pilot), or move that distributor to fixed pickup rounds.")
    else:
        st.success(f"✅ No distributor was visited by two pilots within {OVERLAP_MINS} min.")
    with st.expander(f"All distributors — visits ({len(R['dist'])})"):
        st.dataframe(pd.DataFrame(R["dist"]).astype(str), hide_index=True, width='stretch')
    st.markdown("**💰 Cost per pickup — pilot vs Porter**")
    cost = [r for r in R["cost"] if r["Pickups"] or r["Days present"]]
    if cost:
        st.dataframe(pd.DataFrame([{k: ("—" if v is None else v) for k, v in r.items() if not k.startswith("_")}
                                   for r in cost]).astype(str), hide_index=True, width='stretch')
        miss = [r["Pilot"] for r in cost if r["_no_salary"]]
        if miss:
            st.caption("⚠️ No salary entered for: " + ", ".join(miss) + " — admin: enter it below.")
    P = R["porter"]
    if P["trips"]:
        st.info(f"🛵 **Porter:** ₹{P['spent']:,} paid for {P['trips']} trip(s) carrying {P['arrangements']} arrangement(s) "
                f"→ **₹{P['per_trip']:,} per trip · ₹{P['per_arr']:,} per arrangement**"
                + (f" · {P['unpaid']} booking(s) not paid yet" if P["unpaid"] else ""))
    else:
        st.caption("🛵 Porter: no paid porter trips in this period (💰 Porter Payment).")
    st.caption(f"Pilot cost = monthly salary ÷ {PILOT_WORK_DAYS} × days present + KM × ₹/km (🛵 Delivery KM settings). "
               "Pilots also do delivery trips, so cost per pickup is a little high for them.")
    if st.session_state.get("role") == "admin":
        with st.expander("💰 Pilot monthly salaries (for cost per pickup)"):
            sal = pilot_salaries()
            names = [r["Pilot"] for r in R["cost"]]
            new = {}
            cols = st.columns(min(4, max(1, len(names))))
            for i, n in enumerate(names):
                with cols[i % len(cols)]:
                    new[n] = st.number_input(f"{n} ₹/month", 0, 500000, int(sal.get(n, 0)), step=500, key=f"{kp}_sal_{n}")
            if st.button("💾 Save salaries", key=f"{kp}_sal_save"):
                keep = {k: v for k, v in sal.items() if k not in new}
                set_app_setting("pilot_salary", json.dumps({**keep, **{k: v for k, v in new.items() if v}}))
                overlap_report.clear()
                st.success("✅ Salaries saved")
                st.rerun()


def show_reports(kp="rep"):
    st.subheader("📋 Staff & Area Summary")
    tab = st.radio("Report", ["👤 Staff", "📍 Area", "🚚 Arrangement", "🛵 Delivery", "⏸️ No-work pattern"], horizontal=True,
                   key=f"{kp}_tab", label_visibility="collapsed")
    if tab == "⏸️ No-work pattern":
        show_nowork_pattern(f"{kp}_nw")
        return
    if tab == "👤 Staff":
        show_staff_summary(f"{kp}_s")
    elif tab == "📍 Area":
        show_area_summary(f"{kp}_a")
    elif tab == "🚚 Arrangement":
        show_arrangement_summary(f"{kp}_r")
    else:
        show_delivery_summary(f"{kp}_d")



def show_admin_page():
    st.title("👑 RapidSurge Warehouse — Admin")
    st.caption(f"Welcome **{st.session_state.name}** | {today_ist().strftime('%A, %d %B %Y')} | {time_str()}")
    try:
        _cl = cleanup_old_photos()          # once a day: remove photos that are saved in a ZIP and older than N days
        if _cl:
            st.toast(_cl)
    except Exception:
        pass
    pending_reviews_banner()
    show_report_due_banner()
    show_no_work_panel("adm_nwp")
    st.divider()

    _nav = section_nav("adm", ['🎯 My Day', '📅 Daily Summary', '🔎 Reviews', '📊 Dashboard', '👥 All Staff Work', '🔄 Pipeline', '📈 Performance', '📝 Submit Entry', '👥 Settings', '📥 Reports', '🧭 Live Tracker', '📣 Staff Report', '📦 Customer Orders', '📍 Order Journey', '🛒 Normal Orders', '🧾 Bills Register', '🕐 Attendance', '📌 Assign Tasks', '📅 Shift Planner', '🛵 Delivery KM', '🏆 League', '📦 Photos', '🚚 Order Follow-up', '📋 Staff & Area Summary'])

    if _nav == '📅 Daily Summary':
        show_daily_summary("adm_ds")

    if _nav == '🔎 Reviews':
        show_reviews("adm_rv")

    if _nav == '📦 Photos':
        show_photo_archive("adm_ph")

    if _nav == '🏆 League':
        show_league("adm_lg")

    if _nav == '🛵 Delivery KM':
        show_delivery_km("adm_dkm")

    if _nav == '🚚 Order Follow-up':
        show_order_followup("adm_fu")

    if _nav == '📋 Staff & Area Summary':
        show_reports("adm_rep")

    if _nav == '🎯 My Day':
        show_my_day("md")

    if _nav == '📅 Shift Planner':
        show_shift_planner("adm_shift")

    if _nav == '🛒 Normal Orders':
        show_order_sheet_report("adm_osr")

    if _nav == '👥 All Staff Work':
        show_all_staff_work("adm_asw")

    if _nav == '📌 Assign Tasks':
        show_assign_tasks_admin("adm_asg")

    if _nav == '🕐 Attendance':
        show_attendance_admin("adm_att")

    if _nav == '📦 Customer Orders':
        show_close_old_lines("adm_col")
        show_customer_order_tracker("adm", show_phone=True)
        show_delivery_proof_check("adm_pc")

    if _nav == '📍 Order Journey':
        show_order_journey("adm_oj")
    if _nav == '🧭 Live Tracker':
        show_live_tracker("adm_lt")
    if _nav == '📣 Staff Report':
        show_staff_report("adm_sr")

    if _nav == '🧾 Bills Register':
        show_bills_register("adm_bills")

    if _nav == '📊 Dashboard':
        try:
            tasks_resp = supabase.table("daily_tasks").select("*").eq("date", date_str()).execute()
            df = pd.DataFrame(tasks_resp.data) if tasks_resp.data else pd.DataFrame()
        except Exception:
            df = pd.DataFrame()

        try:
            arr_resp = supabase.table("arrangements").select("*").eq("order_placed_date", date_str()).execute()
            arr_today = arr_resp.data if arr_resp.data else []
        except Exception:
            arr_today = []

        # ── ALERTS & BOTTLENECKS ──────────────────────────────────────────────
        from datetime import datetime as dt
        alerts = []

        for arr in arr_today:
            status = arr.get("status","")
            order_time = arr.get("order_placed_time","")
            if status not in ["Completed","Bill Uploaded","Stock Placed"] and order_time:
                try:
                    order_dt  = dt.strptime(order_time, "%I:%M %p")
                    now_dt    = dt.strptime(time_str(), "%I:%M %p")
                    diff_mins = int((now_dt - order_dt).total_seconds() / 60)
                    if diff_mins > 120:
                        hours = diff_mins // 60
                        mins  = diff_mins % 60
                        alerts.append(f"⚠️ **#{arr.get('arrangement_no')}** — {arr.get('distributor','')} stuck at **{status}** for **{hours}h {mins}m**!")
                except Exception:
                    pass

        pending_self = [a for a in arr_today if a.get("status")=="Pending" and a.get("pickup_type")=="Self Pick"]
        if len(pending_self) > 3:
            alerts.append(f"⚠️ **{len(pending_self)} arrangements** pending Self Pick!")

        reached = [a for a in arr_today if a.get("status")=="Reached Warehouse"]
        if len(reached) > 2:
            alerts.append(f"⚠️ **{len(reached)} arrangements** at warehouse — not cross checked!")

        try:
            all_users = supabase.table("app_users").select("*").eq("active",True).neq("role","admin").execute()
            if all_users.data and not df.empty:
                active_persons = df["person"].unique().tolist() if "person" in df.columns else []
                for u in all_users.data:
                    if u["name"] not in active_persons:
                        alerts.append(f"⚠️ **{u['name']}** ({u['team']}) — No activity today!")
        except Exception:
            pass

        # Show as expander
        with st.expander(f"🚨 Alerts & Bottlenecks ({len(alerts)} alerts)", expanded=len(alerts)>0):
            if alerts:
                for alert in alerts:
                    st.warning(alert)
            else:
                st.success("✅ All good! No alerts.")

        st.divider()

        # ── REAL TIME TEAM STATUS ─────────────────────────────────────────────
        try:
            all_users_resp = supabase.table("app_users").select("*").eq("active",True).neq("role","admin").execute()
            all_users_data = all_users_resp.data if all_users_resp.data else []

            latest_tasks = {}
            if not df.empty:
                for _, row in df.iterrows():
                    person = row.get("person","")
                    if person not in latest_tasks:
                        latest_tasks[person] = row
                    else:
                        try:
                            existing = dt.strptime(str(latest_tasks[person].get("time","12:00 AM")), "%I:%M %p")
                            new_t    = dt.strptime(str(row.get("time","12:00 AM")), "%I:%M %p")
                            if new_t > existing:
                                latest_tasks[person] = row
                        except Exception:
                            pass

            # Team filter
            selected_team = st.selectbox("👥 View Team Status",
                ["All Teams","Purchase","Stock","Call","Delivery"],
                key="team_status_filter")

            teams_to_show = ["Purchase","Stock","Call","Delivery"] if selected_team == "All Teams" else [selected_team]

            with st.expander("👥 Real Time Team Status", expanded=True):
                for team in teams_to_show:
                    team_users = [u for u in all_users_data if u.get("team") == team]
                    if team_users:
                        st.markdown(f"**{team} Team:**")
                        for u in team_users:
                            name = u["name"]
                            c1,c2,c3 = st.columns([2,3,2])
                            with c1: st.markdown(f"👤 **{name}**")
                            if name in latest_tasks:
                                task = latest_tasks[name]
                                if task.get("status") == "In Progress":
                                    with c2: st.markdown(f"🔄 **{task.get('task_type','')}**")
                                else:
                                    with c2: st.markdown(f"✅ **{task.get('task_type','')}**")
                                with c3: st.markdown(f"🕐 {task.get('time','')}")
                            else:
                                with c2: st.markdown("⏳ No activity yet")
                                with c3: st.markdown("")
                        st.divider()
        except Exception as e:
            st.error(f"Error: {e}")

        st.divider()

        # ── ARRANGEMENT SUMMARY ───────────────────────────────────────────────
        st.subheader("📋 Today's Arrangement Summary")
        a1,a2,a3,a4,a5 = st.columns(5)
        with a1: st.metric("Total", len(arr_today))
        with a2: st.metric("🔴 Pending", len([a for a in arr_today if a.get("status")=="Pending"]))
        with a3: st.metric("🚚 In Transit", len([a for a in arr_today if "Transit" in str(a.get("status",""))]))
        with a4: st.metric("🏭 At Warehouse", len([a for a in arr_today if a.get("status")=="Reached Warehouse"]))
        with a5: st.metric("✅ Completed", len([a for a in arr_today if a.get("status")=="Completed"]))

        st.divider()

        # ── PIPELINE HEALTH ───────────────────────────────────────────────────
        st.subheader("📈 Arrangement Pipeline Health")
        try:
            pipeline_times = []
            for arr in arr_today:
                try:
                    o = dt.strptime(arr.get("order_placed_time",""), "%I:%M %p")
                    u = dt.strptime(arr.get("bill_upload_time",""), "%I:%M %p")
                    diff = int((u-o).total_seconds()/60)
                    if diff > 0:
                        pipeline_times.append(diff)
                except Exception:
                    pass
            if pipeline_times:
                avg_t = int(sum(pipeline_times)/len(pipeline_times))
                min_t = min(pipeline_times)
                max_t = max(pipeline_times)
                c1,c2,c3 = st.columns(3)
                with c1: st.metric("⏱️ Avg Order→Bill Upload", f"{avg_t} mins")
                with c2: st.metric("⚡ Fastest", f"{min_t} mins")
                with c3:
                    icon = "🔴" if max_t > 180 else "🟡" if max_t > 120 else "🟢"
                    st.metric(f"{icon} Slowest", f"{max_t} mins")
            else:
                st.info("No completed pipeline data yet today!")
        except Exception as e:
            st.error(f"Error: {e}")

        st.divider()

        # Team tasks
        st.subheader("👥 Team Tasks Today")
        if not df.empty:
            cols = st.columns(4)
            for i,t in enumerate(["Purchase","Stock","Call","Delivery"]):
                with cols[i]: st.metric(t, len(df[df["team"]==t]), "tasks")
            st.divider()
            c1,c2 = st.columns(2)
            with c1: st.bar_chart(df["team"].value_counts())
            with c2: st.bar_chart(df["person"].value_counts())
        else:
            st.info("No tasks today yet!")

        st.divider()

        # All arrangements
        st.subheader("📋 All Arrangements Today")
        try:
            arr = supabase.table("arrangements").select("*")\
                .eq("order_placed_date", date_str()).execute()
            if arr.data:
                arr_df = pd.DataFrame(arr.data)
                display_cols = ["arrangement_no","distributor","area","order_placed_time","order_by","urgency","pickup_type","status"]
                existing_cols = [c for c in display_cols if c in arr_df.columns]
                st.dataframe(arr_df[existing_cols], width='stretch')
            else:
                st.info("No arrangements today.")
        except Exception as e:
            st.error(f"Error: {e}")

    if _nav == '🔄 Pipeline':
        st.subheader("🔄 Pipeline View")
        pickup_board_today()

        pipe_type = st.radio("Select Pipeline",
            ["📦 Arrangement Orders", "🧾 Normal Orders"],
            horizontal=True, key="pipe_type_tab")

        if pipe_type == "🧾 Normal Orders":
            st.subheader("🧾 Normal Order Pipeline")

            c1,c2,c3,c4 = st.columns(4)
            with c1:
                no_date = st.date_input("Date", value=today_ist(), key="no_date")
            with c2:
                try:
                    areas_resp = supabase.table("areas").select("name").eq("active",True).execute()
                    no_area_list = ["All Areas"] + [a["name"] for a in (areas_resp.data or [])]
                except Exception:
                    no_area_list = ["All Areas"]
                no_area = st.selectbox("Area", no_area_list, key="no_area")
            with c3:
                no_dist = st.text_input("Search Distributor", placeholder="Type to search...", key="no_dist")
            with c4:
                no_bill = st.text_input("Search Bill No", placeholder="Type bill no...", key="no_bill")

            no_date_str = no_date.strftime("%Y-%m-%d")

            try:
                reg_resp = supabase.table("daily_tasks").select("*")\
                    .eq("task_type", "Register Entry")\
                    .eq("date", no_date_str).execute()
                register_entries = reg_resp.data or []

                cross_resp = supabase.table("daily_tasks").select("*")\
                    .eq("task_type", "Bill Cross Check")\
                    .eq("date", no_date_str).execute()
                cross_checks = {t.get("details",{}).get("bill_no",""):t for t in (cross_resp.data or []) if not t.get("details",{}).get("arrangement_no","")}

                upload_resp = supabase.table("daily_tasks").select("*")\
                    .eq("task_type", "Bill Upload")\
                    .eq("date", no_date_str).execute()
                uploads = {t.get("details",{}).get("bill_no",""):t for t in (upload_resp.data or []) if not t.get("details",{}).get("arrangement_no","")}

                place_resp = supabase.table("daily_tasks").select("*")\
                    .eq("task_type", "Stock Placement")\
                    .eq("date", no_date_str).execute()
                placements = {t.get("details",{}).get("bill_no",""):t for t in (place_resp.data or []) if not t.get("details",{}).get("arrangement_no","")}

                pcheck_resp = supabase.table("daily_tasks").select("*")\
                    .eq("task_type", "Placement Cross Check")\
                    .eq("date", no_date_str).execute()
                place_checks = {t.get("details",{}).get("bill_no",""):t for t in (pcheck_resp.data or [])}

            except Exception as e:
                st.error(f"Error: {e}")
                register_entries = []
                cross_checks = {}
                uploads = {}
                placements = {}
                place_checks = {}

            if not register_entries:
                st.info("No normal orders found for selected date!")
            else:
                if no_dist:
                    register_entries = [r for r in register_entries if no_dist.lower() in r.get("details",{}).get("distributor","").lower()]
                if no_bill:
                    register_entries = [r for r in register_entries if no_bill.lower() in r.get("details",{}).get("bill_no","").lower()]

                pipeline_rows = []
                for r in register_entries:
                    d       = r.get("details",{})
                    bill_no = d.get("bill_no","")
                    dist    = d.get("distributor","")
                    items   = d.get("no_items","")
                    amount  = d.get("bill_amount","")
                    delby   = d.get("delivery_by","")

                    cross  = cross_checks.get(bill_no)
                    upload = uploads.get(bill_no)
                    place  = placements.get(bill_no)
                    pcheck = place_checks.get(bill_no)

                    if pcheck:
                        status = "✅ Completed"
                    elif place:
                        status = "🔍 Cross Check Pending"
                    elif upload:
                        status = "📍 Placement Pending"
                    elif cross:
                        status = "📤 Upload Pending"
                    else:
                        status = "✔️ Cross Check Pending"

                    pipeline_rows.append({
                        "Bill No": bill_no,
                        "Distributor": dist,
                        "Date": r.get("date",""),
                        "SKUs": items,
                        "Amount(₹)": f"₹{float(amount or 0):,.0f}",
                        "Arrived": r.get("time",""),
                        "Received By": r.get("person",""),
                        "Delivered By": delby,
                        "Check Time": f"{cross.get('duration_mins','-')} mins" if cross else "⏳",
                        "Checked By": cross.get("person","") if cross else "⏳",
                        "Upload Time": f"{upload.get('duration_mins','-')} mins" if upload else "⏳",
                        "Uploaded By": upload.get("person","") if upload else "⏳",
                        "Place Time": f"{place.get('duration_mins','-')} mins" if place else "⏳",
                        "Placed By": place.get("person","") if place else "⏳",
                        "Cross Check": "✅ " + pcheck.get("person","") if pcheck else "⏳",
                        "Status": status
                    })

                if pipeline_rows:
                    pipeline_df = pd.DataFrame(pipeline_rows)
                    st.markdown(f"**{len(pipeline_df)} bills found**")

                    status_filter = st.selectbox("Filter by Status", [
                        "All","✔️ Cross Check Pending","📤 Upload Pending",
                        "📍 Placement Pending","🔍 Cross Check Pending","✅ Completed"
                    ], key="no_status")

                    if status_filter != "All":
                        pipeline_df = pipeline_df[pipeline_df["Status"]==status_filter]

                    st.dataframe(pipeline_df, width='stretch')

                    # Detailed expander view
                    st.markdown("**📋 Detailed View:**")
                    for r in pipeline_rows:
                        with st.expander(f"Bill: {r['Bill No']} | {r['Distributor']} | {r['Status']}"):
                            c1,c2 = st.columns(2)
                            with c1:
                                st.markdown("**📒 Register Entry:**")
                                st.markdown(f"- Arrived: **{r['Arrived']}**")
                                st.markdown(f"- Received By: **{r['Received By']}**")
                                st.markdown(f"- Delivered By: **{r['Delivered By']}**")
                                st.markdown(f"- SKUs: **{r['SKUs']}**")
                                st.markdown(f"- Amount: **{r['Amount(₹)']}**")
                                st.divider()
                                st.markdown("**✔️ Bill Cross Check:**")
                                st.markdown(f"- Checked By: **{r['Checked By']}**")
                                st.markdown(f"- Time Taken: **{r['Check Time']}**")
                            with c2:
                                st.markdown("**📤 Bill Upload:**")
                                st.markdown(f"- Uploaded By: **{r['Uploaded By']}**")
                                st.markdown(f"- Time Taken: **{r['Upload Time']}**")
                                st.divider()
                                st.markdown("**📍 Stock Placement:**")
                                st.markdown(f"- Placed By: **{r['Placed By']}**")
                                st.markdown(f"- Time Taken: **{r['Place Time']}**")
                                st.divider()
                                st.markdown("**🔍 Final Cross Check:**")
                                st.markdown(f"- Result: **{r['Cross Check']}**")

                            # Show invoice image if available
                            reg_entry = next((t for t in register_entries 
                                if t.get("details",{}).get("bill_no","") == r["Bill No"]), None)
                            if reg_entry:
                                img_name = reg_entry.get("details",{}).get("invoice_image","")
                                if img_name:
                                    st.divider()
                                    st.markdown("**📸 Invoice Image:**")
                                    try:
                                        img_data = load_image_bytes(img_name)
                                        from PIL import Image
                                        import io as io_mod
                                        pil_img = Image.open(io_mod.BytesIO(img_data))
                                        st.image(pil_img, width='stretch')
                                        st.download_button(
                                            "🔍 Download Full Size",
                                            img_data,
                                            file_name=f"invoice_{r['Bill No']}.jpg",
                                            mime="image/jpeg",
                                            key=f"dl_inv_{r['Bill No']}"
                                        )
                                    except Exception:
                                        st.info(removed_photo_note(img_name) or "Image not available")

                    buf = io.BytesIO()
                    with pd.ExcelWriter(buf, engine="openpyxl") as w:
                        pipeline_df.to_excel(w, index=False)
                    st.download_button("⬇️ Download Excel", buf.getvalue(),
                        f"normal_orders_{no_date_str}.xlsx",
                        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                        key="no_excel")
                else:
                    st.info("No bills match selected filters!")

        else:
            st.subheader("🔄 Arrangement Pipeline View")
        c1,c2,c3 = st.columns(3)
        with c1:
            pipeline_date = st.date_input("Date", value=today_ist(), key="pipeline_date_tab")
        with c2:
            try:
                areas_resp = supabase.table("areas").select("name").eq("active", True).execute()
                area_list = ["All Areas"] + [a["name"] for a in areas_resp.data]
            except Exception:
                area_list = ["All Areas"]
            pipeline_area = st.selectbox("Area", area_list, key="pipeline_area_tab")
        with c3:
            pipeline_status = st.selectbox("Status", [
                "All","Pending","Picked Up - In Transit","Porter Booked",
                "Given to Porter - In Transit","Reached Warehouse",
                "Bill Cross Checked","Bill Uploaded","Stock Placed","Completed"
            ], key="pipeline_status_tab")

        try:
            pipeline_resp = supabase.table("arrangements").select("*")\
                .eq("order_placed_date", pipeline_date.strftime("%Y-%m-%d")).execute()
            pipeline_arrs = pipeline_resp.data if pipeline_resp.data else []
        except Exception as e:
            st.error(f"Error: {e}")
            pipeline_arrs = []

        if pipeline_area != "All Areas":
            pipeline_arrs = [a for a in pipeline_arrs if a.get("area","") == pipeline_area]
        if pipeline_status != "All":
            pipeline_arrs = [a for a in pipeline_arrs if a.get("status","") == pipeline_status]

        st.markdown(f"**{len(pipeline_arrs)} arrangements found**")

        for arr in pipeline_arrs:
            status  = arr.get("status","")
            urgency = arr.get("urgency","Normal")
            urgency_color = "🔴" if urgency == "Very Urgent" else "🟡" if urgency == "Urgent" else "🟢"

            steps = [
                ("Order Placed",      arr.get("order_placed_time",""), arr.get("order_by",""),                    True),
                ("Picked Up",         arr.get("pickup_time",""),       arr.get("pickup_by",""),                   arr.get("pickup_time","") != ""),
                ("Reached Warehouse", "",                              "",                                        status in ["Reached Warehouse","Bill Cross Checked","Bill Uploaded","Stock Placed","Completed"]),
                ("Bill Cross Checked",arr.get("cross_check_time",""), arr.get("cross_checked_by",""),            status in ["Bill Cross Checked","Bill Uploaded","Stock Placed","Completed"]),
                ("Bill Uploaded",     arr.get("bill_upload_time",""), arr.get("bill_uploaded_by",""),            status in ["Bill Uploaded","Stock Placed","Completed"]),
                ("Stock Placed",      arr.get("placement_time",""),   arr.get("placed_by",""),                   status in ["Stock Placed","Completed"]),
                ("Completed",         "",                              "",                                        status == "Completed"),
            ]

            with st.expander(f"{urgency_color} **#{arr.get('arrangement_no','')}** | {arr.get('distributor','')} | {arr.get('area','')} | **{status}**"):
                for step_name, step_time, step_by, done in steps:
                    if done:
                        time_val = f"— {step_time}" if step_time else ""
                        by_val   = f"— {step_by}" if step_by else ""
                        st.markdown(f"✅ **{step_name}** {time_val} {by_val}")
                    else:
                        st.markdown(f"⏳ {step_name}")

    if _nav == '📈 Performance':
        st.subheader("📈 Performance & CEO Dashboard")

        perf_tab1, perf_tab2 = st.tabs(["👤 Team Performance", "💼 CEO Dashboard"])

        with perf_tab1:
            st.subheader("👤 Individual Performance")

            c1,c2 = st.columns(2)
            with c1:
                perf_date = st.date_input("Date", value=today_ist(), key="perf_date_ind")
            with c2:
                try:
                    users_resp = supabase.table("app_users").select("*")\
                        .eq("active",True).neq("role","admin").execute()
                    person_list = [u["name"] for u in (users_resp.data or [])]
                    teams_dict  = {u["name"]: u["team"] for u in (users_resp.data or [])}
                except Exception:
                    person_list = []
                    teams_dict  = {}
                sel_person = st.selectbox("Select Person", person_list, key="perf_person")

            perf_date_str = perf_date.strftime("%Y-%m-%d")
            from datetime import timedelta
            yesterday_str = (perf_date - timedelta(days=1)).strftime("%Y-%m-%d")

            if sel_person:
                team = teams_dict.get(sel_person, "")

                # Complete day: attendance + every task (any team) + breaks + idle gaps
                st.markdown(f"#### 📋 Full Day — {sel_person}")
                show_person_day(sel_person, perf_date)
                st.divider()
                st.markdown(f"#### 📊 {team} task metrics")

                # Load today tasks
                try:
                    tasks_resp = supabase.table("daily_tasks").select("*")\
                        .eq("person", sel_person)\
                        .eq("date", perf_date_str).execute()
                    tasks = tasks_resp.data or []

                    # Load yesterday tasks
                    yest_resp = supabase.table("daily_tasks").select("*")\
                        .eq("person", sel_person)\
                        .eq("date", yesterday_str).execute()
                    yest_tasks = yest_resp.data or []
                except Exception:
                    tasks = []
                    yest_tasks = []

                if not tasks:
                    st.info(f"No tasks found for {sel_person} on {perf_date_str}!")
                else:
                    # ── PURCHASE TEAM METRICS ─────────────────────────────
                    if team == "Purchase":
                        task_config = {
                            "Purchase Order":       ("no_sku",     "SKUs"),
                            "Arrangement Order":    ("no_medicines","Medicines"),
                            "Purchase Return":      ("no_items",   "Items"),
                            "PharmaRack Search":    ("no_searched","Searched"),
                            "Bounce Medicine Study":("no_bounced", "Bounced"),
                        }

                    # ── STOCK TEAM METRICS ────────────────────────────────
                    elif team == "Stock":
                        task_config = {
                            "Register Entry":       ("no_items",   "Items"),
                            "Bill Cross Check":     ("no_items",   "Items"),
                            "Bill Upload":          ("no_items",   "Items"),
                            "Bill Upload (Arrangement)": ("no_items","Items"),
                            "Stock Placement":      ("no_medicines","Medicines"),
                            "Rack Cleaning":        ("no_racks",   "Racks"),
                            "Inventory Check":      ("no_items",   "Items"),
                        }

                    # ── CALL TEAM METRICS ─────────────────────────────────
                    elif team == "Call":
                        task_config = {
                            "Call Log":         ("calls_made",  "Calls"),
                            "Medicine Search":  ("no_searched", "Searched"),
                        }
                    else:
                        task_config = {}

                    # Build performance table
                    perf_rows = []
                    total_time  = 0
                    total_count = 0
                    total_skus  = 0

                    for task_type, (sku_field, sku_label) in task_config.items():
                        task_list = [t for t in tasks if t.get("task_type") == task_type]
                        if not task_list:
                            continue

                        count    = len(task_list)
                        duration = sum([int(float(t.get("duration_mins",0) or 0)) for t in task_list])
                        skus     = sum([int(float((t.get("details") or {}).get(sku_field,0) or 0)) for t in task_list])
                        avg_sku  = round(duration/skus, 2) if skus > 0 else 0

                        # Yesterday comparison
                        yest_list     = [t for t in yest_tasks if t.get("task_type") == task_type]
                        yest_duration = sum([int(float(t.get("duration_mins",0) or 0)) for t in yest_list])
                        yest_skus     = sum([int(float((t.get("details") or {}).get(sku_field,0) or 0)) for t in yest_list])
                        yest_avg      = round(yest_duration/yest_skus, 2) if yest_skus > 0 else None

                        # Trend
                        if avg_sku != "-" and yest_avg:
                            trend = "✅ Better" if float(avg_sku) < float(yest_avg) else "⚠️ Slower"
                        else:
                            trend = "-"

                        total_time  += duration
                        total_count += count
                        total_skus  += skus

                        perf_rows.append({
                            "Task": task_type,
                            f"Count": count,
                            "Total Time (mins)": duration,
                            f"{sku_label}": skus,
                            "Avg/SKU (mins)": avg_sku,
                            "Yesterday Avg": yest_avg or "",
                            "Trend": trend
                        })

                    if perf_rows:
                        # Summary metrics
                        overall_avg = round(total_time/total_skus, 2) if total_skus > 0 else 0
                        c1,c2,c3,c4 = st.columns(4)
                        with c1: st.metric(f"👤 {sel_person}", team)
                        with c2: st.metric("⏱️ Total Time", f"{total_time} mins")
                        with c3: st.metric("📋 Total Tasks", total_count)
                        with c4: st.metric("📦 Total SKUs", total_skus)

                        st.divider()

                        # Performance table
                        perf_df = pd.DataFrame(perf_rows)
                        st.dataframe(perf_df, width='stretch')

                        # Total row
                        st.markdown(f"**📊 Overall Avg/SKU: {overall_avg} mins**")

                        # Bar chart - time per task
                        st.divider()
                        st.markdown("**⏱️ Time Distribution:**")
                        chart_df = pd.DataFrame([
                            {"Task": r["Task"], "Minutes": r["Total Time (mins)"]}
                            for r in perf_rows
                        ]).set_index("Task")
                        st.bar_chart(chart_df)

                        # Trend analysis
                        st.divider()
                        st.markdown("**📈 Trend vs Yesterday:**")
                        for r in perf_rows:
                            if r["Trend"] != "-":
                                st.markdown(f"**{r['Task']}**: Today {r['Avg/SKU (mins)']} mins/SKU | Yesterday {r['Yesterday Avg']} mins/SKU | {r['Trend']}")
                    else:
                        st.caption(f"No {team} team tasks for {sel_person} on this day — see the Full Day table above for everything else.")

        with perf_tab2:
            st.subheader("📈 CEO Dashboard")

        # Date and filters
        c1,c2,c3 = st.columns(3)
        with c1:
            dash_date = st.date_input("Date", value=today_ist(), key="dash_date")
        with c2:
            try:
                areas_resp = supabase.table("areas").select("name").eq("active",True).execute()
                area_list = ["All Areas"] + [a["name"] for a in (areas_resp.data or [])]
            except Exception:
                area_list = ["All Areas"]
            dash_area = st.selectbox("Area", area_list, key="dash_area")
        with c3:
            try:
                users_resp = supabase.table("app_users").select("name").eq("team","Stock").eq("active",True).execute()
                person_list = ["All Persons"] + [u["name"] for u in (users_resp.data or [])]
            except Exception:
                person_list = ["All Persons"]
            dash_person = st.selectbox("Person", person_list, key="dash_person")

        dash_date_str = dash_date.strftime("%Y-%m-%d")

        try:
            # Load all tasks for selected date
            tasks_resp = supabase.table("daily_tasks").select("*").eq("date", dash_date_str).execute()
            all_tasks = tasks_resp.data or []

            # Load arrangements
            arr_resp = supabase.table("arrangements").select("*").eq("order_placed_date", dash_date_str).execute()
            arrangements = arr_resp.data or []

        except Exception as e:
            st.error(f"Error: {e}")
            all_tasks = []
            arrangements = []

        # Filter tasks
        reg_tasks   = [t for t in all_tasks if t.get("task_type") == "Register Entry"]
        cross_tasks = [t for t in all_tasks if t.get("task_type") == "Bill Cross Check"]
        upload_tasks= [t for t in all_tasks if t.get("task_type") in ["Bill Upload","Bill Upload (Arrangement)"]]
        place_tasks = [t for t in all_tasks if t.get("task_type") == "Stock Placement"]

        # Apply area filter
        if dash_area != "All Areas":
            arrangements = [a for a in arrangements if a.get("area","") == dash_area]

        # Apply person filter
        if dash_person != "All Persons":
            reg_tasks    = [t for t in reg_tasks    if t.get("person") == dash_person]
            cross_tasks  = [t for t in cross_tasks  if t.get("person") == dash_person]
            upload_tasks = [t for t in upload_tasks if t.get("person") == dash_person]
            place_tasks  = [t for t in place_tasks  if t.get("person") == dash_person]

        # ── SECTION 1 — TODAY'S RECEIPTS ─────────────────────────────────────
        st.markdown("### 📥 Today's Receipts")

        total_bills   = len(reg_tasks)
        total_skus    = sum([int(float((t.get("details") or {}).get("no_items",0) or 0)) for t in reg_tasks])
        total_amount  = sum([float((t.get("details") or {}).get("bill_amount",0) or 0) for t in reg_tasks])

        # Time calculations
        cross_dur  = sum([int(float(t.get("duration_mins",0) or 0)) for t in cross_tasks])
        upload_dur = sum([int(float(t.get("duration_mins",0) or 0)) for t in upload_tasks])
        place_dur  = sum([int(float(t.get("duration_mins",0) or 0)) for t in place_tasks])

        avg_cross  = round(cross_dur/len(cross_tasks), 1)  if cross_tasks  else 0
        avg_upload = round(upload_dur/len(upload_tasks), 1) if upload_tasks else 0
        avg_place  = round(place_dur/len(place_tasks), 1)  if place_tasks  else 0

        c1,c2,c3 = st.columns(3)
        with c1:
            st.metric("📋 Bills Received", total_bills)
            st.metric("📦 Total SKUs", total_skus)
            st.metric("💰 Total Amount", f"₹{total_amount:,.0f}")
        with c2:
            st.metric("⏱️ Total Check Time", f"{cross_dur} mins")
            st.metric("⏱️ Total Upload Time", f"{upload_dur} mins")
            st.metric("⏱️ Total Place Time", f"{place_dur} mins")
        with c3:
            st.metric("📊 Avg Check/Bill", f"{avg_cross} mins")
            st.metric("📊 Avg Upload/Bill", f"{avg_upload} mins")
            st.metric("📊 Avg Place/Bill", f"{avg_place} mins")

        st.divider()

        # ── SECTION 2 — PENDING WORK ──────────────────────────────────────────
        st.markdown("### ⏳ Pending Work")

        # Count pending at each stage
        reached_wh    = [a for a in arrangements if a.get("status") == "Reached Warehouse"]
        cross_checked = [a for a in arrangements if a.get("status") == "Bill Cross Checked"]
        bill_uploaded = [a for a in arrangements if a.get("status") == "Bill Uploaded"]
        stock_placed  = [a for a in arrangements if a.get("status") == "Stock Placed" and a.get("cross_check_status") == "Pending"]

        # Normal orders pending
        normal_cross_pending  = [t for t in all_tasks if t.get("task_type") == "Register Entry" and not any(c.get("details",{}).get("bill_no","") == t.get("details",{}).get("bill_no","") for c in cross_tasks)]
        normal_upload_pending = [t for t in cross_tasks if not t.get("details",{}).get("arrangement_no","") and not t.get("details",{}).get("bill_uploaded")]
        normal_place_pending  = [t for t in upload_tasks if not t.get("details",{}).get("arrangement_no","") and not t.get("details",{}).get("placement_done")]

        p1,p2,p3,p4 = st.columns(4)
        with p1:
            total_cross_pending = len(reached_wh) + len(normal_cross_pending)
            st.metric("✔️ Cross Check Pending", total_cross_pending)
        with p2:
            total_upload_pending = len(cross_checked) + len(normal_upload_pending)
            st.metric("📤 Upload Pending", total_upload_pending)
        with p3:
            total_place_pending = len(bill_uploaded) + len(normal_place_pending)
            st.metric("📍 Placement Pending", total_place_pending)
        with p4:
            st.metric("🔍 Final Check Pending", len(stock_placed))

        st.divider()

        # ── SECTION 3 — PERSON WISE PERFORMANCE ──────────────────────────────
        st.markdown("### 👤 Person Wise Performance")

        # Get all stock team members
        try:
            stock_users = supabase.table("app_users").select("name").eq("team","Stock").eq("active",True).execute()
            stock_names = [u["name"] for u in (stock_users.data or [])]
        except Exception:
            stock_names = list(set([t.get("person","") for t in cross_tasks + upload_tasks + place_tasks]))

        person_rows = []
        for person in stock_names:
            if dash_person != "All Persons" and person != dash_person:
                continue

            p_cross  = [t for t in cross_tasks  if t.get("person") == person]
            p_upload = [t for t in upload_tasks if t.get("person") == person]
            p_place  = [t for t in place_tasks  if t.get("person") == person]

            p_cross_dur  = sum([int(float(t.get("duration_mins",0) or 0)) for t in p_cross])
            p_upload_dur = sum([int(float(t.get("duration_mins",0) or 0)) for t in p_upload])
            p_place_dur  = sum([int(float(t.get("duration_mins",0) or 0)) for t in p_place])

            person_rows.append({
                "Person": person,
                "Bills Checked": len(p_cross),
                "Total Check(mins)": p_cross_dur,
                "Avg Check/Bill": round(p_cross_dur/len(p_cross),1) if p_cross else 0,
                "Bills Uploaded": len(p_upload),
                "Total Upload(mins)": p_upload_dur,
                "Avg Upload/Bill": round(p_upload_dur/len(p_upload),1) if p_upload else 0,
                "Bills Placed": len(p_place),
                "Total Place(mins)": p_place_dur,
                "Avg Place/Bill": round(p_place_dur/len(p_place),1) if p_place else 0,
            })

        if person_rows:
            person_df = pd.DataFrame(person_rows)
            st.dataframe(person_df, width='stretch')

            # Team summary
            st.markdown("**📊 Team Summary:**")
            s1,s2,s3 = st.columns(3)
            with s1:
                st.metric("Total Bills Checked", sum([r["Bills Checked"] for r in person_rows]))
                st.metric("Team Avg Check/Bill", f"{round(sum([p_cross_dur for p_cross_dur in [r['Total Check(mins)'] for r in person_rows] if p_cross_dur > 0]) / max(sum([r['Bills Checked'] for r in person_rows]),1), 1)} mins")
            with s2:
                st.metric("Total Bills Uploaded", sum([r["Bills Uploaded"] for r in person_rows]))
                st.metric("Team Avg Upload/Bill", f"{round(sum([r['Total Upload(mins)'] for r in person_rows]) / max(sum([r['Bills Uploaded'] for r in person_rows]),1), 1)} mins")
            with s3:
                st.metric("Total Bills Placed", sum([r["Bills Placed"] for r in person_rows]))
                st.metric("Team Avg Place/Bill", f"{round(sum([r['Total Place(mins)'] for r in person_rows]) / max(sum([r['Bills Placed'] for r in person_rows]),1), 1)} mins")
        else:
            st.info("No stock team data for selected filters!")

        st.divider()

        # ── SECTION 4 — AREA WISE SUMMARY ────────────────────────────────────
        st.markdown("### 📍 Area Wise Summary")
        try:
            area_data = {}
            for arr in arrangements:
                area = arr.get("area","Unknown")
                if area not in area_data:
                    area_data[area] = {"bills": 0, "skus": 0, "amount": 0, "pending": 0}
                area_data[area]["bills"] += 1
                area_data[area]["skus"]  += int(float(arr.get("no_medicines",0) or 0))
                if arr.get("status") not in ["Completed","Stock Placed"]:
                    area_data[area]["pending"] += 1

            if area_data:
                area_rows = [{"Area": k, "Bills": v["bills"], "SKUs": v["skus"], "Pending": v["pending"]} for k,v in area_data.items()]
                st.dataframe(pd.DataFrame(area_rows), width='stretch')
            else:
                st.info("No area data available!")
        except Exception as e:
            st.error(f"Error: {e}")

        st.divider()

        st.subheader("📈 CEO Dashboard")

        # Date selector
        ceo_date = st.date_input("Select Date", value=today_ist(), key="ceo_date")
        ceo_date_str = ceo_date.strftime("%Y-%m-%d")

        try:
            # Load all data
            tasks_resp = supabase.table("daily_tasks").select("*").eq("date", ceo_date_str).execute()
            tasks = tasks_resp.data or []
            arr_resp = supabase.table("arrangements").select("*").eq("order_placed_date", ceo_date_str).execute()
            arrangements = arr_resp.data or []
        except Exception as e:
            st.error(f"Error: {e}")
            tasks = []
            arrangements = []

        # ── FINANCIAL OVERVIEW ────────────────────────────────────────────────
        st.markdown("### 💰 Financial Overview")
        reg_entries = [t for t in tasks if t.get("task_type") == "Register Entry"]
        
        total_amount = sum([float((t.get("details") or {}).get("bill_amount",0) or 0) for t in reg_entries])
        arr_amount   = sum([float((t.get("details") or {}).get("bill_amount",0) or 0) for t in reg_entries if (t.get("details") or {}).get("order_type") == "Arrangement"])
        normal_amount = sum([float((t.get("details") or {}).get("bill_amount",0) or 0) for t in reg_entries if (t.get("details") or {}).get("order_type") == "Normal Order"])
        porter_payments = supabase.table("porter_bookings").select("*").eq("date", ceo_date_str).eq("status","Payment Done").execute()
        porter_cost = sum([float(p.get("porter_cost",0) or 0) for p in (porter_payments.data or [])])

        c1,c2,c3,c4 = st.columns(4)
        with c1: st.metric("💰 Total Purchase", f"₹{total_amount:,.0f}")
        with c2: st.metric("📋 Arrangement", f"₹{arr_amount:,.0f}")
        with c3: st.metric("🛒 Normal Orders", f"₹{normal_amount:,.0f}")
        with c4: st.metric("🚛 Porter Cost", f"₹{porter_cost:,.0f}")

        st.divider()

        # ── WEEK ON WEEK TRENDS ───────────────────────────────────────────────
        st.markdown("### 📈 Week on Week Trends")
        try:
            from datetime import timedelta
            
            # This week vs last week
            this_week_start = (ceo_date - timedelta(days=ceo_date.weekday())).strftime("%Y-%m-%d")
            last_week_start = (ceo_date - timedelta(days=ceo_date.weekday()+7)).strftime("%Y-%m-%d")
            last_week_end   = (ceo_date - timedelta(days=ceo_date.weekday()+1)).strftime("%Y-%m-%d")

            this_week_tasks = supabase.table("daily_tasks").select("*")                .gte("date", this_week_start)                .lte("date", ceo_date_str).execute()
            last_week_tasks = supabase.table("daily_tasks").select("*")                .gte("date", last_week_start)                .lte("date", last_week_end).execute()

            this_week_arr = supabase.table("arrangements").select("*")                .gte("order_placed_date", this_week_start)                .lte("order_placed_date", ceo_date_str).execute()
            last_week_arr = supabase.table("arrangements").select("*")                .gte("order_placed_date", last_week_start)                .lte("order_placed_date", last_week_end).execute()

            this_week_count = len(this_week_tasks.data or [])
            last_week_count = len(last_week_tasks.data or [])
            this_arr_count  = len(this_week_arr.data or [])
            last_arr_count  = len(last_week_arr.data or [])

            task_delta = this_week_count - last_week_count
            arr_delta  = this_arr_count - last_arr_count

            c1,c2,c3,c4 = st.columns(4)
            with c1: st.metric("📋 This Week Tasks", this_week_count, f"{'+' if task_delta>=0 else ''}{task_delta} vs last week")
            with c2: st.metric("📦 This Week Arrangements", this_arr_count, f"{'+' if arr_delta>=0 else ''}{arr_delta} vs last week")
            with c3:
                this_week_amount = sum([float((t.get("details") or {}).get("bill_amount",0) or 0) for t in (this_week_tasks.data or []) if t.get("task_type")=="Register Entry"])
                last_week_amount = sum([float((t.get("details") or {}).get("bill_amount",0) or 0) for t in (last_week_tasks.data or []) if t.get("task_type")=="Register Entry"])
                amount_delta = this_week_amount - last_week_amount
                st.metric("💰 This Week Purchase", f"₹{this_week_amount:,.0f}", f"{'+'if amount_delta>=0 else ''}₹{amount_delta:,.0f}")
            with c4:
                # Avg processing time this week
                pipeline_times = []
                for arr in (this_week_arr.data or []):
                    try:
                        from datetime import datetime as dt
                        o = dt.strptime(arr.get("order_placed_time",""), "%I:%M %p")
                        u = dt.strptime(arr.get("bill_upload_time",""), "%I:%M %p")
                        diff = int((u-o).total_seconds()/60)
                        if diff > 0:
                            pipeline_times.append(diff)
                    except Exception:
                        pass
                avg_pipeline = round(sum(pipeline_times)/len(pipeline_times),0) if pipeline_times else 0
                st.metric("⏱️ Avg Pipeline Time", f"{int(avg_pipeline)} mins")

        except Exception as e:
            st.error(f"Trends error: {e}")

        st.divider()

        # ── DISTRIBUTOR PERFORMANCE ───────────────────────────────────────────
        st.markdown("### 🏪 Distributor Performance")
        try:
            # Count orders and issues per distributor
            dist_data = {}
            for t in tasks:
                if t.get("task_type") in ["Register Entry","Bill Upload","Bill Cross Check"]:
                    d = t.get("details",{}) or {}
                    dist = d.get("distributor","")
                    if not dist:
                        continue
                    if dist not in dist_data:
                        dist_data[dist] = {
                            "orders": 0, "amount": 0,
                            "near_expiry": 0, "damaged": 0,
                            "contra": 0, "wrong_batch": 0,
                            "shortage": 0
                        }
                    if t.get("task_type") == "Register Entry":
                        dist_data[dist]["orders"] += 1
                        dist_data[dist]["amount"] += float(d.get("bill_amount",0) or 0)
                    if t.get("task_type") == "Bill Cross Check":
                        dist_data[dist]["near_expiry"] += int(float(d.get("near_expiry",0) or 0))
                        dist_data[dist]["damaged"]     += int(float(d.get("damaged",0) or 0))
                        dist_data[dist]["contra"]      += int(float(d.get("contra",0) or 0))
                        dist_data[dist]["wrong_batch"] += int(float(d.get("wrong_batch",0) or 0))
                        dist_data[dist]["shortage"]    += int(float(d.get("shortage",0) or 0))

            if dist_data:
                dist_rows = []
                for dist, data in dist_data.items():
                    total_issues = data["near_expiry"] + data["damaged"] + data["contra"] + data["wrong_batch"] + data["shortage"]
                    status = "🔴 Issues" if total_issues > 0 else "✅ Good"
                    dist_rows.append({
                        "Distributor": dist,
                        "Orders": data["orders"],
                        "Amount(₹)": f"₹{data['amount']:,.0f}",
                        "Near Expiry": data["near_expiry"],
                        "Damaged": data["damaged"],
                        "Contra": data["contra"],
                        "Wrong Batch": data["wrong_batch"],
                        "Shortage": data["shortage"],
                        "Total Issues": total_issues,
                        "Status": status
                    })
                dist_df = pd.DataFrame(dist_rows).sort_values("Total Issues", ascending=False)
                st.dataframe(dist_df, width='stretch')
            else:
                st.info("No distributor data for selected date!")
        except Exception as e:
            st.error(f"Distributor error: {e}")

        st.divider()

        # ── TEAM PRODUCTIVITY ─────────────────────────────────────────────────
        st.markdown("### 👥 Team Productivity")
        if tasks:
            tasks_df = pd.DataFrame(tasks)
            person_summary = tasks_df.groupby(["person","team"]).agg(
                Tasks=("task_type","count")
            ).reset_index()
            person_summary["Total_mins"] = person_summary.apply(
                lambda row: sum([int(float(t.get("duration_mins",0) or 0)) 
                    for t in tasks if t.get("person")==row["person"]]), axis=1)
            person_summary = person_summary.sort_values("Tasks", ascending=False)
            st.dataframe(person_summary, width='stretch')
            st.bar_chart(tasks_df.groupby("person").size())
        else:
            st.info("No team data for selected date!")

        st.divider()

        st.subheader("📈 Performance Dashboard")
        perf_date = st.date_input("Date", value=today_ist(), key="perf_date_tab")
        perf_date_str = perf_date.strftime("%Y-%m-%d")
        try:
            tasks_resp = supabase.table("daily_tasks").select("*").eq("date", perf_date_str).execute()
            tasks = tasks_resp.data if tasks_resp.data else []
        except Exception:
            tasks = []

        if not tasks:
            st.info("No data for selected date!")
        else:
            tasks_df = pd.DataFrame(tasks)
            st.markdown("### 👥 Team Performance")
            person_summary = tasks_df.groupby(["person","team","task_type"]).size().reset_index(name="count")
            st.dataframe(person_summary, width='stretch')
            st.bar_chart(tasks_df.groupby("person").size())

    if _nav == '📝 Submit Entry':
        st.subheader("📝 Submit Entry")
        tabs_entry = st.tabs(["🛒 Purchase","📋 Arrangement","🧾 Bill Upload",
                              "📞 Call","🚚 Delivery","🚛 Book Porter",
                              "🚛 Handover","📦 Receive","💰 Payment","✏️ Other"])
        with tabs_entry[0]: form_purchase_order()
        with tabs_entry[1]: form_arrangement()
        with tabs_entry[2]: form_bill_upload()
        with tabs_entry[3]: form_call_log()
        with tabs_entry[4]: form_delivery()
        with tabs_entry[5]: form_book_porter()
        with tabs_entry[6]: form_porter_handover()
        with tabs_entry[7]: form_porter_receive()
        with tabs_entry[8]: form_porter_payment()
        with tabs_entry[9]: form_other_task()

    if _nav == '👥 Settings':
        st.subheader("👥 User Management")
        tab_u1, tab_u2 = st.tabs(["➕ Add User","👥 Manage Users"])
        with tab_u1:
            with st.form("add_user_form", clear_on_submit=True):
                c1,c2 = st.columns(2)
                with c1:
                    new_username = st.text_input("Username *")
                    new_name     = st.text_input("Full Name *")
                    new_password = st.text_input("Password *")
                with c2:
                    new_team = st.selectbox("Team", ["Purchase","Stock","Call","Delivery","Admin"], key="nu_team")
                    new_role = st.selectbox("Role", ["user","manager","admin"], key="nu_role",
                                            help="manager = own work + Team View (no settings/passwords)")
                    new_phone = st.text_input("Mobile (for WhatsApp reminders)", placeholder="98XXXXXXXX")
                if st.form_submit_button("Add User ✅", type="primary", width='stretch'):
                    if not new_username or not new_name or not new_password:
                        st.error("Fill all fields!")
                    else:
                        try:
                            check = supabase.table("app_users").select("id").eq("username", new_username).execute()
                            if check.data:
                                st.error(f"❌ Username already exists!")
                            else:
                                supabase.table("app_users").insert({
                                    "username": new_username.strip(), "password": new_password,
                                    "name": new_name, "team": new_team,
                                    "role": new_role, "active": True,
                                    **({"phone": new_phone.strip()} if new_phone.strip() else {})
                                }).execute()
                                load_users.clear()
                                st.success(f"✅ {new_name} added!")
                                st.rerun()
                        except Exception as e:
                            st.error(f"Error: {e}")
        with tab_u2:
            try:
                users_resp = supabase.table("app_users").select("*").order("team").execute()
                with st.expander("📱 Mobile numbers & roles", expanded=False):
                    act_users = [u for u in (users_resp.data or []) if u.get("active") and u.get("role") != "admin"]
                    if act_users and "phone" not in act_users[0]:
                        st.warning("Run the new line in attendance_setup.sql in Supabase first (adds the phone column).")
                    elif act_users:
                        ph_df = pd.DataFrame([{"id": u["id"], "Name": u["name"], "Team": u.get("team",""),
                                               "Mobile": u.get("phone") or "", "Role": u.get("role") or "user"} for u in act_users])
                        ph_ed = st.data_editor(ph_df, key="phone_editor", hide_index=True, width='stretch',
                                               disabled=["Name","Team"],
                                               column_config={"id": None,
                                                              "Role": st.column_config.SelectboxColumn("Role", options=["user","manager"], required=True,
                                                                        help="manager = own work + 👥 Team View")})
                        if st.button("💾 Save", key="save_phones", type="primary"):
                            old = {u["id"]: (u.get("phone") or "", u.get("role") or "user") for u in act_users}
                            done, failed = [], []
                            for _, r in ph_ed.iterrows():
                                uid = int(r["id"])
                                new = (str(r["Mobile"] or "").strip(), str(r["Role"] or "user"))
                                if new == old.get(uid, ("", "user")):
                                    continue
                                try:
                                    supabase.table("app_users").update({"phone": new[0], "role": new[1]}).eq("id", uid).execute()
                                    chk = supabase.table("app_users").select("role,phone").eq("id", uid).execute().data or []
                                    if chk and (chk[0].get("role") or "user") == new[1]:
                                        done.append(r["Name"])
                                    else:
                                        failed.append(f"{r['Name']}: database did not accept the change")
                                except Exception as e:
                                    failed.append(f"{r['Name']}: {e}")
                            load_users.clear()
                            if done:
                                st.success(f"✅ Saved: {', '.join(done)} — a new role applies after that person logs out and in again")
                            for f in failed:
                                st.error(f"❌ {f} — run fix_roles.sql in Supabase (see Claude's note), then try again")
                            if not done and not failed:
                                st.info("Nothing changed — edit a cell first, then Save.")
                show_extra_teams_admin(users_resp.data or [])
                if users_resp.data:
                    for u in users_resp.data:
                        c1,c2,c3,c4,c5 = st.columns([2,2,2,1,1])
                        with c1: st.markdown(f"👤 **{u['name']}**")
                        with c2: st.markdown(f"🔑 `{u['username']}`")
                        with c3: st.markdown(f"🔒 `{u['password']}`")
                        with c4: st.markdown("✅" if u.get("active") else "❌")
                        with c5:
                            if u.get("active"):
                                if st.button("Deactivate", key=f"deact_{u['id']}"):
                                    supabase.table("app_users").update({"active": False}).eq("id", u["id"]).execute()
                                    load_users.clear()
                                    st.rerun()
                            else:
                                if st.button("Activate", key=f"act_{u['id']}"):
                                    supabase.table("app_users").update({"active": True}).eq("id", u["id"]).execute()
                                    load_users.clear()
                                    st.rerun()
            except Exception as e:
                st.error(f"Error: {e}")

        st.divider()
        st.subheader("🏭 Warehouses, Areas & Distributors")
        tab_w, tab_a, tab_d = st.tabs(["🏭 Warehouses","📍 Areas","🚚 Distributors"])
        with tab_d:
            show_distributors_admin("adm_dist")
        with tab_w:
            c1,c2 = st.columns(2)
            with c1:
                with st.form("add_warehouse", clear_on_submit=True):
                    wh_name = st.text_input("Warehouse Name *")
                    wh_loc  = st.text_input("Location")
                    if st.form_submit_button("Add ✅"):
                        if wh_name:
                            try:
                                supabase.table("warehouses").insert({"name": wh_name, "location": wh_loc}).execute()
                                st.success(f"✅ {wh_name} added!")
                                st.rerun()
                            except Exception as e:
                                st.error(f"Error: {e}")
            with c2:
                try:
                    wh_resp = supabase.table("warehouses").select("*").eq("active", True).execute()
                    if wh_resp.data:
                        for wh in wh_resp.data:
                            c1,c2 = st.columns([3,1])
                            with c1: st.markdown(f"🏭 **{wh['name']}**")
                            with c2:
                                if st.button("Remove", key=f"rm_wh_{wh['id']}"):
                                    supabase.table("warehouses").update({"active": False}).eq("id", wh["id"]).execute()
                                    st.rerun()
                except Exception as e:
                    st.error(f"Error: {e}")
        with tab_a:
            c1,c2 = st.columns(2)
            with c1:
                with st.form("add_area", clear_on_submit=True):
                    area_name = st.text_input("Area Name *")
                    if st.form_submit_button("Add ✅"):
                        if area_name:
                            try:
                                supabase.table("areas").insert({"name": area_name}).execute()
                                load_areas.clear()
                                st.success(f"✅ {area_name} added!")
                                st.rerun()
                            except Exception as e:
                                st.error(f"Error: {e}")
            with c2:
                try:
                    area_resp = supabase.table("areas").select("*").eq("active", True).execute()
                    if area_resp.data:
                        for area in area_resp.data:
                            c1,c2 = st.columns([3,1])
                            with c1: st.markdown(f"📍 **{area['name']}**")
                            with c2:
                                if st.button("Remove", key=f"rm_area_{area['id']}"):
                                    supabase.table("areas").update({"active": False}).eq("id", area["id"]).execute()
                                    load_areas.clear()
                                    st.rerun()
                except Exception as e:
                    st.error(f"Error: {e}")

    if _nav == '📥 Reports':
        st.subheader("📥 Download Reports")
        c1,c2,c3 = st.columns(3)
        with c1: sel_team   = st.selectbox("Team", ["All","Purchase","Stock","Call","Delivery"], key="r_team")
        with c2: date_f     = st.selectbox("Period", ["Today","Yesterday","Last 7 Days","Last 30 Days","All Time"], key="r_date")
        with c3: sel_person = st.text_input("Person Name", placeholder="Leave blank for all", key="r_person")

        try:
            from datetime import timedelta
            _today = today_ist()
            _from = {"Today": _today, "Yesterday": _today - timedelta(days=1),
                     "Last 7 Days": _today - timedelta(days=7), "Last 30 Days": _today - timedelta(days=30)}.get(date_f)
            _to = _today - timedelta(days=1) if date_f == "Yesterday" else _today
            def _rep_filter(q):
                if _from:
                    q = q.gte("date", _from.strftime("%Y-%m-%d")).lte("date", _to.strftime("%Y-%m-%d"))
                if sel_team != "All":
                    q = q.eq("team", sel_team)
                return q
            all_rows  = fetch_all("daily_tasks", _rep_filter)   # all rows, not just the first 1000
            filtered  = pd.DataFrame(all_rows) if all_rows else pd.DataFrame()
            if not filtered.empty:
                filtered["date"] = pd.to_datetime(filtered["date"])
                if sel_team != "All": filtered = filtered[filtered["team"]==sel_team]
                if sel_person: filtered = filtered[filtered["person"].str.contains(sel_person, case=False)]
                if date_f == "Today": filtered = filtered[filtered["date"]==pd.to_datetime(date_str())]
                elif date_f == "Yesterday": filtered = filtered[filtered["date"]==pd.to_datetime(date_str())-pd.Timedelta(days=1)]
                elif date_f == "Last 7 Days": filtered = filtered[filtered["date"]>=pd.Timestamp.now()-pd.Timedelta(days=7)]
                elif date_f == "Last 30 Days": filtered = filtered[filtered["date"]>=pd.Timestamp.now()-pd.Timedelta(days=30)]
                st.markdown(f"**{len(filtered)} tasks found**")
                st.dataframe(filtered.sort_values("date", ascending=False), width='stretch')
                c1,c2 = st.columns(2)
                with c1:
                    buf = io.BytesIO()
                    with pd.ExcelWriter(buf, engine="openpyxl") as w:
                        filtered.to_excel(w, index=False)
                    st.download_button("⬇️ Excel", buf.getvalue(),
                        f"rapidsurge_{date_str()}.xlsx",
                        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                        key="dl_excel_tab")
                with c2:
                    st.download_button("⬇️ CSV", filtered.to_csv(index=False).encode(),
                        f"rapidsurge_{date_str()}.csv", "text/csv", key="dl_csv_tab")
        except Exception as e:
            st.error(f"Error: {e}")




