def main():
    _timer_save_done()      # placeholder of a task finished in the previous run (form saved elsewhere)
    if not st.session_state.logged_in:
        show_login()
    else:
        if st.session_state.role != "admin":
            init_work_mode()
        show_sidebar()
        if st.session_state.role == "admin":
            show_admin_page()
        else:
            show_user_page()

if __name__ == "__main__":
    main()
